/* 자동 생성 — 개념카드/굽기.py. 손으로 고치지 말 것 */
window.CARD={"물류정책기본법":{"묶음":[{"머리":"정의(제2조)","줄":[{"t":"물류사업: 화주의 수요에 따라 유상으로 물류활동을 영위하는 것을 업으로 하는 것. 화물운송업·물류시설운영업·물류서비스업·종합물류서비스업 4종.","src":"물류정책기본법 제2조제1항제2호"},{"t":"화물운송업: 자동차·철도차량·선박·항공기 또는 파이프라인 등 운송수단으로 화물을 운송하는 사업(파이프라인 운송도 화물운송업).","src":"물류정책기본법 제2조제1항제2호가목"},{"t":"물류시설운영업: 물류터미널이나 창고 등 물류시설을 운영하는 사업.","src":"물류정책기본법 제2조제1항제2호나목"},{"t":"물류서비스업: 화물운송의 주선, 물류장비의 임대, 물류정보의 처리 또는 물류컨설팅 등의 업무를 하는 사업. 종합물류서비스업은 가~다목 사업을 종합적·복합적으로 영위하는 사업.","src":"물류정책기본법 제2조제1항제2호다·라목"},{"t":"물류시설: 화물의 운송·보관·하역 시설 / 가공·조립·분류·수리·포장·상표부착·판매·정보통신 등 부가 시설 / 물류의 공동화·자동화·정보화 시설 / 이 시설들이 모여 있는 물류터미널 및 물류단지.","src":"물류정책기본법 제2조제1항제4호"},{"t":"물류공동화: 물류기업이나 화주기업이 물류활동의 효율성을 높이기 위해 시설·장비·인력·조직·정보망 등을 공동으로 이용하는 것.","src":"물류정책기본법 제2조제1항제5호"},{"t":"물류표준화 대상: 시설·장비의 종류·형상·치수·구조 / 포장의 종류·형상·치수·구조·방법 / 물류용어·물류회계·물류 관련 전자문서 등.","src":"물류정책기본법 제2조제1항제7호"},{"t":"단위물류정보망: 기능별 또는 지역별로 관련 행정기관·물류기업 및 그 거래처를 연결하는 일련의 물류정보체계.","src":"물류정책기본법 제2조제1항제8호"},{"t":"제3자물류: 화주가 대통령령으로 정하는 특수관계에 있지 아니한 물류기업에 물류활동의 일부 또는 전부를 위탁하는 것.","src":"물류정책기본법 제2조제1항제10호"},{"t":"국제물류주선업: 타인의 수요에 따라 자기의 명의와 계산으로 타인의 물류시설·장비 등을 이용하여 수출입화물의 물류를 주선하는 사업.","src":"물류정책기본법 제2조제1항제11호"},{"t":"물류보안: 공항·항만과 물류시설에 폭발물·무기류 등 위해물품을 은닉·반입하는 행위, 물류시설·장비·인력·조직·정보망·화물 등에 위해를 가할 목적의 불법행위를 사전에 방지하기 위한 조치.","src":"물류정책기본법 제2조제1항제13호"}]},{"머리":"물류사업의 범위(시행령 별표 1)","줄":[{"t":"화물운송업: 육상(화물자동차운송사업·화물자동차운송가맹사업·철도사업) / 해상(외항정기·외항부정기·내항화물운송사업) / 항공(정기항공운송·부정기항공운송·상업서류송달업) / 파이프라인운송업.","src":"물류정책기본법 시행령 별표 1"},{"t":"물류시설운영업: 창고업(일반창고업·냉장 및 냉동 창고업·농수산물 창고업·위험물품보관업·그 밖의 창고업, 공동집배송센터운영업 포함) / 물류터미널운영업.","src":"물류정책기본법 시행령 별표 1"},{"t":"물류서비스업 세분류: 화물취급업(하역업 포함) / 화물주선업(국제물류주선업·화물자동차운송주선사업) / 물류장비임대업 / 물류정보처리업 / 물류컨설팅업 / 해운부대사업(해운대리점업·해운중개업·선박관리업) / 항만운송관련업 / 항만운송사업.","src":"물류정책기본법 시행령 별표 1"},{"t":"항만운송관련업: 항만용역업·선용품공급업·선박연료공급업·선박수리업·컨테이너 수리업·예선업. 운반·적치·하역장비 임대업은 물류장비임대업에 속한다.","src":"물류정책기본법 시행령 별표 1"},{"t":"항만운송사업: 항만하역사업·검수사업·감정사업·검량사업.","src":"물류정책기본법 시행령 별표 1"},{"t":"항공화물운송업에는 상업서류송달업이 들어간다. 물류시설운영업에는 위험물품보관업(창고업 세세분류)이 들어간다. 물류장비의 폐기물 처리는 물류사업 범위에 없다.","src":"기출 2021-1, 2025-1"}]},{"머리":"물류현황조사(제7~10조)","줄":[{"t":"물류현황조사 주체: 국토교통부장관 또는 해양수산부장관. 관계 행정기관의 장과 미리 협의한 후 조사. 국가교통조사와 중복되지 않게 한다.","src":"물류정책기본법 제7조제1항"},{"t":"조사 항목: 물동량 발생현황과 이동경로, 물류시설·장비 현황과 이용실태, 물류인력·물류체계 현황, 물류비, 물류산업·국제물류 현황 등.","src":"물류정책기본법 제7조제1항"},{"t":"자료제출·직접조사 요청 대상: 관계 중앙행정기관의 장, 시·도지사, 물류기업 및 이 법에 따라 지원을 받는 기업·단체 등. 요청받은 자는 특별한 사정이 없으면 따라야 한다.","src":"물류정책기본법 제7조제2항"},{"t":"전문기관에 조사의 전부 또는 일부를 수행하게 할 수 있다. 조사 결과로 물류비 등 물류지표를 설정해 정책 수립·평가에 활용할 수 있다.","src":"물류정책기본법 제7조제3·4항"},{"t":"물류현황조사지침은 국토교통부장관이 대통령령으로 정하는 바에 따라 작성·통보할 수 있다. 작성하려면 미리 관계 중앙행정기관의 장과 협의한다(시·도지사와의 협의 아님).","src":"물류정책기본법 제8조"},{"t":"지역물류현황조사: 시·도지사가 실시. 시장·군수·구청장, 물류기업, 지원받는 기업·단체 등에 자료제출·직접조사 요청 가능. 전문기관에 일부 또는 전부 수행시킬 수 있다. 조사지침은 해당 시·도 조례로 정하는 바에 따라 작성·통보할 수 있다.","src":"물류정책기본법 제9조"},{"t":"물류개선조치의 요청: 수요가 특정 시설·운송수단에 치우치거나 정책·계획이 국가물류기본계획에 위배된다고 판단되면 중앙행정기관의 장이나 시·도지사에게 요청(미리 협의). 이의가 있으면 국가물류정책위원회에 조정을 요청할 수 있다.","src":"물류정책기본법 제10조"}]},{"머리":"국가물류기본계획·연도별시행계획(제11~13조)","줄":[{"t":"국가물류기본계획: 국토교통부장관과 해양수산부장관이 공동으로, 10년 단위 계획을 5년마다 수립.","src":"물류정책기본법 제11조제1항"},{"t":"수립·변경 중요사항은 관계 중앙행정기관의 장·시·도지사와 협의한 후 국가물류정책위원회 심의를 거친다.","src":"물류정책기본법 제11조제4항"},{"t":"수립·변경 시 관보 고시 및 관계 중앙행정기관의 장·시·도지사 통보는 국토교통부장관이 한다.","src":"물류정책기본법 제11조제5항"},{"t":"포함사항: 물류환경 변화와 전망 / 정책 목표·전략·단계별 추진계획 / 국가물류정보화사업 / 기능별·운송수단별 정책의 종합·조정 / 시설·장비의 수급·배치 및 투자 우선순위 / 연계물류체계 구축·개선 / 표준화·공동화 등 효율화 / 물류보안 / 산업 경쟁력 강화 / 인력 양성·기술 개발 / 국제물류 촉진·지원 / 환경친화적 물류활동 촉진·지원 / 그 밖에 체계 개선에 필요한 사항.","src":"물류정책기본법 제11조제2항"},{"t":"중요한 사항 변경(시행령): 정책 목표와 주요 추진전략 / 물류시설·장비 투자 우선순위 / 국제물류 촉진·지원 기본사항 / 위원회 심의가 필요하다고 인정하는 사항.","src":"물류정책기본법 시행령 제5조"},{"t":"국가물류기본계획은 국토종합계획·국가기간교통망계획과 조화를 이루어야 한다. 다른 법령에 따라 수립되는 물류 계획에는 우선하며 그 계획의 기본이 된다.","src":"물류정책기본법 제12조"},{"t":"연도별시행계획: 국토교통부장관·해양수산부장관이 매년 공동으로 수립.","src":"물류정책기본법 제13조"}]},{"머리":"지역물류기본계획(제14~16조)","줄":[{"t":"특별시장·광역시장: 10년 단위 지역물류기본계획을 5년마다 수립해야 한다.","src":"물류정책기본법 제14조제1항"},{"t":"특별자치시장·도지사·특별자치도지사: 필요한 경우 수립할 수 있다(임의).","src":"물류정책기본법 제14조제2항"},{"t":"지역물류기본계획은 국가물류기본계획에 배치되지 않아야 한다.","src":"물류정책기본법 제14조제3항"},{"t":"수립방법·기준 지침은 국토교통부장관과 해양수산부장관이 공동으로 작성하고, 국토교통부장관이 특별시장·광역시장 등에게 통보한다.","src":"물류정책기본법 제14조제4·5항"},{"t":"수립·중요사항 변경 시 인접 시·도지사와 협의한 후 지역물류정책위원회 심의를 거친다. 수립·변경한 계획은 국토교통부장관·해양수산부장관에게 통보하고, 공고한다.","src":"물류정책기본법 제15조제2·3항"},{"t":"국토교통부장관 또는 해양수산부장관은 통보받은 지역계획이 필요하면 관계 중앙행정기관과 협의 후 물류정책분과위원회 심의를 거쳐 변경을 요구할 수 있다.","src":"물류정책기본법 제15조제4항"},{"t":"지역물류시행계획: 지역물류기본계획을 수립한 특별시장·광역시장이 매년 수립.","src":"물류정책기본법 제16조제1항"}]},{"머리":"국가물류정책위원회","줄":[{"t":"설치: 국토교통부장관 소속. 위원장은 국토교통부장관.","src":"물류정책기본법 제17조제1항, 제18조제2항"},{"t":"심의·조정 사항: 국가물류체계 효율화 중요 정책 / 물류시설의 종합적 개발계획 수립 / 물류산업 육성·발전 중요 정책 / 물류보안 중요 정책 / 국제물류 촉진·지원 중요 정책 / 법률에서 위원회 심의를 거치도록 한 사항 / 위원장이 회의에 부치는 사항.","src":"물류정책기본법 제17조제2항"},{"t":"구성: 위원장 포함 23명 이내. 위원은 관계 부처 고위공무원단 공무원 각 1명(해당 기관장 지명)과 전문가 10명 이내(위원장 위촉). 간사 1명은 국토교통부 소속 공무원 중 위원장 지명.","src":"물류정책기본법 제18조제1~3항"},{"t":"공무원이 아닌 위원의 임기 2년, 연임 가능.","src":"물류정책기본법 제18조제4항"},{"t":"회의: 위원장이 소집, 5일 전까지 통지(긴급 시 예외). 재적위원 과반수 출석으로 개의, 출석위원 과반수 찬성으로 의결.","src":"물류정책기본법 시행령 제11조"},{"t":"분과위원회: 물류정책·물류시설·국제물류 3개. 분과위원회가 위임사항 및 법률상 심의사항을 심의·조정하면 위원회의 심의·조정으로 본다.","src":"물류정책기본법 제19조"},{"t":"분과위원회 위원장: 분과위원 중에서 국토교통부장관(물류정책·물류시설) 또는 해양수산부장관(국제물류)이 지명. 공무원 아닌 분과위원 임기 2년, 연임 가능.","src":"물류정책기본법 시행령 제13조"},{"t":"국가물류정책위원회에는 5명 이내의 비상근 전문위원을 둘 수 있다.","src":"기출 2022-5"},{"t":"전문위원회: 녹색물류전문위원회·생활물류전문위원회.","src":"물류정책기본법 제19조의2"},{"t":"지역물류정책위원회: 시·도지사 소속(국토교통부장관 소속 아님). 위원장 포함 20명 이내, 위원장은 해당 시·도지사. 공무원 아닌 위원 임기 2년, 연임 가능.","src":"물류정책기본법 제20조, 시행령 제16조"}]},{"머리":"물류시설·장비 확충, 연계, 공동화·자동화(제21~23조)","줄":[{"t":"물류시설·장비 확충 권고: 국토교통부장관·해양수산부장관·산업통상부장관(종전 산업통상자원부장관)이 물류기업에 권고하고 행정적·재정적 지원을 할 수 있다.","src":"물류정책기본법 제21조"},{"t":"새 시설 건설·기존 시설 정비 시 고려사항: 주요 물류거점시설·운송수단과의 연계성 / 주변 물류시설과의 기능중복 여부 / 공항·항만·산업단지의 배후 물류시설 부지 확보 여부. 대상 주체는 국가·지방자치단체·물류관련기관·물류기업 등(민법 제32조 비영리법인 포함).","src":"물류정책기본법 제22조, 시행령 제17조"},{"t":"물류공동화 자금 지원: 국토교통부장관·해양수산부장관·산업통상부장관 또는 시·도지사가 물류기업이나 화주기업 또는 물류 관련 단체에 예산 범위에서 지원 가능.","src":"물류정책기본법 제23조제1항"},{"t":"화주기업이 물류공동화를 추진하면 물류기업이나 물류 관련 단체와 공동 추진을 권고할 수 있고, 이행하면 우선 지원할 수 있다.","src":"물류정책기본법 제23조제2항"},{"t":"우선 지원 대상 물류기업: 클라우드컴퓨팅 등 정보통신기술을 활용해 공동화를 추진하는 경우 / 농수산물·식품, 의약품, 반도체·이차전지 등을 적합한 온도로 운송하는 정온물류 공동화를 추진하는 경우.","src":"물류정책기본법 제23조제3항, 시행령 제17조의2"},{"t":"시범지역 지정·시범사업 선정·운영: 국토교통부장관·해양수산부장관·산업통상부장관 또는 시·도지사(관세청장·시장·군수·구청장은 주체가 아님).","src":"물류정책기본법 제23조제4항"},{"t":"물류자동화 자금 지원: 국토교통부장관·해양수산부장관 또는 산업통상부장관이 물류기업이 자동화를 위해 시설·장비를 확충·교체하려는 경우 지원(시·도지사는 이 항의 주체 아님).","src":"물류정책기본법 제23조제5항"},{"t":"시·도지사가 공동화 조치를 하려면 중앙부처 장관과 미리 협의하고 지역물류기본계획·시행계획에 반영한다.","src":"물류정책기본법 제23조제7항"}]},{"머리":"물류표준화·물류회계·정보화(제24~28조)","줄":[{"t":"한국산업표준 제정·개정·폐지 요청: 국토교통부장관 또는 해양수산부장관이 산업통상부장관에게 요청할 수 있다(임의).","src":"물류정책기본법 제24조제1항"},{"t":"물류표준장비 제조·사용, 표준 규격 포장 요청·권고: 국토교통부장관·해양수산부장관·산업통상부장관.","src":"물류정책기본법 제24조제2항"},{"t":"기업물류비 산정지침: 국토교통부장관이 해양수산부장관·산업통상부장관과 협의해 작성·고시. 비용관리를 권고하고 지원할 수 있다.","src":"물류정책기본법 제26조"},{"t":"기업물류비 산정지침 포함사항: 물류비 관련 용어·개념의 정의 / 영역별·기능별·자가별·위탁별 물류비 분류 / 물류비 계산 기준·방법 / 물류비 계산서 표준 서식.","src":"물류정책기본법 시행령 제18조"},{"t":"물류정보화 시책 강구 주체: 국토교통부장관·해양수산부장관·산업통상부장관 또는 관세청장.","src":"물류정책기본법 제27조제1항"},{"t":"단위물류정보망 전담기관 지정 가능 공공기관: 인천국제공항공사·한국공항공사·한국도로공사·한국철도공사·한국토지주택공사·항만공사·국토교통부장관 고시 공공기관. 공공기관이 아니면 자본금 2억원 이상 주식회사 등 기준 충족.","src":"물류정책기본법 시행령 제20조"},{"t":"전담기관 지정취소: 거짓·부정 지정은 취소하여야 하고, 지정기준 미달은 취소할 수 있다.","src":"물류정책기본법 제28조제8항"},{"t":"전담기관 지정 공고: 신청방법 등을 정해 30일 이상 관보·공보·인터넷 홈페이지에 공고.","src":"물류정책기본법 시행령 제20조제1항"}]},{"머리":"위험물질운송안전관리센터(제29조~제29조의3)","줄":[{"t":"설치·운영: 국토교통부장관. 한국교통안전공단이 대행.","src":"물류정책기본법 제29조제1항, 시행령 제21조"},{"t":"법 제29조 위험물질: 위험물안전관리법상 위험물 / 화학물질관리법상 허가물질·제한물질·금지물질·유해화학물질 / 고압가스 / 방사성폐기물 / 지정폐기물 / 농약·원제 / 그 밖에 대통령령 물질. (생활폐기물, 화약류는 해당 없음)","src":"물류정책기본법 제29조제1항"},{"t":"감시 필요 위험물질 차량의 최대 적재량 기준(시행규칙): 위험물 10,000리터 이상 / 지정폐기물 10,000킬로그램 이상 / 유해화학물질 등 5,000킬로그램 이상 / 가연성가스 6,000킬로그램 이상 / 독성가스 2,000킬로그램 이상.","src":"물류정책기본법 시행규칙 제2조의2"},{"t":"단말장치 장착의무는 차량 소유자, 작동 유지는 운전자, 운송계획정보 사전 입력은 단말장치 장착차량의 소유자. 장착 비용은 국토교통부장관이 지원할 수 있다.","src":"물류정책기본법 제29조의2"},{"t":"장착 명령 불이행 시 국토교통부장관은 차량 운행중지를 명할 수 있다. 취득 정보 목적 외 사용 금지.","src":"물류정책기본법 제29조의3, 제29조제4항"}]},{"머리":"국가물류통합정보센터·전자문서(제30~34조)","줄":[{"t":"국가물류통합데이터베이스 구축·통합정보센터 설치·운영: 국토교통부장관.","src":"물류정책기본법 제30조, 제30조의2제1항"},{"t":"국가물류통합정보센터운영자로 지정 가능한 자: 중앙행정기관 / 대통령령 공공기관(인천국제공항공사·한국공항공사·한국도로공사·한국철도공사·한국토지주택공사·항만공사 등) / 정부출연연구기관 / 물류관련협회 / 자본금 2억원 이상 등 기준을 갖춘 상법상 주식회사.","src":"물류정책기본법 제30조의2제2항, 시행령 제22조"},{"t":"운영자 지정 절차: 국토교통부장관이 물류시설분과위원회 심의를 거쳐 신청방법 등을 정해 30일 이상 관보·인터넷 홈페이지에 공고. 지정 후 지정증 발급·공고.","src":"물류정책기본법 시행령 제22조"},{"t":"운영자 지정취소: 거짓·부정 지정은 취소하여야 한다. 지정기준 미달, 물류정보를 영리 목적으로 사용한 경우는 취소할 수 있다.","src":"물류정책기본법 제31조"},{"t":"전자문서·물류정보 보관기간: 2년.","src":"물류정책기본법 시행령 제25조"},{"t":"전자문서 위작·변작·행사: 10년 이하 징역 또는 1억원 이하 벌금(미수범 처벌). 물류정보 훼손·비밀침해·누설: 5년 이하 징역 또는 5천만원 이하 벌금. 보호조치 침해·훼손: 3년 이하 징역 또는 3천만원 이하 벌금.","src":"물류정책기본법 제71조제1~3항"}]},{"머리":"물류신고센터(제37조의2·3)","줄":[{"t":"설치·운영: 국토교통부장관 또는 해양수산부장관(임의). 센터의 장은 국토교통부·해양수산부 물류정책 총괄 부서의 장 중 장관이 지명하는 사람.","src":"물류정책기본법 제37조의2제1항, 시행령 제27조의2"},{"t":"신고 대상 행위: 계약을 정당한 사유 없이 불이행·일방 변경 / 단가 인하를 위한 고의적 재입찰·계약단가 정보 노출 / 계약 범위를 벗어난 과적·금전 등 제공 강요 / 유류비 급등 등 비용 증가분의 계약단가 반영 지속 회피.","src":"물류정책기본법 제37조의2제2항"},{"t":"신고 종결 사유: 명백한 거짓 / 보완요구 불응 / 처리결과 통보 사항을 새 증거 없이 재신고 / 재판 계류·판결 확정 / 이미 수사·감사 중 / 확인 불가 등 센터장 인정. 종결 시 사실과 사유를 신고자에게 서면 등으로 통보해야 한다.","src":"물류정책기본법 시행규칙 제4조의3"},{"t":"조정권고 서면 통지 명시사항: 신고의 주요내용 / 조정권고 내용 / 수락 여부 통보기한 / 향후 신고 처리 사항.","src":"물류정책기본법 시행규칙 제4조의5"},{"t":"신고 내용이 다른 법률(공정거래법·하도급법·대리점법 등) 위반으로 판단되면 관계부처에 통보하여야 한다. 조정권고용 자료제출 불이행·허위: 1천만원 이하 벌금.","src":"물류정책기본법 제37조의3, 제71조제7항"}]},{"머리":"우수물류기업 인증(제38~42조)","줄":[{"t":"인증 주체: 국토교통부장관 및 해양수산부장관이 소관 물류기업을 각각 인증. 물류사업별로 운영 가능.","src":"물류정책기본법 제38조제1·2항"},{"t":"사업별 인증 주체(시행령 별표 1의2): 화물자동차운송기업 - 국토교통부장관 / 물류창고기업 - 국토교통부장관 또는 해양수산부장관(항만구역 창고 운영 기업만 해수부) / 국제물류주선기업 - 국토교통부장관 / 화물정보망기업 - 국토교통부장관 / 종합물류서비스기업 - 국토교통부장관·해양수산부장관 공동.","src":"물류정책기본법 시행령 별표 1의2"},{"t":"요건 유지 점검: 3년마다(공동부령으로 정하는 바에 따라). 요건을 유지하지 못한다고 판단되면 별도 점검 가능. 인증 기준·절차 등은 국토교통부·해양수산부 공동부령.","src":"물류정책기본법 제38조제3·4항, 시행령 제28조"},{"t":"인증 취소: 거짓·부정 인증은 취소하여야 한다. 아래는 취소할 수 있다 - 공정거래위원회 시정조치 또는 과징금 처분 / 점검을 정당한 사유 없이 3회 이상 거부 / 인증기준 미달 / 성명·상호 사용 영업 허용 또는 인증서 대여.","src":"물류정책기본법 제39조제1항"},{"t":"인증 취소 시 인증서 반납, 인증마크 사용 중지. 인증마크 계속 사용은 과태료 대상(1차 50만원, 2차 100만원, 3차 이상 200만원).","src":"물류정책기본법 제39조제2항, 시행령 별표 4"},{"t":"인증심사대행기관: 국토교통부장관·해양수산부장관이 공동 지정. 업무: 인증신청 접수 / 인증요건 심사 / 점검 대행 / 그 밖의 지원업무. 공공기관 또는 정부출연연구기관 중에서 지정.","src":"물류정책기본법 제40조"},{"t":"심사대행기관 지정취소(공동): 거짓·부정 지정은 취소하여야 한다. 고의·중과실로 기준·절차 위반, 정당한 사유 없는 인증업무 거부는 취소할 수 있다.","src":"물류정책기본법 제40조의2"},{"t":"인증서·인증마크: 인증우수물류기업이 아닌 자가 거짓 인증마크를 제작·사용하거나 인증기업을 사칭하면 3천만원 이하 벌금.","src":"물류정책기본법 제41조제3항, 제71조제6항"},{"t":"지원: 국가·지방자치단체·공공기관이 인증우수물류기업 및 우수녹색물류실천기업에 행정적·재정적 지원 가능(인증우수물류기업의 해외시장 개척 소요비용 우선 지원 가능).","src":"물류정책기본법 제42조 / 기출 2022-7"}]},{"머리":"국제물류주선업(제43~47조, 제67조)","줄":[{"t":"등록: 시·도지사에게 등록(국토교통부령). 중요사항 변경 시 변경등록. 등록기준: 자본금 3억원 이상(법인이 아니면 자산평가액 6억원 이상) + 대통령령 기준.","src":"물류정책기본법 제43조제1~3항"},{"t":"시행령 기준: 1억원 이상 보증보험 가입. 다만 자본금(또는 자산평가액) 10억원 이상 / 컨테이너장치장 소유 / 은행의 1억원 이상 지급보증 / 1억원 이상 화물배상책임보험 가입 중 하나면 예외.","src":"물류정책기본법 시행령 제30조의2"},{"t":"등록기준 신고: 3년이 경과할 때마다. 등록한 날부터 3년 경과 시점부터 60일 이내 시·도지사에게 신고.","src":"물류정책기본법 제43조제4항, 시행규칙 제7조의2"},{"t":"변경등록 사유: 상호 / 성명(법인은 임원 성명) 및 주민등록번호 / 주사무소 소재지 / 국적·소속 국가명 / 자본금·자산평가액 감소. 변경사유 발생일부터 60일 이내 신청.","src":"물류정책기본법 시행규칙 제7조"},{"t":"결격사유: 피성년후견인·피한정후견인 / 이 법·화물자동차 운수사업법·항공사업법·항공안전법·공항시설법·해운법 위반으로 금고 이상 실형 집행종료·면제 후 2년 미경과 / 같은 법 위반 금고 이상 집행유예 기간 중 / 같은 법 위반 벌금형 선고 후 2년 미경과 / 등록 취소 후 2년 미경과(피성년후견인 사유 취소 제외) / 법인의 대표자 또는 임원이 위 해당.","src":"물류정책기본법 제44조"},{"t":"사업 승계: 양도·사망·합병 시 양수인·상속인·합병법인이 권리·의무 승계. 승계자는 시·도지사에게 신고(양도·상속·합병일부터 30일 이내). 승계자 결격사유는 제44조 준용.","src":"물류정책기본법 제45조, 시행규칙 제8조"},{"t":"휴업·폐업 확인: 시·도지사가 관할 세무관서의 장에게 과세정보 제공 요청 가능(국세청장 아님).","src":"물류정책기본법 제46조"},{"t":"등록취소·정지(시·도지사): 6개월 이내 사업의 전부 또는 일부 정지 가능. 필요적 취소 - 거짓·부정 등록 / 결격사유 해당(예외 있음) / 성명·상호 사용 영업 허용 또는 등록증 대여. 임의적(취소 또는 정지) - 등록기준 미달 / 등록기준 신고 불이행·허위 신고.","src":"물류정책기본법 제47조"},{"t":"결격 예외: 상속인이 결격이어도 상속일부터 3개월 이내 사업 양도 시, 법인 임원 결격은 사유 발생일(합병일)부터 3개월 이내 임원 개임 시 취소하지 않는다.","src":"물류정책기본법 제47조제1항제4호 단서"},{"t":"과징금: 사업정지를 명해야 하는 경우로서 이용자에게 심한 불편을 주면 정지에 갈음해 1천만원 이하 과징금(시·도지사). 시행령 별표 3: 등록기준 미달·등록기준 신고 위반의 2차 100만원, 3차 200만원. 총액 가중 시에도 1천만원 초과 불가. 미납 시 지방행정제재·부과금법에 따라 징수.","src":"물류정책기본법 제67조, 시행령 제52조·별표 3"},{"t":"등록 없이 국제물류주선업 경영: 1년 이하 징역 또는 1천만원 이하 벌금. 성명·상호 사용 허용·등록증 대여: 1천만원 이하 벌금. 변경등록 불이행·승계 신고 불이행: 200만원 이하 과태료.","src":"물류정책기본법 제71조제4·7항, 제73조제1항"}]},{"머리":"물류관리사(제50~54조, 제66조의2)","줄":[{"t":"자격시험: 국토교통부장관 실시(매년 1회, 수급상 필요하면 2년마다). 시험 부정행위 시 무효, 그 처분일 또는 자격 취소일부터 3년간 응시 불가.","src":"물류정책기본법 제51조, 시행령 제35조"},{"t":"직무: 물류활동 관련 전문지식이 필요한 사항에 대한 계획·조사·연구·진단·평가, 상담·자문, 그 밖에 물류관리에 필요한 직무.","src":"물류정책기본법 제52조"},{"t":"자격 취소(필요적, 국토교통부장관): 부정한 방법으로 취득 / 성명 사용 사업 허용·자격증 대여 / 이를 알선. 청문 실시.","src":"물류정책기본법 제53조, 제68조"},{"t":"고용사업자 우선 지원: 국토교통부장관 또는 시·도지사가 물류관리사를 고용한 물류관련 사업자를 우선 지원할 수 있다. 시·도지사는 미리 국토교통부장관과 협의.","src":"물류정책기본법 제54조"},{"t":"자격증 대여 금지: 대여·성명 사용 허용·알선·대여받은 자 모두 1년 이하 징역 또는 1천만원 이하 벌금.","src":"물류정책기본법 제66조의2, 제71조제4항"},{"t":"물류연수기관: 물류관련협회 또는 그 교육훈련기관 / 물류지원센터 / 화물자동차운수사업자 협회·연합회 및 그 교육훈련기관 / 대한무역투자진흥공사 / 민법 제32조 물류 비영리법인 / 고시 기관 / 한국해양수산연수원 / 항만운송사업법상 교육훈련기관. 대한무역투자진흥공사도 물류연수기관이 될 수 있다.","src":"물류정책기본법 시행규칙 제11조"}]},{"머리":"물류관련협회·물류지원센터(제55·56조)","줄":[{"t":"물류관련협회 설립: 회원 자격이 있는 기업 100개 이상이 발기인으로 정관 작성 → 회원 자격이 있는 기업 200개 이상이 참여한 창립총회 의결 → 소관에 따라 국토교통부장관 또는 해양수산부장관의 설립인가.","src":"물류정책기본법 제55조제2항"},{"t":"설립인가를 받아 설립등기를 함으로써 성립. 법인. 이 법에 규정 없으면 민법 중 사단법인 규정 준용. 인가권자는 행정적·재정적 지원 가능.","src":"물류정책기본법 제55조제3~6항"},{"t":"협회 사업: 해당 사업의 진흥·발전에 필요한 통계 작성·관리, 외국자료 수집·조사·연구 등.","src":"기출 2024-5"},{"t":"물류지원센터(민·관 합동): 국토교통부장관·해양수산부장관·산업통상부장관 및 대통령령 물류관련협회·전문기관·단체가 공동으로 설치·운영할 수 있다. 업무: 국내 물류기업 해외진출·해외기업 국내투자유치 지원 / 물류산업 조사·연구 / 공동화·정보화 지원 등. 센터의 장이 매 연도별로 사업계획을 수립(3년마다 아님).","src":"물류정책기본법 제56조, 시행령 제46조"}]},{"머리":"환경친화적 물류(제59~60조의8)","줄":[{"t":"환경친화적 물류시책 마련은 국토교통부장관·해양수산부장관 또는 시·도지사의 의무(하여야 한다).","src":"물류정책기본법 제59조제1항"},{"t":"지원 대상 활동: 환경친화적 운송수단 또는 포장재료 사용 / 기존 시설·장비·운송수단을 환경친화적인 것으로 변경 / 환경친화적 물류시스템 도입·개발 / 물류활동에 따른 폐기물 감량 / 물류자원 절약·재활용 활동(고시). 지원 대상자는 물류기업·화주기업·개인 운송사업자.","src":"물류정책기본법 제59조제2항, 시행령 제47조"},{"t":"환경친화적 운송수단 전환 지원 대상: 화물자동차·철도차량·선박·항공기의 배출가스 저감 또는 저감 가능한 운송수단 전환과 그 시설·장비투자 / 환경친화적 연료 사용 운송수단 전환과 그 시설·장비투자.","src":"물류정책기본법 시행령 제48조"},{"t":"우수녹색물류실천기업: 국토교통부장관이 환경친화적 물류활동을 모범적으로 하는 물류기업·화주기업을 지정. 요건 유지 여부 3년마다 점검. 지정기준: 평가항목 합산 70점 이상, 항목별 배점의 2할 이상.","src":"물류정책기본법 제60조의3, 시행규칙 제14조의7"},{"t":"지정취소: 거짓·부정 지정은 취소하여야 한다. 요건 미충족, 점검 정당한 사유 없이 3회 이상 거부는 취소할 수 있다. 취소 시 지정증 반납·지정표시 사용 중지(계속 사용 시 과태료 50/100/200만원).","src":"물류정책기본법 제60조의6"},{"t":"지정심사대행기관: 국토교통부장관이 지정(공공기관 또는 정부출연연구기관 중). 취소 - 거짓·부정 지정은 취소하여야 하고, 고의·중과실 기준·절차 위반, 정당한 사유 없는 업무 거부는 취소할 수 있다.","src":"물류정책기본법 제60조의7·8"},{"t":"녹색물류협의기구(기출 기준): 환경친화적 물류활동 지원 사업의 심사·선정, 정책·사업 개발·제안 등을 맡고 위원장 포함 15명 이상 30명 이하로 구성. 현행 조문에서는 확인되지 않음.","src":"기출 2021-7, 2022-4"}]},{"머리":"과태료·벌칙 요약","줄":[{"t":"200만원 이하 과태료: 자료제출 불이행·허위(물류기업 등) / 국제물류주선업 변경등록 불이행 / 승계 신고 불이행 / 인증마크·지정표시 계속 사용 / 단말장치 미장착·미점검·미유지 / 운송계획정보 미입력·허위 / 출입·조사 거부.","src":"물류정책기본법 제73조제1항"},{"t":"과태료 금액(시행령 별표 4): 인증마크 계속 사용 50만원-100만원-200만원 / 단말장치 관련 50-100-200만원 / 자료제출 위반 50-100-150만원 / 변경등록·승계 신고 지연 10일 이하 10-20-30만원, 90일 이상 130-140-150만원.","src":"물류정책기본법 시행령 별표 4"},{"t":"과태료 부과·징수: 국토교통부장관·해양수산부장관 또는 시·도지사.","src":"물류정책기본법 제73조제2항"},{"t":"1년 이하 징역/1천만원 이하 벌금: 위험물질 정보 목적 외 사용 / 정보 보관기간 미준수 / 국제물류주선업 무등록 / 물류관리사 자격증 대여. 1천만원 이하 벌금: 운행중지 명령 불이행 / 조정권고 관련 보고·조사 방해 / 상호 사용 허용·증서 대여.","src":"물류정책기본법 제71조"}]}],"함정":[{"x":"시ㆍ도지사는 물류기업 등에게 지역물류현황조사를 요청하는 경우 조례로 정하는 바에 따라 조사지침을 작성ㆍ통보할 수 없고, 국토교통부장관의 물류현황조사지침을 따르도록 해야 한다.","o":"시·도지사는 해당 시·도의 조례로 정하는 바에 따라 지역물류현황조사 지침을 작성·통보할 수 있다.","src":"물류정책기본법 제9조제4항 / 기출 2021-2"},{"x":"국제물류주선업을 경영하려는 자는 국토교통부장관에게 등록하여야 한다.","o":"시·도지사에게 등록한다.","src":"물류정책기본법 제43조제1항 / 기출 2021-5"},{"x":"피한정후견인은 국제물류주선업의 등록을 할 수 있다.","o":"피성년후견인·피한정후견인은 등록할 수 없다.","src":"물류정책기본법 제44조제1호 / 기출 2021-5"},{"x":"등록증 대여 등의 금지규정에 위반하여 다른 사람에게 등록증을 대여한 경우에는 시ㆍ도지사는 사업의 전부의 정지를 명할 수 있다.","o":"등록증 대여는 등록을 취소하여야 하는 사유다.","src":"물류정책기본법 제47조제1항제5호 / 기출 2021-5"},{"x":"시ㆍ도지사는 국제물류주선업자가 거짓이나 그 밖의 부정한 방법으로 등록을 한 경우에는 사업의 일부의 정지를 명할 수 있다.","o":"거짓·부정 등록은 등록을 취소하여야 한다.","src":"물류정책기본법 제47조제1항제1호 / 기출 2021-5"},{"x":"물류신고센터는 신고 내용이 명백히 거짓인 경우 접수된 신고를 종결할 수 있으며, 이 경우 종결 사유를 신고자에게 통보할 필요가 없다.","o":"종결 사실과 그 사유를 신고자에게 서면 등으로 통보해야 한다.","src":"물류정책기본법 시행규칙 제4조의3 / 기출 2021-6"},{"x":"물류신고센터의 장은 산업통상자원부장관이 지명하는 사람이 된다.","o":"국토교통부장관 또는 해양수산부장관이 지명하는 사람(물류정책 총괄 부서의 장)이다.","src":"물류정책기본법 시행령 제27조의2제2항 / 기출 2021-6"},{"x":"화물운송의 단가를 인하하기 위한 고의적 재입찰 행위로 발생한 분쟁에 대해서는 물류신고센터에 신고할 수 없다.","o":"단가 인하를 위한 고의적 재입찰·계약단가 정보 노출 행위는 신고 대상이다.","src":"물류정책기본법 제37조의2제2항제2호 / 기출 2021-6"},{"x":"물류신고센터는 신고 내용이 이미 수사나 감사 중에 있다는 이유로 접수된 신고를 종결할 수 없다.","o":"이미 수사나 감사 중인 경우 종결할 수 있다.","src":"물류정책기본법 시행규칙 제4조의3제5호 / 기출 2021-6"},{"x":"녹색물류협의기구의 위원장은 국토교통부장관이 임명한다.","o":"위원장은 국토교통부장관이 임명하지 않는다(기출이 틀린 문장으로 처리). 정확한 선임 방법은 현행 조문에서 확인되지 않음.","src":"기출 2021-7"},{"x":"물류관련협회를 설립하려는 경우에는 해당 협회의 회원이 될 자격이 있는 기업 150개 이상이 참여한 창립총회의 의결을 거쳐야 한다.","o":"200개 이상이 참여한 창립총회 의결(발기인은 100개 이상).","src":"물류정책기본법 제55조제2항 / 기출 2021-8"},{"x":"해양수산부장관은 국가물류기본계획을 수립한 때에는 이를 관보에 고시하여야 한다.","o":"관보 고시는 국토교통부장관이 한다.","src":"물류정책기본법 제11조제5항 / 기출 2022-1"},{"x":"「대한무역투자진흥공사법」에 따른 대한무역투자진흥공사는 물류연수기관이 될 수 없다.","o":"대한무역투자진흥공사는 물류연수기관에 해당한다.","src":"물류정책기본법 시행규칙 제11조제5호 / 기출 2022-3"},{"x":"녹색물류협의기구의 위원장은 위원 중에서 국토교통부장관이 지명하는 사람으로 한다.","o":"국토교통부장관이 지명하지 않는다(기출이 틀린 문장으로 처리). 정확한 선임 방법은 현행 조문에서 확인되지 않음.","src":"기출 2022-4"},{"x":"물류시설분과위원회의 위원장은 해당 분과위원회의 위원 중에서 해양수산부장관이 지명하는 사람으로 한다.","o":"물류정책·물류시설분과위원회 위원장은 국토교통부장관이 지명, 국제물류분과위원회 위원장만 해양수산부장관이 지명.","src":"물류정책기본법 시행령 제13조제2항 / 기출 2022-5"},{"x":"컨테이너장치장을 소유하고 있는 자가 국제물류주선업을 등록하려는 경우 1억원 이상의 보증보험에 가입하여야 한다.","o":"컨테이너장치장 소유자는 보증보험 가입 의무가 면제된다.","src":"물류정책기본법 시행령 제30조의2제2호 / 기출 2022-6"},{"x":"국제물류주선업을 경영하려는 자는 해양수산부장관에게 등록하여야 한다.","o":"시·도지사에게 등록한다.","src":"물류정책기본법 제43조제1항 / 기출 2022-6"},{"x":"국제물류주선업자는 등록기준에 관한 사항을 5년이 경과할 때마다 신고하여야 한다.","o":"3년이 경과할 때마다 신고한다.","src":"물류정책기본법 제43조제4항 / 기출 2022-6"},{"x":"해양수산부장관은 국제물류주선업자의 폐업 사실을 확인하기 위하여 필요한 경우에는 국세청장에게 폐업에 관한 과세정보의 제공을 요청할 수 있다.","o":"시·도지사가 관할 세무관서의 장에게 요청할 수 있다.","src":"물류정책기본법 제46조 / 기출 2022-6"},{"x":"국제물류주선기업에 대한 우수물류기업 인증의 주체는 해양수산부장관이다.","o":"국제물류주선기업 인증 주체는 국토교통부장관이다.","src":"물류정책기본법 시행령 별표 1의2 / 기출 2022-7"},{"x":"국토교통부장관은 물류현황조사를 위한 조사지침을 작성하려는 경우에는 미리 시ㆍ도지사와 협의하여야 한다.","o":"미리 관계 중앙행정기관의 장과 협의한다.","src":"물류정책기본법 제8조제2항 / 기출 2023-1"},{"x":"특별시장 및 광역시장은 지역물류정책의 기본방향을 설정하는 5년 단위의 지역물류기본계획을 3년마다 수립하여야 한다.","o":"10년 단위 계획을 5년마다 수립한다.","src":"물류정책기본법 제14조제1항 / 기출 2023-2"},{"x":"지역물류정책에 관한 주요 사항을 심의하기 위하여 국토교통부장관 소속으로 지역물류정책위원회를 둘 수 있다.","o":"시·도지사 소속으로 지역물류정책위원회를 둔다(둘 수 있다가 아니라 둔다).","src":"물류정책기본법 제20조제1항 / 기출 2024-1"},{"x":"국토교통부장관 또는 해양수산부장관은 물류표준화에 관한 업무를 효과적으로 추진하기 위하여 필요하다고 인정하는 경우에는 통계청장에게 「산업표준화법」에 따른 한국산업표준의 제정ㆍ개정 또는 폐지를 요청하여야 한다.","o":"산업통상부장관(종전 산업통상자원부장관)에게 요청할 수 있다.","src":"물류정책기본법 제24조제1항 / 기출 2024-2"},{"x":"국토교통부장관 또는 해양수산부장관은 인증우수물류기업이 해당 요건을 유지하는지에 대하여 공동부령으로 정하는 바에 따라 2년마다 점검하여야 한다.","o":"3년마다 점검한다.","src":"물류정책기본법 시행령 제28조제1항 / 기출 2024-3"},{"x":"민ㆍ관 합동 물류지원센터의 장은 3년마다 사업계획을 수립한다.","o":"매 연도별로 사업계획을 수립한다.","src":"물류정책기본법 시행령 제46조제2항 / 기출 2024-5"},{"x":"국토교통부장관은 국가물류통합정보센터운영자를 지정하려는 경우에는 미리 물류정책분과위원회의 심의를 거쳐 신청방법 등을 정하여 30일 이상 관보 또는 인터넷 홈페이지에 이를 공고하여야 한다.","o":"물류시설분과위원회의 심의를 거친다.","src":"물류정책기본법 시행령 제22조제1항 / 기출 2024-6"},{"x":"국토교통부장관은 우수녹색물류실천기업 지정심사대행기관이 고의 또는 중대한 과실로 지정 기준 및 절차를 위반한 경우에는 그 지정을 취소하여야 한다.","o":"취소할 수 있다. 거짓·부정 지정일 때만 취소하여야 한다.","src":"물류정책기본법 제60조의8 / 기출 2024-7"},{"x":"국가물류기본계획은 「국토기본법」에 따라 수립된 국토종합계획 및 「국가통합교통체계효율화법」에 따라 수립된 국가기간교통망계획에 우선한다.","o":"국토종합계획·국가기간교통망계획과 조화를 이루어야 한다. 우선하는 대상은 다른 법령에 따른 물류 계획.","src":"물류정책기본법 제12조 / 기출 2025-2"},{"x":"국가물류정책위원회는 위원장을 제외한 20명 이내의 위원으로 구성하고, 위원은 연임할 수 없다.","o":"위원장 포함 23명 이내, 공무원이 아닌 위원은 임기 2년에 연임할 수 있다.","src":"물류정책기본법 제18조 / 기출 2025-3"},{"x":"화물정보망기업에 대한 우수물류기업 인증의 주체는 국토교통부장관ㆍ해양수산부장관 공동이다.","o":"국토교통부장관이다. 공동 인증은 종합물류서비스기업.","src":"물류정책기본법 시행령 별표 1의2 / 기출 2025-4"},{"x":"국제물류주선업을 경영하려는 자는 국토교통부장관의 허가를 받아야 한다.","o":"시·도지사에게 등록한다(허가 아님).","src":"물류정책기본법 제43조제1항 / 기출 2025-5"},{"x":"국제물류주선업자가 그 사업을 양도하거나 사망한 때에는 그 양수인ㆍ상속인은 국제물류주선업의 등록에 따른 권리ㆍ의무를 승계하지 아니한다.","o":"권리·의무를 승계한다.","src":"물류정책기본법 제45조제1항 / 기출 2025-5"},{"x":"국제물류주선업자가 등록한 사항 중 자본금이 감소되는 경우에는 변경등록을 하지 않아도 된다.","o":"자본금 또는 자산평가액 감소는 변경등록 사유다.","src":"물류정책기본법 시행규칙 제7조제1항제2호 / 기출 2025-5"},{"x":"국토교통부장관은 국제물류주선업자가 거짓이나 그 밖의 부정한 방법으로 허가를 받은 경우에는 허가를 취소할 수 있다.","o":"시·도지사가 등록을 취소하여야 한다.","src":"물류정책기본법 제47조제1항제1호 / 기출 2025-5"},{"x":"국토교통부장관ㆍ해양수산부장관ㆍ산업통상자원부장관 또는 관세청장은 물류공동화를 확산하기 위하여 필요한 경우에는 시범사업을 선정하여 운영할 수 있다.","o":"주체는 국토교통부장관·해양수산부장관·산업통상부장관 또는 시·도지사(관세청장 아님).","src":"물류정책기본법 제23조제4항 / 기출 2025-7"},{"x":"화학물질관리법상 유해화학물질을 운송하는 차량은 최대 적재량 10,000리터 이상이면 위험물질운송안전관리센터 감시 대상이다.","o":"유해화학물질 등은 5,000킬로그램 이상, 위험물안전관리법 위험물은 10,000리터 이상.","src":"물류정책기본법 시행규칙 제2조의2 / 기출 2023-4, 2025-8"}]},"물류시설의 개발 및 운영에 관한 법률":{"묶음":[{"머리":"정의(제2조)","줄":[{"t":"물류터미널: 화물의 집화·하역 및 관련 분류·포장·보관·가공·조립·통관 등에 필요한 기능을 갖춘 시설물. 가공·조립 시설은 대통령령 규모 이하여야 한다.","src":"물류시설법 제2조제2호"},{"t":"물류터미널사업 제외 시설: 항만구역 안 화물하역·보관·처리시설 / 공항구역 안 화물운송시설과 부대·지원시설 / 철도사업자가 그 사업에 사용하는 화물운송·하역·보관시설 / 유통산업발전법상 집배송시설 및 공동집배송센터.","src":"물류시설법 제2조제3호"},{"t":"복합물류터미널사업: 두 종류 이상의 운송수단 간 연계운송을 할 수 있는 규모·시설을 갖춘 물류터미널사업. 일반물류터미널사업은 복합물류터미널사업을 제외한 것.","src":"물류시설법 제2조제4·5호"},{"t":"물류창고업 제외: 주차장법상 주차장의 자동차 보관·자전거 주차장의 자전거 보관 / 철도사업자가 여객의 수하물·소화물을 보관하는 것 / 위험물저장소에 보관하는 것 등 공동부령 사항.","src":"물류시설법 제2조제5호의3"},{"t":"스마트물류센터: 첨단물류시설·설비·운영시스템 등을 도입한 물류창고로서 국토교통부장관의 인증을 받은 물류창고.","src":"물류시설법 제2조제5호의4"},{"t":"물류단지: 물류단지시설과 지원시설을 집단적으로 설치·육성하기 위해 지정·개발하는 일단의 토지 및 시설. 도시첨단물류단지와 일반물류단지로 구분(스마트물류단지라는 구분은 없다).","src":"물류시설법 제2조제6호"},{"t":"도시첨단물류단지: 도시 내 물류를 지원하고 물류·유통산업과 관련 산업의 육성·개발을 촉진하려는 목적으로 국토계획법상 도시지역에 지정·개발. 일반물류단지는 도시첨단물류단지를 제외한 것.","src":"물류시설법 제2조제6호의2·3"},{"t":"일반물류단지시설: 물류터미널 및 창고 / 대규모점포·전문상가단지·공동집배송센터·중소유통공동도매물류센터 / 농수산물도매시장·공판장·종합유통센터 / 궤도사업자의 화물운송·하역·보관시설 / 축산물 작업장 / 협동조합 등의 구매·판매사업 시설 / 화물자동차운수사업용 차고·화물취급소 등 / 의약품 도매상 창고·영업소 / 대통령령 시설 / 딸린 시설. 수산물가공업 시설(냉동·냉장업 제외)은 해당 없음.","src":"물류시설법 제2조제7호, 기출 2023-12"},{"t":"지원시설: 물류단지시설의 운영을 효율적으로 지원하기 위해 물류단지 안에 설치 - 가공·제조 시설(대통령령) / 정보처리시설 / 금융·보험·의료·교육·연구·업무 시설 / 종사자·이용자 생활·편의시설 / 그 밖에 대통령령 시설.","src":"물류시설법 제2조제8호"},{"t":"물류시설개발종합계획의 기능별 분류: 단위물류시설(창고·집배송센터 등 개별 수행 최소 단위) / 집적물류시설(물류터미널·물류단지 등 둘 이상 단위시설이 함께 설치) / 연계물류시설(시설 상호 간 화물운송을 위한 도로·철도 등 교통시설).","src":"물류시설법 제4조제2항"}]},{"머리":"물류시설개발종합계획(제4~6조)","줄":[{"t":"수립: 국토교통부장관이 5년 단위로 수립하여야 한다.","src":"물류시설법 제4조제1항"},{"t":"포함사항: 장래수요 / 공급정책 / 지정·개발 / 지역별·규모별·연도별 배치 및 우선순위 / 기능개선·효율화 / 공동화·집단화 / 국내·국제 연계수송망 구축 / 환경보전·관리 / 도심지 물류시설의 정비와 교외이전 / 용수·에너지·통신시설 등 기반시설(대통령령). 물류보안은 포함사항이 아니다.","src":"물류시설법 제4조제3항, 시행령 제3조제1항"},{"t":"절차: 관계 행정기관의 장으로부터 소관별 계획을 제출받아 안 작성 → 시·도지사 의견 청취 → 관계 중앙행정기관 협의 → 물류시설분과위원회 심의 → 관보 고시.","src":"물류시설법 제5조제1·2항"},{"t":"심의 재거침 변경: 물류시설별 물류시설용지면적의 100분의 10 이상으로 수요·공급계획을 변경하는 경우.","src":"물류시설법 시행령 제3조제2항"},{"t":"관계 중앙행정기관의 장은 필요한 경우 국토교통부장관에게 변경을 요청할 수 있다. 국토교통부장관은 필요하면 물류시설을 조사할 수 있다(물류정책기본법 제7조 준용).","src":"물류시설법 제5조제3·5항"},{"t":"종합계획은 국가물류기본계획과 조화를 이루어야 한다.","src":"물류시설법 제6조제1항"}]},{"머리":"복합물류터미널사업의 등록(제7~8조)","줄":[{"t":"등록 주체: 국토교통부장관에게 등록.","src":"물류시설법 제7조제1항"},{"t":"등록할 수 있는 자: 국가·지방자치단체 / 대통령령 공공기관 / 지방공사 / 특별법에 따라 설립된 법인 / 민법 또는 상법에 따라 설립된 법인.","src":"물류시설법 제7조제2항"},{"t":"대통령령 공공기관: 한국철도공사·한국토지주택공사·한국도로공사·한국수자원공사·한국농어촌공사·항만공사.","src":"물류시설법 시행령 제4조제1항"},{"t":"등록기준: 지역 운송망 중심지에 위치하여 다른 교통수단과 쉽게 연계 / 부지 면적 3만3천제곱미터 이상 / 주차장·화물취급장·창고 또는 배송센터 구비 / 물류시설개발종합계획 및 국가물류기본계획상 물류터미널 개발·정비계획에 배치되지 아니할 것.","src":"물류시설법 제7조제4항"},{"t":"등록 신청이 들어오면 등록기준 미충족 또는 결격사유가 있는 경우를 제외하고 등록해 주어야 한다.","src":"물류시설법 제7조제5항"},{"t":"변경등록 불필요(시행령 제외 사항): 부지 면적의 통산 10분의 1 미만 변경 / 구조 또는 설비의 변경 / 영업소의 명칭 또는 위치의 변경. 그 밖의 등록사항 변경은 변경등록.","src":"물류시설법 시행령 제4조제2항"},{"t":"결격사유: 이 법 위반으로 벌금형 이상 선고 후 2년 미경과 / 등록 취소 후 2년 미경과(제3호 가목에 해당해 취소된 경우 제외) / 법인의 임원 중 위 해당자, 피성년후견인·파산선고 후 미복권자, 이 법 위반 금고 이상 실형 집행종료·면제 후 2년 미경과, 이 법 위반 금고 이상 집행유예 기간 중인 자가 있는 경우. 직원(임원이 아닌 자)이 파산자여도 결격이 아니다.","src":"물류시설법 제8조, 기출 2024-9"}]},{"머리":"공사시행인가·수용·국공유지(제9~13조)","줄":[{"t":"공사시행인가: 복합물류터미널사업자는 국토교통부장관, 일반물류터미널사업자는 필요한 경우 시·도지사의 인가. 인가 전 시장·군수·구청장 의견 청취. 구조·설비 기준에 적합하면 인가하여야 한다.","src":"물류시설법 제9조"},{"t":"변경인가 사유(시행령): 공사기간 변경 / 부지 면적의 10분의 1 이상 변경 / 건축물 연면적의 10분의 1 이상 변경 / 도로·철도·광장·녹지 등 공공시설 변경. 제조시설·점포 설치 시에도 변경인가.","src":"물류시설법 제9조제1항, 시행령 제5조제2항"},{"t":"물류터미널사업자의 토지등 수용·사용: 도시·군계획시설인 물류터미널에 한정. 국가·지방자치단체·대통령령 공공기관 등이 아닌 자는 사업대상 토지 면적의 3분의 2 이상 소유 + 토지소유자 총수의 2분의 1 이상 동의가 필요.","src":"물류시설법 제10조제1항"},{"t":"공사시행인가 고시가 있으면 사업인정 및 그 고시가 있은 것으로 보며, 재결 신청은 공사시행인가에서 정한 사업시행기간 내에 할 수 있다.","src":"물류시설법 제10조제2항"},{"t":"국·공유지: 물류터미널 건설사업에 필요한 국가·지방자치단체 소유 토지는 건설사업 목적이 아닌 다른 목적으로 매각·양도 불가. 부지 안 국가·지방자치단체 재산은 다른 법령에도 불구하고 물류터미널사업자에게 수의계약으로 매각 가능(미리 관계 행정기관과 협의, 요청받은 날부터 30일 이내 조치).","src":"물류시설법 제13조"}]},{"머리":"승계·휴업·폐업·취소·과징금(제14~18조)","줄":[{"t":"승계: 양도·합병 시 양수인·합병법인이 권리·의무 승계. 승계자는 국토교통부장관에게 신고. 국토교통부장관은 신고일부터 10일 이내 수리 여부 통지, 미통지 시 기간 끝난 날의 다음 날 수리 간주. 결격사유는 제8조 준용.","src":"물류시설법 제14조"},{"t":"휴업·폐업: 전부 또는 일부를 휴업·폐업하려면 미리 국토교통부장관에게 신고. 휴업기간 6개월 초과 불가. 미리 영업소 등 보기 쉬운 곳에 게시. 법인이 합병 외 사유로 해산하면 청산인(파산관재인)이 지체 없이 신고.","src":"물류시설법 제15조"},{"t":"등록증 대여·성명 또는 상호 사용 허용 금지.","src":"물류시설법 제16조"},{"t":"취소 또는 6개월 이내 사업정지(국토교통부장관). 필요적 취소: 거짓·부정 등록 / 결격사유 해당(법인 임원 사유는 3개월 이내 개임하면 예외) / 성명·상호 사용 허용·등록증 대여 / 사업정지명령 위반 영업.","src":"물류시설법 제17조제1항"},{"t":"임의적 사유: 변경등록 없이 등록사항 변경 / 등록기준 미충족(3개월 이내 충족 시 예외) / 인가 없이 공사 시행·변경 / 휴업 후 정당한 사유 없이 휴업기간 지나도 사업 미재개.","src":"물류시설법 제17조제1항제2·3·5·6호"},{"t":"과징금: 사업정지를 명해야 하는 경우로서 이용자에게 심한 불편을 줄 때 정지에 갈음해 5천만원 이하(복합물류터미널사업). 필요적 취소 사유(제1·4·7·8호)에는 부과 불가. 미납 시 국세강제징수 예에 따라 징수.","src":"물류시설법 제18조"},{"t":"과징금 금액(시행령 별표 1): 복합물류터미널 - 변경등록 위반 2차 1,500만원·3차 2,000만원 / 등록기준 미충족 2차 1,500만원·3차 3,000만원 / 인가 없이 공사 2차 1,500만원·3차 2,000만원 / 휴업 후 미재개 2차 3,000만원. 가중해도 총액 5천만원 초과 불가.","src":"물류시설법 시행령 별표 1"}]},{"머리":"물류터미널사업협회·터미널 지원(제19·20조)","줄":[{"t":"협회 설립: 복합물류터미널사업자 및 일반물류터미널을 경영하는 자가 설립. 회원 자격자의 5분의 1 이상 발기인이 정관 작성 → 회원 자격자의 3분의 1 이상 출석한 창립총회 의결 → 국토교통부장관 설립인가. 인가·설립등기로 성립. 법인.","src":"물류시설법 제19조"},{"t":"인가 신청: 사업자 7명 이상의 발기인이 창립총회 의결 후 신청서에 정관·발기인 명부와 이력서·회원 명부·사업계획서와 수입지출계획서·창립총회 회의록 첨부.","src":"물류시설법 시행령 제10조"},{"t":"협회 업무: 공동이익 도모 사업 / 진흥·발전에 필요한 통계 작성·관리, 외국자료 수집·조사·연구 / 경영자·종업원 교육훈련 / 경영개선 지도 / 국토교통부장관 위탁업무.","src":"물류시설법 시행령 제12조"},{"t":"개발 지원: 국가·지방자치단체는 물류터미널 건설·위치 변경·규모 구조 설비 확충 개선에 소요자금 일부를 융자하거나 부지 확보를 지원할 수 있다.","src":"물류시설법 제20조제1항"},{"t":"기반시설 예산 지원 대상(시행령): 도로 / 철도 / 수도시설 / 수질오염방지시설. 보건위생시설 중 종합의료시설은 해당 없음.","src":"물류시설법 제20조제2항, 시행령 제12조의2"}]},{"머리":"물류창고업(제21조의2·3·9·10)","줄":[{"t":"등록 대상: 보관시설 전체 바닥면적의 합계 1천제곱미터 이상 또는 보관장소 전체면적의 합계 4천500제곱미터 이상인 물류창고를 소유 또는 임차하여 경영하려는 자.","src":"물류시설법 제21조의2제1항"},{"t":"등록처: 국토교통부장관(항만구역 제외) / 해양수산부장관(국가관리무역항·국가관리연안항 구역) / 시·도지사(지방관리무역항·지방관리연안항 구역).","src":"물류시설법 제21조의2제1항"},{"t":"변경등록: 성명(법인은 대표자)·상호 / 물류창고 소재지 / 면적의 100분의 10 이상 증감. 변경사유 발생일부터 30일 이내.","src":"물류시설법 제21조의2제2항, 시행령 제12조의3"},{"t":"등록 의제: 관세법 보세창고, 화학물질관리법 유해화학물질 보관·저장업, 식품냉동·냉장업·축산물보관업·수산물가공업(냉동·냉장업)으로만 전부 사용하고 해당 법률상 허가·등록·신고를 한 경우.","src":"물류시설법 제21조의2제4항"},{"t":"준용(제21조의10): 결격사유(제8조), 승계·휴업·폐업·등록증 대여 금지·취소 등(제14~17조)과 협회(제19조)를 준용. 물류창고협회 설립에도 준용.","src":"물류시설법 제21조의10"},{"t":"과징금: 물류창고업자에게 사업정지에 갈음해 1천만원 이하. 필요적 취소 사유에는 부과 불가(취소를 갈음할 수 없음). 별표 1: 변경등록 위반 2차 300만원·3차 400만원 / 등록기준 미충족 2차 300만원·3차 600만원 / 휴업 후 미재개 2차 600만원.","src":"물류시설법 제21조의9, 시행령 별표 1"},{"t":"재정지원: 물류창고업자 또는 사업자단체가 물류창고 건설, 보수·개조·개량, 물류장비 투자, 물류창고 관련 기술 개발, 교육·훈련 등을 하면 보조 또는 융자 가능.","src":"물류시설법 제21조의7제1항"},{"t":"수수료: 복합물류터미널사업 등록·변경등록 / 공사시행인가·변경인가 / 물류창고업 등록·변경등록 / 스마트물류센터 인증 신청. 도시첨단물류단지 지정 신청은 수수료 대상이 아니다.","src":"물류시설법 제63조, 기출 2024-11"},{"t":"내진설계 기준: 국토교통부장관이 물류창고 내 선반 등에 대한 기준을 정하는 시책을 강구하여야 한다.","src":"물류시설법 제21조의3"}]},{"머리":"스마트물류센터(제21조의4~7)","줄":[{"t":"인증 주체: 국토교통부장관(단독). 인증 유효기간 3년. 인증기관을 지정해 인증·점검을 맡길 수 있고, 신청은 인증기관에 한다.","src":"물류시설법 제21조의4제1~3항"},{"t":"인증서 교부·인증마크 사용 / 인증 후 기준 유지 점검 / 인증기관 지도·감독과 비용 일부 지원. 인증 기준·절차·인증기관 지정기준은 국토교통부령.","src":"물류시설법 제21조의4제4~8항"},{"t":"인증 없이 거짓 인증마크 제작·사용 또는 스마트물류센터 사칭: 3천만원 이하 벌금(과태료 아님).","src":"물류시설법 제21조의4제5항, 제65조제2항"},{"t":"인증 취소: 거짓·부정 인증은 취소하여야 한다. 취소할 수 있는 사유 - 인증 근거 중대 사실 변경 / 점검을 정당한 사유 없이 3회 이상 거부 / 인증 기준 미달 / 인증받은 자가 인증서 반납. 취소 시 인증서 반납·인증마크 사용 중지(계속 사용 시 200만원 이하 과태료). 취소는 관보 고시.","src":"물류시설법 제21조의5, 제67조, 시행령 제12조의4"},{"t":"인증기관 지정취소: 거짓·부정 지정은 취소하여야 한다. 지정기준 미달 / 고의·중과실 기준·절차 위반 / 정당한 사유 없이 업무 거부 / 지정 후 2년 이상 업무 미수행 / 업무 수행 불가는 지정취소 또는 1년 이내 업무정지.","src":"물류시설법 제21조의6"},{"t":"스마트물류센터 지원: 국가·지방자치단체·공공기관이 기금·자금 우대 등 행정적·재정적 우선 지원. 구축 비용 일부 보조·융자, 대출금리 차액 보전, 용적률·높이 상한 적용 등. 신용보증기금·기술보증기금이 보증한도·보증료 등 보증조건을 우대할 수 있다(국가·지방자치단체가 아님).","src":"물류시설법 제21조의7제2항, 시행령 제12조의5"}]},{"머리":"물류단지 지정(제22~26조)","줄":[{"t":"일반물류단지 지정권자: 국가정책사업으로 개발하거나 2개 이상 시·도에 걸친 경우 국토교통부장관, 그 외 시·도지사.","src":"물류시설법 제22조제1항"},{"t":"국토교통부장관 지정 절차: 개발계획 수립 → 시·도지사·시장·군수·구청장 의견 청취 → 관계 중앙행정기관 협의 → 물류시설분과위원회 심의. 시·도지사 지정 절차: 관계 행정기관 협의 → 지역물류정책위원회 심의.","src":"물류시설법 제22조제2·3항"},{"t":"지정 요청: 관계 행정기관의 장과 시행자 자격자(제27조제2항 제2~6호)가 대상지역을 정해 요청. 중앙행정기관 이외의 자는 개발계획안을 작성·제출.","src":"물류시설법 제22조제4항"},{"t":"일반물류단지개발계획 포함사항: 명칭·위치·면적 / 지정목적 / 시행자 / 시행기간·방법 / 토지이용계획·주요 기반시설계획 / 주요 유치시설·설치기준 / 재원조달계획 / 수용·사용할 토지 등 세부목록 / 대통령령 사항.","src":"물류시설법 제22조제5항"},{"t":"중요 사항 변경(시행령): 지정 면적·시설용지 면적·기반시설 부지 면적의 10분의 1 이상 변경 / 시설용지 용도변경 / 기반시설 위치 변경 / 시행자 변경.","src":"물류시설법 시행령 제13조제2항"},{"t":"도시첨단물류단지 지정: 국토교통부장관 또는 시·도지사가 노후화된 일반물류터미널 부지·인근 지역, 노후화된 유통업무설비 부지·인근 지역, 그 밖에 필요하다고 인정하는 지역에 지정. 시·도지사(특별자치도지사 제외)가 지정할 때는 시장·군수·구청장의 신청을 받아 지정할 수 있다. 신청 시 개발계획안 작성·제출.","src":"물류시설법 제22조의2제1·2항"},{"t":"도시첨단물류단지개발계획에는 층별·시설별 용도, 바닥면적 등 건축계획과 복합용지이용계획이 포함되어야 한다. 시행자는 대상 부지 토지가액의 일정 범위(고시 기준 100분의 25 범위)에서 일자리 창출시설 등 공익시설 또는 운영비용을 국가·지방자치단체에 제공.","src":"물류시설법 제22조의2제3·4항, 시행령 제14조의2"},{"t":"토지소유자 동의: 도시첨단물류단지 예정지역 토지면적의 2분의 1 이상 토지소유자 + 토지소유자 총수와 건축물 소유자 총수 각 2분의 1 이상.","src":"물류시설법 제22조의3"},{"t":"물류단지개발지침: 국토교통부장관이 작성해 관보 고시. 작성·변경 시 시·도지사 의견 청취 → 관계 중앙행정기관 협의 → 물류시설분과위원회 심의(국토교통부령 경미 사항 변경 제외). 포함사항: 계획적·체계적 개발 / 지정·개발·지원 / 환경보전 / 지역 간 균형발전 / 국가유산 보존 / 토지가격 안정 / 분양가격 결정 / 토지·시설 공급.","src":"물류시설법 제22조의6, 시행령 제15조"},{"t":"물류단지 실수요 검증: 지정 전에 물류단지지정권자가 실시하여야 한다(지정 후 아님). 필요하면 실수요검증위원회 구성·운영 가능. 도시첨단물류단지개발사업은 위원회 자문으로 갈음 가능. 실수요검증위원회는 국토교통부 또는 시·도에 각각 둔다. 위원장·부위원장은 공무원 아닌 위원 중 호선. 심의결과는 심의·의결을 마친 날부터 14일 이내 서면 통지.","src":"물류시설법 제22조의7, 기출 2023-10, 2021-11"},{"t":"주민 의견청취: 지정하려는 때 주민 및 관계 전문가 의견 청취. 시장·군수·구청장이 공고 후 14일 이상 열람, 의견서는 시장·군수·구청장에게 제출(물류단지지정권자에게 직접 제출 아님). 경미 사항(면적 변경 10분의 1 미만 등)은 생략 가능.","src":"물류시설법 제24조, 시행령 제17조"},{"t":"행위허가(시장·군수·구청장): 건축물 건축·대수선·용도변경(가설건축물 포함) / 공작물 설치 / 토지 형질변경 / 토석 채취 / 토지분할 / 이동이 쉽지 않은 물건을 1개월 이상 쌓아놓는 행위 / 죽목 벌채·식재. 허가 불요: 재해복구 응급조치, 간이공작물, 경작용 형질변경, 개발에 지장 없는 토석 채취, 존치하기로 결정된 대지 안에서 물건 쌓아놓기, 관상용 죽목 임시 식재. 이미 착수한 공사는 지정·고시일부터 30일 이내 신고 후 계속. 위반 시 원상회복 명령·행정대집행.","src":"물류시설법 제25조, 시행령 제18조, 기출 2025-13"},{"t":"지정 해제: 지정·고시일부터 5년 이내 실시계획 승인 신청이 없으면 그 기간이 지난 다음 날 해제된 것으로 본다. 임의 해제 - 개발 전망이 없는 경우 / 준공 20년 이상으로 재정비해도 기능 수행이 어려운 경우. 해제 시 14일 이상 열람.","src":"물류시설법 제26조, 시행령 제19조"}]},{"머리":"시행자·실시계획·수용·귀속(제27~37조)","줄":[{"t":"시행자로 지정받을 수 있는 자: 국가·지방자치단체 / 대통령령 공공기관(한국토지주택공사·한국도로공사·한국수자원공사·한국농어촌공사·항만공사) / 지방공사 / 특별법에 따라 설립된 법인 / 민법 또는 상법에 따라 설립된 법인 / 물류단지 예정지역의 토지소유자 또는 그 조합.","src":"물류시설법 제27조제2항, 시행령 제20조"},{"t":"민법·상법 법인 또는 토지소유자(조합)가 승인된 기간 내 완료하지 못하면 물류단지지정권자가 다른 시행자를 지정할 수 있다. 국가·지방자치단체·공공기관·지방공사·특별법인 시행자는 입주기업체·지원기관에 사업 일부를 대행하게 할 수 있다.","src":"물류시설법 제27조제4·5항"},{"t":"실시계획: 시행자가 수립해 물류단지지정권자 승인. 개발한 토지·시설 등의 처분에 관한 사항을 포함. 변경 승인 불필요한 경미 사항 - 주소 변경 / 대표자 변경 / 착오 정정 / 면적 100분의 10 범위 감소 / 사업비 100분의 10 범위 증감 등.","src":"물류시설법 제28조, 시행령 제22조제3항"},{"t":"수용·사용: 토지소유자 또는 그 조합이 시행자(제27조제2항제6호)면 수용·사용 불가. 민법·상법 법인은 사업대상 토지면적의 3분의 2 이상을 매입해야 수용·사용 가능.","src":"물류시설법 제32조제1항"},{"t":"물류단지 지정 고시가 있으면 사업인정 및 그 고시가 있은 것으로 본다. 재결: 국토교통부장관 지정 단지는 중앙토지수용위원회, 시·도지사 지정 단지는 지방토지수용위원회. 재결 신청은 개발계획의 사업시행기간 내에 할 수 있다.","src":"물류시설법 제32조제2·3항"},{"t":"공공시설 귀속: 국가·지방자치단체·공공기관·지방공사·특별법인(제1~4호 시행자)이 설치하면 종래 공공시설은 시행자에게 무상 귀속, 새 공공시설은 관리할 국가 또는 지방자치단체에 무상 귀속. 민법·상법 법인 및 토지소유자·조합(제5·6호)은 새 시설만 관리청에 귀속되고, 폐지되는 국공유 재산은 설치비용 상당 범위에서 무상 양도 가능.","src":"물류시설법 제36조"},{"t":"개발사업 지원: 국가·지방자치단체는 비용 일부를 보조·융자하고, 도로·철도·항만·용수시설 등 기반시설 설치를 우선 지원하여야 한다. 지원 기반시설: 도로·철도·항만시설 / 용수공급시설·통신시설 / 하수도시설·폐기물처리시설 / 공동구 / 집단에너지공급시설 / 국토교통부령 시설.","src":"물류시설법 제39조, 시행령 제29조"},{"t":"물류단지개발특별회계: 시·도지사 또는 시장·군수가 지방자치단체에 설치할 수 있다. 재원 - 일반회계 전입금 / 정부 보조금 / 부과·징수된 과태료 / 개발부담금 중 조례 비율 / 국토계획법상 수익금 / 재산세 징수액 중 10퍼센트(조례로 달리 정하면 그 비율) / 차입금 / 융자회수금·이자수입금 등.","src":"물류시설법 제40조, 시행령 제30조"},{"t":"이주대책: 시행자가 수립·시행. 이주자 또는 인근지역 주민의 우선 고용은 입주기업체 및 지원기관의 의무(시행자 아님).","src":"물류시설법 제45조"},{"t":"준공인가: 시행자가 물류단지지정권자에게 신청. 검사 결과 실시계획대로 완료되면 인가·공고·통지, 완료되지 않으면 지체 없이 보완시공 등 조치를 명하여야 한다. 준공인가 전 사용 불가(사용허가 신청일부터 15일 이내 허가 여부 통지).","src":"물류시설법 제46조"}]},{"머리":"토지·시설 처분, 이행강제금, 취소(제50~52조의3)","줄":[{"t":"분양·임대: 시행자가 개발한 토지·시설을 분양 또는 임대. 입주기업체·지원기관은 분양계약일부터 국토교통부령 기간 안에 건설공사에 착수하거나 토지·시설을 처분하여야 한다.","src":"물류시설법 제50조, 제50조의2"},{"t":"처분제한: 시설 설치 완료 전 분양받은 토지·시설을 처분하려면 시행자 또는 관리기관에 양도. 매수할 수 없으면 다른 입주기업체·지원기관·한국토지주택공사·은행 등에 양도. 토지 양도가격은 취득가격에 이자·비용을 더한 금액.","src":"물류시설법 제51조"},{"t":"이행강제금: 의무를 이행하지 않으면 재산가액(감정평가액)의 100분의 20. 부과 전 문서 예고. 이행기간 만료 다음 날 기준 매년 1회 반복 부과·징수 가능. 의무 이행 시 새 부과는 중지하되 이미 부과된 이행강제금은 징수하여야 한다.","src":"물류시설법 제50조의3"},{"t":"물류단지재정비사업: 준공(부분 준공 포함)된 날부터 20년이 지나 재정비 필요 시 가능. 20년 미만도 업종 재배치 필요 시 가능.","src":"물류시설법 제52조의2제1항"},{"t":"재정비 구분: 전부 재정비 - 토지이용계획·기반시설계획 변경을 수반하고 지정 면적의 100분의 50 이상 재정비. 나머지는 부분 재정비. 부분 재정비는 재정비계획 고시 생략 가능, 분과위원회·지역물류정책위원회 심의 생략 가능.","src":"물류시설법 제52조의2, 시행령 제42조의2"},{"t":"재정비계획: 입주업체·관계 지방자치단체장 의견 청취 + 관계 행정기관 협의 후 수립·고시. 재정비시행계획 승인 전 입주업체·지방자치단체장 의견 청취 + 관계 행정기관 협의. 경미 사항(사업비 100분의 10 범위 증감 등) 외 변경은 승인.","src":"물류시설법 제52조의2제3~6항"},{"t":"지정·승인·인가 취소(국토교통부장관 또는 시·도지사): 거짓·부정으로 단지 지정·시행자 지정·실시계획 승인·준공인가·재정비시행계획 승인을 받은 경우는 취소하여야 한다. 사정 변경으로 사업 계속 시행이 불가능하게 된 경우는 임의(취소 또는 공사 중지 등).","src":"물류시설법 제52조의3"}]},{"머리":"물류단지 관리(제53~59조)","줄":[{"t":"관리기관: 물류단지지정권자가 관리기구 또는 입주기업체협의회에 관리하게 하여야 한다.","src":"물류시설법 제53조제1항"},{"t":"관리기구: 한국토지주택공사 / 한국도로공사 / 한국수자원공사 / 한국농어촌공사 / 항만공사 / 지방공사. 지방자치단체와 한국철도공사는 해당 없음.","src":"물류시설법 시행령 제43조, 기출 2024-16, 2025-14"},{"t":"입주기업체협의회: 구성 당시 입주기업체의 75퍼센트 이상 가입 / 일반회원은 입주기업체 대표자, 특별회원은 정관으로 정함 / 매 사업연도 개시일부터 2개월 이내 정기총회 / 회원 과반수 출석, 출석회원 과반수 찬성 의결.","src":"물류시설법 시행령 제43조의2"}]},{"머리":"물류 교통·환경 정비지구(제59조의4~7)","줄":[{"t":"지정 신청: 시장·군수·구청장이 시·도지사에게. 정비계획을 수립해 제출(둘 이상 시·군·구에 걸치면 관할 시장·군수·구청장이 공동 수립·제출).","src":"물류시설법 제59조의4제1·2항"},{"t":"신청 요건(시행령): 도로 등 기반시설 정비나 소음·진동·미세먼지 저감 등 생활환경 개선이 필요한 지역 + 면적 30만 제곱미터 이상 + 물류시설 총부지면적이 지역 면적의 100분의 30 이상.","src":"물류시설법 시행령 제46조의2"},{"t":"신청 전 절차: 주민설명회 개최, 14일 이상 주민 공람, 지방의회 의견 청취(통지일부터 60일 이내, 미제시 시 이의 없음 간주). 경미 사항(정비지구 면적·정비사업 비용 100분의 5 미만 변경 등)은 생략 가능.","src":"물류시설법 제59조의4제3항, 시행령 제46조의4"},{"t":"지정: 시·도지사가 관계 행정기관 협의(30일 이내 의견) 후 물류단지계획심의위원회와 지방도시계획위원회의 공동 심의를 거쳐 지정. 지방자치단체 공보 고시, 국토교통부장관 보고. 공동위원회는 위원 25명 이내, 위원장은 부시장·부지사.","src":"물류시설법 제59조의5, 시행령 제46조의5"},{"t":"지원 사업: 국가 또는 시·도지사가 시장·군수·구청장에게 - 도로 등 기반시설 신설·확장·개량·보수 / 공영차고지 및 화물자동차 휴게소 설치 / 방음·방진시설 설치 / 전기자동차 충전시설·수소연료공급시설 설치·정비·개량. 유독물 보관·저장시설의 보수·개조는 해당 없음.","src":"물류시설법 제59조의7, 시행령 제46조의8"}]},{"머리":"벌칙·과태료","줄":[{"t":"1년 이하 징역 또는 1천만원 이하 벌금: 무등록 복합물류터미널사업 / 공사시행인가 없이 공사 / 등록증 대여·성명·상호 사용 허용 / 무등록 물류창고업 / 허가 없이 건축물 건축 등 / 거짓·부정 시행자 지정·실시계획 승인 / 처분제한 위반 처분.","src":"물류시설법 제65조제1항"},{"t":"3천만원 이하 벌금: 거짓 인증마크 제작·사용, 스마트물류센터 사칭.","src":"물류시설법 제65조제2항"},{"t":"300만원 이하 과태료: 보고·자료제출 불이행·허위 및 검사 방해·거부. 200만원 이하 과태료: 승계 신고 불이행 / 인증마크 계속 사용. 부과·징수는 국토교통부장관·해양수산부장관 또는 시·도지사.","src":"물류시설법 제67조"},{"t":"공사시행인가 없이 공사한 복합물류터미널사업자, 등록증 대여한 물류창고업자, 부정한 방법으로 시행자 지정을 받은 자는 형사벌 대상이다. 관리기관 업무 검사를 방해·거부한 자는 과태료 대상.","src":"기출 2024-12, 2025-15"}]}],"함정":[{"x":"「철도사업법」에 따른 철도사업자가 그 사업에 사용하는 화물운송ㆍ하역 및 보관 시설은 일반물류단지 안에 설치하더라도 일반물류단지시설에 해당하지 않는다.","o":"기출은 해당한다고 보아 이 문장을 틀린 것으로 처리. 현행 조문은 궤도사업자의 화물운송·하역·보관시설로 규정(제2조제7호라목).","src":"물류시설법 제2조제7호 / 기출 2021-9"},{"x":"복합물류터미널사업의 등록을 하려면 부지 면적이 10,000제곱미터 이상이어야 한다.","o":"3만3천제곱미터 이상이어야 한다.","src":"물류시설법 제7조제4항제2호 / 기출 2021-10"},{"x":"물류단지지정권자는 도시첨단물류단지를 지정한 후 1년 이내에 물류단지 실수요 검증을 실시하여야 한다.","o":"지정 전에 실수요 검증을 실시한다.","src":"물류시설법 제22조의7제1항 / 기출 2021-11"},{"x":"국가 또는 지방자치단체는 스마트물류센터의 구축 및 운영에 필요한 자금의 대출 등으로 인한 금전채무의 보증한도, 보증료 등 보증조건을 우대할 수 있다.","o":"보증조건 우대 주체는 신용보증기금·기술보증기금이다.","src":"물류시설법 시행령 제12조의5제2항 / 기출 2021-13"},{"x":"스마트물류센터 인증의 유효기간은 인증을 받은 날부터 5년으로 한다.","o":"3년으로 한다.","src":"물류시설법 제21조의4제1항 / 기출 2021-13, 2024-14"},{"x":"스마트물류센터 인증의 등급은 3등급으로 구분한다.","o":"기출이 틀린 문장으로 처리(등급 구분은 법령 조문에서 확인되지 않음). 인증 기준·절차·방법은 국토교통부령.","src":"기출 2021-13"},{"x":"스마트물류센터임을 사칭한 자에게는 과태료를 부과한다.","o":"3천만원 이하 벌금(형사벌).","src":"물류시설법 제65조제2항 / 기출 2021-13"},{"x":"물류단지개발사업에 필요한 토지등을 수용하려면 물류단지 지정 고시가 있은 후 「공익사업을 위한 토지 등의 취득 및 보상에 관한 법률」에 따른 사업인정 및 그 고시가 있어야 한다.","o":"물류단지 지정 고시가 있으면 사업인정 및 그 고시가 있은 것으로 본다.","src":"물류시설법 제32조제2항 / 기출 2021-14"},{"x":"물류단지의 부분 재정비사업은 지정된 물류단지 면적의 3분의 2 미만을 재정비하는 사업을 말한다.","o":"지정된 면적의 100분의 50 미만 재정비(전부 재정비는 100분의 50 이상).","src":"물류시설법 시행령 제42조의2 / 기출 2021-16"},{"x":"「항만공사법」에 따른 항만공사는 복합물류터미널사업의 등록을 할 수 있는 자에 해당하지 않는다.","o":"항만공사는 대통령령 공공기관으로 등록할 수 있다.","src":"물류시설법 시행령 제4조제1항제7호 / 기출 2022-11"},{"x":"「물류시설의 개발 및 운영에 관한 법률」을 위반하여 벌금형을 선고받은 후 1년이 지난 자는 복합물류터미널사업의 등록을 할 수 있다.","o":"벌금형 이상 선고 후 2년이 지나지 않으면 등록할 수 없다.","src":"물류시설법 제8조제1호 / 기출 2022-11"},{"x":"부지 면적이 3만제곱미터인 경우는 복합물류터미널사업의 등록기준 중 부지 면적 기준을 충족한다.","o":"3만3천제곱미터 이상이어야 충족한다.","src":"물류시설법 제7조제4항제2호 / 기출 2022-11"},{"x":"복합물류터미널사업자가 그 등록한 사항 중 영업소의 명칭을 변경하려는 경우에는 변경등록을 하여야 한다.","o":"영업소의 명칭·위치 변경은 변경등록 사항이 아니다.","src":"물류시설법 시행령 제4조제2항 / 기출 2022-11"},{"x":"집적[클러스터(cluster)]물류시설은 창고 및 집배송센터 등 물류활동을 개별적으로 수행하는 최소 단위의 물류시설을 말한다.","o":"이것은 단위물류시설의 정의. 집적물류시설은 물류터미널·물류단지 등 둘 이상의 단위물류시설 등이 함께 설치된 시설.","src":"물류시설법 제4조제2항 / 기출 2022-14"},{"x":"도시첨단물류단지개발사업의 경우에는 물류단지 실수요 검증을 실수요검증위원회의 자문으로 갈음할 수 없다.","o":"갈음할 수 있다.","src":"물류시설법 제22조의7제3항 / 기출 2022-15"},{"x":"물류단지개발지침의 내용 중 토지가격의 안정을 위하여 필요한 사항을 변경할 때에는 시ㆍ도지사의 의견을 듣고 관계 중앙행정기관의 장과 협의한 후 물류시설분과위원회의 심의를 거쳐야 한다.","o":"기출은 틀린 문장으로 처리. 법 제22조의6은 변경 시에도 같은 절차를 정하되 국토교통부령으로 정하는 경미한 사항 변경은 제외.","src":"물류시설법 제22조의6제2항 / 기출 2022-15"},{"x":"국가정책사업으로 물류단지를 개발하는 경우 일반물류단지의 지정권자는 시ㆍ도지사가 된다.","o":"국토교통부장관이 지정한다.","src":"물류시설법 제22조제1항제1호 / 기출 2022-15"},{"x":"공고된 물류단지개발계획안의 내용에 대하여 의견이 있는 자는 그 열람기간 내에 물류단지지정권자에게 의견서를 제출할 수 있다.","o":"열람기간 내에 해당 시장·군수·구청장에게 의견서를 제출한다.","src":"물류시설법 시행령 제17조제2항 / 기출 2022-15"},{"x":"물류단지개발사업의 시행자는 특별한 사유가 없으면 이주자 또는 인근지역의 주민을 우선적으로 고용하여야 한다.","o":"우선 고용 의무자는 입주기업체 및 지원기관이다.","src":"물류시설법 제45조제2항 / 기출 2022-16"},{"x":"복합물류터미널사업자의 휴업기간은 3개월을 초과할 수 없다.","o":"6개월을 초과할 수 없다.","src":"물류시설법 제15조제3항 / 기출 2023-9"},{"x":"실수요검증위원회의 회의는 분기별로 2회 이상 개최 하여야 한다.","o":"기출이 틀린 문장으로 처리(분기별 2회 개최 규정은 확인되지 않음). 위원회는 필요한 경우 구성·운영하는 임의 기구.","src":"물류시설법 제22조의7 / 기출 2023-10"},{"x":"입주기업체협의회는 매 사업연도 개시일부터 3개월 이내에 정기총회를 개최하여야 한다.","o":"2개월 이내에 개최한다.","src":"물류시설법 시행령 제43조의2제4항 / 기출 2023-15"},{"x":"스마트물류센터 인증은 국토교통부장관과 해양수산부장관이 공동으로 한다.","o":"국토교통부장관이 한다.","src":"물류시설법 제21조의4제1항 / 기출 2024-14"},{"x":"스마트물류센터 인증에 대한 정기 점검은 인증한 날을 기준으로 5년마다 한다.","o":"기출이 틀린 문장으로 처리. 인증 유효기간은 3년이며 점검은 국토교통부령으로 정하는 바에 따라 한다.","src":"물류시설법 제21조의4제6항 / 기출 2024-14"},{"x":"인증기관의 장은 점검 결과 스마트물류센터가 인증기준을 유지하고 있다고 판단하는 경우에는 인증의 유효기간을 5년의 범위 내에서 연장할 수 있다.","o":"기출이 틀린 문장으로 처리(5년 아님; 유효기간 3년 기준).","src":"기출 2024-14"},{"x":"연계물류시설은 물류터미널 및 물류단지 등 둘 이상의 단위물류시설 등이 함께 설치된 물류시설이다.","o":"이것은 집적물류시설의 정의. 연계물류시설은 시설 간 화물운송을 위한 도로·철도 등 교통시설.","src":"물류시설법 제4조제2항 / 기출 2024-10"},{"x":"물류단지지정권자는 의무가 있는 자가 그 의무를 이행한 경우에는 이미 부과된 이행강제금 처분을 취소하여야 한다.","o":"새로운 부과를 중지하되 이미 부과된 이행강제금은 징수하여야 한다.","src":"물류시설법 제50조의3제5항 / 기출 2024-13"},{"x":"일반물류단지는 물류단지 개발사업의 대상지역이 2개 이상의 시ㆍ도에 걸쳐 있는 경우 시ㆍ도지사가 협의하여 지정한다.","o":"국토교통부장관이 지정한다.","src":"물류시설법 제22조제1항제1호 / 기출 2024-15"},{"x":"시ㆍ도지사는 일반물류단지를 지정하려는 때에는 「물류정책기본법」에 따른 물류시설분과위원회의 심의를 거쳐야 한다.","o":"시·도지사는 지역물류정책위원회 심의를 거친다(물류시설분과위원회는 국토교통부장관 지정 시).","src":"물류시설법 제22조제3항 / 기출 2024-15"},{"x":"국토교통부장관은 시장ㆍ군수ㆍ구청장의 신청을 받아 도시첨단물류단지를 지정한다.","o":"시장·군수·구청장의 신청을 받아 지정하는 주체는 시·도지사(특별자치도지사 제외).","src":"물류시설법 제22조의2제1항 / 기출 2024-15"},{"x":"「민법」 에 따라 설립된 법인은 물류단지개발사업의 시행자로 지정받을 수 없다.","o":"민법 또는 상법에 따라 설립된 법인은 시행자로 지정받을 수 있다.","src":"물류시설법 제27조제2항제5호 / 기출 2024-15"},{"x":"“도시첨단물류단지”란 도시 내 물류를 지원하기 위하여 지정ㆍ개발하는 일단의 토지 및 시설로서 스마트물류단지와 일반물류단지로 구분된다.","o":"물류단지가 도시첨단물류단지와 일반물류단지로 구분된다.","src":"물류시설법 제2조제6호 / 기출 2025-9"},{"x":"보관장소 전체면적의 합계가 2천500제곱미터 이상인 물류창고를 소유 또는 임차하여 물류창고업을 경영하려는 자는 물류창고업의 등록을 하여야 한다.","o":"보관장소는 4천500제곱미터 이상, 보관시설 바닥면적은 1천제곱미터 이상.","src":"물류시설법 제21조의2제1항 / 기출 2025-10"},{"x":"시ㆍ도지사가 일반물류단지를 지정할 때에는 시장ㆍ군수ㆍ구청장의 신청이 있어야 한다.","o":"일반물류단지 지정에는 시장·군수·구청장의 신청이 필수 요건이 아니다(도시첨단물류단지에서 신청을 받아 지정할 수 있다).","src":"물류시설법 제22조, 제22조의2 / 기출 2025-12"},{"x":"「지방공기업법」 에 따른 지방공사가 물류단지개발사업의 시행으로 기존의 공공시설에 대체되는 공공시설을 설치한 경우에는 종래의 공공시설은 그 시설을 관리할 지방자치단체에 무상으로 귀속된다.","o":"종래의 공공시설은 시행자(지방공사)에게 무상 귀속되고, 새로 설치된 공공시설이 관리할 지방자치단체에 귀속된다.","src":"물류시설법 제36조제1항 / 기출 2025-12"},{"x":"물류단지지정권자가 물류단지재정비사업을 하려는 경우에는 입주업체 2분의 1 이상의 동의가 있어야 한다.","o":"입주업체와 관계 지방자치단체장의 의견을 듣는다(동의 요건 없음).","src":"물류시설법 제52조의2제3항 / 기출 2025-12"},{"x":"물류단지개발실시계획의 승인을 한 물류단지지정권자는 시행자가 사정이 변경되어 물류단지개발사업을 계속 시행하는 것이 불가능하게 된 경우 그 승인을 취소하여야 한다.","o":"취소할 수 있다. 거짓·부정 승인일 때만 취소하여야 한다.","src":"물류시설법 제52조의3제1항 / 기출 2025-12"},{"x":"정비지구의 지정을 신청하려면 해당 지역의 면적이 50만 제곱미터 이상이어야 한다.","o":"30만 제곱미터 이상이어야 한다.","src":"물류시설법 시행령 제46조의2제1항제2호 / 기출 2025-16"},{"x":"정비지구가 둘 이상의 시ㆍ군ㆍ구의 관할지역에 걸쳐있는 경우에는 시ㆍ도지사가 물류 교통ㆍ환경 정비계획을 수립한다.","o":"관할 시장·군수·구청장이 공동으로 수립·제출한다.","src":"물류시설법 제59조의4제2항 / 기출 2025-16"},{"x":"정비지구 면적의 100분의 10 미만의 변경을 신청하는 경우에는 주민의 의견청취 절차를 거치지 아니할 수 있다.","o":"100분의 5 미만 변경이 경미 사항.","src":"물류시설법 시행령 제46조의4 / 기출 2025-16"},{"x":"정비지구를 지정하려면 지역물류정책위원회와 「국토의 계획 및 이용에 관한 법률」에 따른 지방도시계획위원회가 공동으로 하는 심의를 거쳐야 한다.","o":"물류단지계획심의위원회와 지방도시계획위원회가 공동으로 심의한다.","src":"물류시설법 제59조의5제1항 / 기출 2025-16"}]},"화물자동차 운수사업법":{"묶음":[{"머리":"정의(제2조)","줄":[{"t":"화물자동차 운수사업: 운송사업·운송주선사업·운송가맹사업 3종.","src":"화물자동차 운수사업법 제2조제2호"},{"t":"운송사업: 다른 사람의 요구에 응하여 화물자동차를 사용하여 화물을 유상으로 운송하는 사업. 화주가 함께 타는 화물은 여객자동차에 싣기 부적합한 화물(국토교통부령 기준).","src":"화물자동차 운수사업법 제2조제3호"},{"t":"화주 동승 화물의 기준(시행규칙): 화주 1명당 중량 20킬로그램 이상 / 화주 1명당 용적 4만 세제곱센티미터 이상 / 불결하거나 악취가 나는 농산물·수산물·축산물 / 혐오감을 주는 동물 또는 식물 / 기계·기구류 등 공산품 / 합판·각목 등 건축기자재 / 폭발성·인화성·부식성 물품 중 어느 하나. 대상차량은 밴형 화물자동차.","src":"화물자동차 운수사업법 시행규칙 제3조의2"},{"t":"운송주선사업: 다른 사람의 요구에 응하여 유상으로 화물운송계약을 중개·대리하거나, 운송사업·가맹사업자의 운송수단을 이용하여 자기 명의와 계산으로 화물을 운송하는 사업(이사화물은 포장·보관 등 부대서비스 포함).","src":"화물자동차 운수사업법 제2조제4호"},{"t":"운송가맹사업: 다른 사람의 요구에 응하여 자기 화물자동차를 사용하여 유상으로 화물을 운송하거나, 화물정보망을 통해 소속 운송가맹점에 의뢰하여 운송하게 하는 사업.","src":"화물자동차 운수사업법 제2조제5호"},{"t":"운송가맹점: 가맹사업자의 화물정보망으로 화물을 배정받아 운송하는 운송사업자 / 가맹사업자의 화물운송계약을 중개·대리하는 운송주선사업자 / 경영의 일부를 위탁받은 위·수탁차주(위탁한 운송사업자가 가맹점이면 제외).","src":"화물자동차 운수사업법 제2조제7호"},{"t":"공영차고지 설치자: 시·도지사 / 시장·군수·구청장 / 대통령령 공공기관 / 지방공사. 대통령령 공공기관: 인천국제공항공사·한국공항공사·한국도로공사·한국철도공사·한국토지주택공사·항만공사. (한국가스공사, 한국농수산식품유통공사는 해당 없음)","src":"화물자동차 운수사업법 제2조제9호, 시행령 제2조"},{"t":"화물차주: 개인 운송사업자 + 경영의 일부를 위탁받은 위·수탁차주. 안전운송운임은 화주가 지급할 최소 운임, 안전위탁운임은 운수사업자가 화물차주에게 지급할 최소 운임.","src":"화물자동차 운수사업법 제2조제11·13호"}]},{"머리":"운송사업 허가·변경·신고(제3조)","줄":[{"t":"허가권자: 국토교통부장관. 일반화물자동차 운송사업 = 20대 이상(시행령 20대)의 화물자동차 사용. 개인화물자동차 운송사업 = 1대 사용.","src":"화물자동차 운수사업법 제3조제1항, 시행령 제3조제1항"},{"t":"운송가맹사업 허가를 받은 자는 운송사업 허가를 따로 받지 않는다. 운송주선사업도 같다.","src":"화물자동차 운수사업법 제3조제2항, 제24조제1항"},{"t":"허가사항 변경은 변경허가가 원칙. 경미한 사항은 신고(통지 기한 3일): 상호 변경 / 대표자 변경(법인) / 화물취급소 설치·폐지 / 화물자동차 대폐차 / 주사무소·영업소·화물취급소 이전(주사무소는 관할 관청 행정구역 내 이전만). 관할 밖 주사무소 이전은 변경허가.","src":"화물자동차 운수사업법 제3조제3·4항, 시행령 제3조제2항"},{"t":"신고 후 통지 기한에 수리 여부를 통지하지 않으면 그 기간이 끝난 날의 다음 날 수리한 것으로 본다.","src":"화물자동차 운수사업법 제3조제5항"},{"t":"증차를 수반하는 허가사항 변경 불가 사유: 개선명령을 받고 이행하지 않은 경우 / 감차 조치 명령을 받은 후 1년이 지나지 않은 경우.","src":"화물자동차 운수사업법 제3조제8항"},{"t":"허가기준 신고: 허가받은 날부터 5년의 범위에서 대통령령이 정한 기간마다(시행령 5년) 신고. 신고서는 5년이 지난 날부터 3개월 이내 제출(개인 운송사업자 제외). 흠이 없으면 도달 시 신고 의무 이행.","src":"화물자동차 운수사업법 제3조제9항, 시행령 제3조제3항, 시행규칙 제14조"},{"t":"영업소: 주사무소 외 장소에 상주하여 영업하려면 국토교통부장관의 허가를 받아 영업소를 설치(신고 아님). 개인 운송사업자는 예외.","src":"화물자동차 운수사업법 제3조제11항"},{"t":"임시허가: 허가취소·감차 조치로 위·수탁계약이 해지된 위·수탁차주였던 자가 3개월 내 신청하면 6개월 이내 기간 한정 허가. 임시허가 기간 내 위·수탁계약을 체결하지 못해 만료되면 3개월 내 정식 허가 신청 가능. 관할관청은 신청일부터 10일 이내 화물자동차 등록 여부 / 허가기준(차고지 등) 적합 여부 / 화물운송 종사자격 보유 여부 / 적재물배상보험등 가입 여부를 확인(채권·채무 여부는 확인사항 아님).","src":"화물자동차 운수사업법 제3조제12·13항, 시행규칙 제7조의2"},{"t":"허가 또는 증차를 수반하는 변경허가에는 조건 또는 기한을 붙일 수 있다(경영 위탁 제한도 이 조건으로 한다).","src":"화물자동차 운수사업법 제3조제14항, 제40조제2항"},{"t":"운송사업자가 사업정지처분을 받은 경우 주사무소를 이전하는 변경허가를 하여서는 아니 된다.","src":"화물자동차 운수사업법 제3조제15항"}]},{"머리":"결격사유(제4조)","줄":[{"t":"운송사업 허가를 받을 수 없는 자(법인은 임원 포함): 피성년후견인·피한정후견인 / 파산선고를 받고 복권되지 않은 자 / 이 법 위반 징역 이상 실형을 선고받고 집행이 끝나거나 면제된 날부터 2년 미경과 / 이 법 위반 징역 이상 집행유예 기간 중인 자.","src":"화물자동차 운수사업법 제4조제1~4호"},{"t":"허가취소 후 기간: 일반 취소 사유 후 2년 미경과 / 부정한 방법으로 허가(제19조제1항제1호) 또는 부정한 방법의 변경허가(제2호)로 취소된 후 5년 미경과.","src":"화물자동차 운수사업법 제4조제5·6호"},{"t":"법인 임원이 결격이어도 3개월 이내에 그 임원을 개임하면 허가를 취소하지 않는다.","src":"화물자동차 운수사업법 제19조제1항제5호"}]},{"머리":"운임·요금·안전운임(제5조, 제5조의9~13)","줄":[{"t":"운임·요금 신고: 시행령상 신고 대상은 구난형 특수자동차 이용 사업자와 밴형 화물자동차로 화주와 화물을 함께 운송하는 사업자. 국토교통부장관은 신고일부터 14일 이내 수리 여부 통지.","src":"화물자동차 운수사업법 제5조, 시행령 제4조"},{"t":"신고 대리: 운임·요금 신고는 협회·연합회가 대리할 수 있다(기출 O).","src":"기출 2021-19"},{"t":"안전운임위원회: 국토교통부장관 소속. 위원장 포함 15명 이내(화물차주·운수사업자·화주 각 3명, 공익 4명). 위원장은 공익위원 중 위원회가 선출. 관계 행정기관 공무원 3명 이내 특별위원 둘 수 있음. 위원 임기 1년, 연임 가능. 회의는 재적 과반수 출석, 출석 과반수 찬성.","src":"화물자동차 운수사업법 제5조의9, 시행령 제4조의10"},{"t":"안전운송원가 심의 시 고려: 인건비·감가상각비 등 고정비용 / 유류비·부품비 등 변동비용 / 상하차 대기료, 운송사업자의 운송서비스 수준 등.","src":"화물자동차 운수사업법 제5조의10"},{"t":"공표: 국토교통부장관이 매년 10월 31일까지 다음 연도 적용 안전운송원가·안전운임을 공표. 안전운임 품목: 특수자동차로 운송되는 수출입 컨테이너, 시멘트.","src":"화물자동차 운수사업법 제5조의11"},{"t":"효력: 화주는 안전운송운임 이상 지급, 운수사업자는 화물차주에게 안전위탁운임 이상 지급. 미달 부분은 무효로 하며 안전운임과 동일한 운임을 지급하기로 한 것으로 본다(취소·재계약 아님). 서로 부정한 금품 수수 금지(2년 이하 징역 또는 2천만원 이하 벌금). 안전운임보다 적게 지급하면 1천만원 이하 과태료.","src":"화물자동차 운수사업법 제5조의12, 제67조, 제70조"},{"t":"주지 의무: 안전운임을 적용받는 화주와 운수사업자는 게시 등으로 운수사업자와 화물차주에게 알려야 한다.","src":"화물자동차 운수사업법 제5조의13"}]},{"머리":"운송약관·적재물사고 책임(제6·7조)","줄":[{"t":"운송약관: 운송사업자가 정하여 국토교통부장관에게 신고(허가 아님). 국토교통부장관은 3일 이내 수리 여부 통지. 신고는 협회가 대리할 수 있다.","src":"화물자동차 운수사업법 제6조제1~3항"},{"t":"표준약관: 협회·연합회가 작성해 공정거래위원회 심사를 거친 약관. 국토교통부장관이 운송사업자에게 사용을 권장(공정거래위원회가 권장하는 것 아님). 허가·변경허가 시 표준약관 사용에 동의하면 약관을 신고한 것으로 본다. 약관에는 운송책임이 시작·끝나는 시기를 적는다.","src":"화물자동차 운수사업법 제6조제4·5항"},{"t":"적재물사고(멸실·훼손·인도지연) 손해배상은 상법 제135조 준용. 인도기한이 지난 후 3개월 이내 인도되지 않으면 멸실된 것으로 본다.","src":"화물자동차 운수사업법 제7조제1·2항"},{"t":"분쟁조정: 화주가 요청하면 국토교통부장관이 조정. 지체 없이 사실 확인·손해 조사 후 조정안 작성(작성하여야 한다). 당사자 쌍방이 수락하면 조정안과 동일한 합의 성립으로 본다. 한국소비자원 또는 소비자기본법상 등록 소비자단체에 업무 위탁 가능.","src":"화물자동차 운수사업법 제7조제3~6항"}]},{"머리":"운전업무 종사자격(제8·9조)","줄":[{"t":"자격 요건: 연령·운전경력 요건 + 운전적성 정밀검사 기준 적합 + (국토교통부장관 시험 합격 후 교육 이수, 또는 교통안전체험 이론·실기 교육 이수). 자격증 발급: 국토교통부장관.","src":"화물자동차 운수사업법 제8조"},{"t":"자격증 대여·차용·알선 금지: 1년 이하 징역 또는 1천만원 이하 벌금.","src":"화물자동차 운수사업법 제8조제3~5항, 제68조"},{"t":"자격 결격: 운송사업 허가 결격 중 제4조제3·4호 해당자 / 자격 취소 후 2년 미경과 / 운전면허 취소·벌금형 이상 확정 후 5년 미경과(일정 사유) / 일정 사유로 면허 취소 후 3년 미경과.","src":"화물자동차 운수사업법 제9조"},{"t":"자격이 없는 자에게 운송하게 하면 허가 취소·사업정지·감차 사유(제19조제1항제6호). 종사자격증 없이 운전업무 종사: 500만원 이하 과태료.","src":"화물자동차 운수사업법 제19조, 제70조제2항"}]},{"머리":"운송사업자 준수사항(제11조, 시행규칙 제21조)","줄":[{"t":"금지: 부당한 운송조건·정당한 사유 없는 운송계약 인수 거부 / 운전자 과도 승차근무 / 기준에 맞지 않는 화물 운송 / 자동차관리사업자와 부정한 금품 수수 / 운임·요금을 부당하게 화주·다른 운송사업자·주선사업자에게 되돌려주는 행위 / 택시 요금미터기 장착 등 택시 유사표시행위.","src":"화물자동차 운수사업법 제11조"},{"t":"운송사업 양도·양수 비용을 위·수탁차주에게 부담시키는 것 금지. 현물출자 차량을 위·수탁차주 동의 없이 매도·저당 설정 금지. 위·수탁차주가 다른 운송사업자와 동시에 1년 이상 운송계약을 체결하는 것을 제한하거나 불이익 금지. 운임·요금과 운송약관을 영업소 또는 화물자동차에 갖추어 두고 요구 시 내보인다.","src":"화물자동차 운수사업법 제11조제8항·제14~16항"},{"t":"적재된 화물이 떨어지지 않도록 덮개·포장·고정장치 등 조치 의무(운수종사자도 해당). 이를 하지 않아 사람을 상해·사망에 이르게 하면 5년 이하 징역 또는 2천만원 이하 벌금. 자동차 튜닝 승인 없이 운행 금지(시행규칙).","src":"화물자동차 운수사업법 제11조제20항, 제12조제1항제8호, 제66조"},{"t":"밤샘주차(0시부터 4시 사이 1시간 이상 주차): 운송사업자 차고지 / 다른 운송사업자 차고지 / 공영차고지 / 화물자동차 휴게소 / 화물터미널 / 조례로 정하는 시설·장소에서만. 최대적재량 1.5톤 이하는 주차장·차고지 또는 조례로 정하는 시설·장소에서만. (휴게소 주차 가능)","src":"화물자동차 운수사업법 시행규칙 제21조제3·4호"},{"t":"개인 운송사업자: 주사무소가 있는 시·도와 이와 맞닿은 시·도 외의 지역에 상주해 영업 금지. 자기 명의로 계약한 화물을 수수료를 받고 다른 운송사업자에게 위탁·대행 금지. 화주의 부당 운임 환급 요구 시 환급. 밴형 화물자동차 사업자는 바깥쪽에 '화물'을 한국어·영어·중국어·일본어로 표시.","src":"화물자동차 운수사업법 시행규칙 제21조제2·6·8·18호"},{"t":"운수종사자 금지: 정당한 사유 없이 화물 중도 하차·운송 거부 / 부당한 운임·요금 요구 / 자동차관리사업자와 부정한 금품 수수 / 일정 장소에 오랜 시간 정차해 화주 호객 / 문 완전히 닫지 않은 출발·운행 / 택시 유사표시행위 / 화물 이탈방지 조치 없이 운행 / 최고속도제한장치 무단 해체·조작. 2시간 연속운전 후 15분 이상 휴게.","src":"화물자동차 운수사업법 제12조, 시행규칙 제22조"}]},{"머리":"직접운송 의무·위탁(제11조의2, 제34조의4)","줄":[{"t":"일반화물자동차 운송사업자: 연간 운송계약 화물의 100분의 50 이상을 직접 운송(사업기간 1년 미만은 신규허가일 등부터 12월 31일 기준).","src":"화물자동차 운수사업법 시행규칙 제21조의5제1항"},{"t":"운송사업과 운송주선사업을 동시에 영위하면 연간 운송계약 및 운송주선계약 화물의 100분의 30 이상 직접 운송.","src":"화물자동차 운수사업법 제11조의2제4항, 시행규칙 제21조의5제3항"},{"t":"직접 운송 외 화물의 위탁 상대: 다른 운송사업자 또는 다른 운송사업자에게 소속된 위·수탁차주만 가능. 운송가맹사업자의 화물정보망(또는 물류정책기본법 인증 화물정보망)을 이용해 위탁하면 직접 운송한 것으로 본다(인정 기준은 위탁운송 화물의 100분의 80~100 범위에서 고시).","src":"화물자동차 운수사업법 제11조의2제2·5항, 시행규칙 제21조의5제4항"},{"t":"화물정보망 이용 가능: 운송사업자가 다른 운송사업자·그 소속 위·수탁차주에게 위탁할 때, 운송주선사업자가 운송사업자·위·수탁차주에게 위탁할 때.","src":"화물자동차 운수사업법 제34조의4"},{"t":"실적 신고: 개인 운송사업자를 제외한 운송사업자·운송주선사업자·운송가맹사업자가 운송 또는 주선 실적을 관리하고 국토교통부장관에게 신고. 직접 운송 실적, 화주와의 계약 실적, 다른 운수사업자와의 계약 실적, 가맹사업자의 소속 가맹점과의 계약 실적이 대상.","src":"화물자동차 운수사업법 제47조의2"}]},{"머리":"개선명령·업무개시명령(제13·14조, 제31조)","줄":[{"t":"운송사업자 개선명령(국토교통부장관): 운송약관 변경 / 화물자동차 구조변경·운송시설 개선 / 화물의 안전운송 조치 / 적재물배상보험등 및 자동차손해배상 보장법상 보험·공제 가입 / 위·수탁 차량 번호판·대폐차·사용본거지 변경 관련 조치 / 대통령령 사항. 가맹사업법상 정보공개서 제공의무 통지는 운송가맹사업자 개선명령 사항이지 운송사업자 사항이 아니다.","src":"화물자동차 운수사업법 제13조, 제31조"},{"t":"운송가맹사업자 개선명령은 국토교통부장관이 한다(시장·군수·구청장 아님).","src":"화물자동차 운수사업법 제31조"},{"t":"업무개시 명령: 운송사업자나 운수종사자가 정당한 사유 없이 집단으로 화물운송을 거부해 국가경제에 매우 심각한 위기를 초래할 우려가 있을 때 국토교통부장관이 명령. 국무회의 심의를 거치고 국회 소관 상임위원회에 보고. 대상은 운송사업자·운수종사자이며 운송주선사업자는 해당 없음.","src":"화물자동차 운수사업법 제14조, 제28조"}]},{"머리":"양도·상속·휴업·폐업(제16~18조)","줄":[{"t":"양도·양수: 양수인이 국토교통부장관에게 신고(승인 아님). 5일 이내 수리 여부 통지. 신고되면 양수인이 운송사업자 지위 승계, 위·수탁계약도 동일 내용으로 승계. 양수인 결격은 제4조 준용. 조건부 허가(전기·수소차 위탁금지 조건 등) 운송사업자는 사업 양도 불가.","src":"화물자동차 운수사업법 제16조"},{"t":"상속: 운송사업자 사망 시 상속인이 계속하려면 사망 후 90일 이내 신고. 5일 이내 수리 여부 통지. 신고하면 사망일부터 신고일까지 피상속인의 허가는 상속인의 허가로 본다. 상속인이 사망일부터 3개월 이내 다른 사람에게 양도하면 그 기간 허가는 상속인에 대한 허가로 본다. 양도에 승인은 필요 없다.","src":"화물자동차 운수사업법 제17조"},{"t":"휴업·폐업: 미리 국토교통부장관에게 신고 + 영업소 등 보기 쉬운 곳에 게시. 폐업신고 시 해당 화물자동차의 자동차등록증·번호판 반납. 신고 의무는 신고서가 접수기관에 도달된 때 이행된 것으로 본다(수리 통지 시 아님). 관할관청은 폐업신고 사실을 협회에 통지.","src":"화물자동차 운수사업법 제18조, 제20조, 기출 2022-25"}]},{"머리":"운송사업 허가취소·정지·과징금(제19~21조)","줄":[{"t":"취소 또는 6개월 이내 사업의 전부·일부 정지 또는 감차 조치명령(국토교통부장관). 반드시 취소: 부정한 방법의 허가 / 결격사유 해당(법인 임원 3개월 내 개임 시 예외) / 거짓 보험금 청구로 금고 이상 형 확정.","src":"화물자동차 운수사업법 제19조제1항"},{"t":"임의적 사유 예: 6개월 운송실적 미달 / 부정한 방법의 변경허가·변경허가 없는 변경 / 허가기준 미충족 / 허가기준 신고 불이행·허위 신고 / 영업소 허가 없이 상주 영업(2대 이상) / 조건·기한 위반 / 종사자격 없는 자 운송 / 준수사항 위반 / 직접운송 의무 위반 / 개선명령 불이행 / 업무개시명령 불이행 / 사업 양도 제한 위반 / 사업정지·감차명령 위반 / 중대하거나 빈번한 교통사고로 1명 이상 사상자 / 보조금 정지 후 5년 내 재위반 / 연한 초과 차량 검사 미수검 운행.","src":"화물자동차 운수사업법 제19조제1항"},{"t":"운송사업자의 허가취소·감차 시 위·수탁계약 해지로 보는 사유: 제19조제1항 제1·2·3·5호 등. 처분 대상 차량이 2대 이상이면 화물운송 영향을 고려해 분할 집행 가능.","src":"화물자동차 운수사업법 제40조의3제3항, 기출 2024-20"},{"t":"과징금: 사업정지처분 대상이 이용자에게 심한 불편을 주면 정지에 갈음해 2천만원 이하. 미납 시 국세 체납처분 예에 따라 징수. 사용처: 화물터미널 건설·확충 / 공동차고지 건설·확충 / 경영개선·화물 정보 제공 사업 / 신고포상금 지급. 징수 금액의 운용계획을 국토교통부장관이 수립·시행.","src":"화물자동차 운수사업법 제21조"},{"t":"사업정지·허가취소 시 자동차등록증·번호판을 국토교통부장관에게 반납. 정지기간이 끝나면 되돌려 받는다.","src":"화물자동차 운수사업법 제20조"}]},{"머리":"운송주선사업(제24~28조)","줄":[{"t":"허가: 국토교통부장관. 허가사항 변경은 신고(변경허가 아님), 5일 이내 수리 여부 통지. 영업소는 허가를 받아 설치. 허가기준 신고는 제3조제9항 준용(5년마다).","src":"화물자동차 운수사업법 제24조"},{"t":"허가기준: 고시하는 공급기준에 맞을 것 + 사무실 면적 등 국토교통부령 기준.","src":"화물자동차 운수사업법 제24조제6항"},{"t":"명의이용 금지: 자기 명의로 다른 사람에게 운송주선사업을 경영하게 할 수 없다.","src":"화물자동차 운수사업법 제25조"},{"t":"준수사항: 자기 명의로 계약한 화물을 계약금액 일부를 제외한 금액으로 다른 주선사업자와 재계약해 운송하게 하는 행위 금지 / 화주로부터 중개·대리를 의뢰받은 화물을 수수료를 받고 다른 주선사업자에게 중개·대리 의뢰 금지 / 운송사업자에게 화물 종류·무게·부피를 거짓 통보하거나 기준 위반 화물 운송 주선 금지. 운송가맹사업자에게 주선하는 행위는 위 금지에서 제외.","src":"화물자동차 운수사업법 제26조"},{"t":"허가취소·정지(국토교통부장관): 반드시 취소 - 결격사유 해당(법인 임원 3개월 내 개임 시 예외) / 거짓·부정 허가 / 사업정지명령 위반 영업. 임의 - 허가기준 미충족 / 기준 신고 불이행 / 영업소 허가 없는 영업 / 명의이용 금지 위반 / 준수사항 위반 / 개선명령 불이행 등.","src":"화물자동차 운수사업법 제27조"},{"t":"허가 없이 또는 부정한 방법으로 허가받아 운송주선사업 경영: 2년 이하 징역 또는 2천만원 이하 벌금(과태료 아님). 명의이용 금지 위반도 형사벌.","src":"화물자동차 운수사업법 제67조제4·5호"},{"t":"운송주선사업자의 손해배상 책임에 상법 제135조 준용(기출). 허가사항 변경 시 신고 대상: 상호·대표자 등.","src":"화물자동차 운수사업법 제28조, 기출 2025-21"}]},{"머리":"운송가맹사업(제29~34조)","줄":[{"t":"허가: 국토교통부장관. 변경허가 원칙, 경미 사항은 신고. 허가·신고 통지 기한 20일. 기한 내 미통지 시 끝난 날의 다음 날 허가·수리 간주. 영업소는 허가를 받아 설치.","src":"화물자동차 운수사업법 제29조"},{"t":"변경신고 대상(시행령): 대표자 변경(법인) / 화물취급소 설치·폐지 / 화물자동차 대폐차(직접 소유한 경우) / 주사무소·영업소·화물취급소 이전 / 운송가맹계약 체결 또는 해제·해지. 상호 변경은 허가사항 변경신고 대상이 아니다.","src":"화물자동차 운수사업법 시행령 제9조의2, 기출 2025-22"},{"t":"허가사항 변경신고 서류 관리: 허가대장은 전자적 처리가 불가능한 특별한 사유가 없으면 전자적 방법으로 작성·관리.","src":"기출 2021-24, 2024-18"},{"t":"가맹사업자 이행사항: 직접운송물량과 가맹점 운송물량의 공정한 배정 / 효율적 운송기법 개발·보급 / 화물정보망 설치·운영. 가맹점 이행사항: 가맹사업자 기준에 맞는 운송서비스 제공 / 차량 위치의 통지(운송사업자·위·수탁차주인 가맹점) / 운송화물 확보·공급(주선사업자인 가맹점).","src":"화물자동차 운수사업법 제30조"},{"t":"가맹사업자 개선명령은 국토교통부장관. 사항: 운송약관 변경 / 구조변경·운송시설 개선 / 안전운송 조치 / 가맹사업법 정보공개서 제공 등 / 적재물배상보험등 가입 / 대통령령 사항.","src":"화물자동차 운수사업법 제31조"},{"t":"가맹사업 허가취소(국토교통부장관): 필요적 - 결격사유 해당(임원 3개월 내 개임 예외), 거짓·부정 허가. 임의 - 변경허가 위반·기준 미충족·기준 신고 불이행·영업소 무허가·개선명령 불이행·준수사항 위반·정지/감차 명령 위반·교통사고·검사 미수검 등. 거짓·부정 허가는 반드시 취소(6개월 정지 사유가 아님).","src":"화물자동차 운수사업법 제32조"}]},{"머리":"적재물배상보험등(제35~38조)","줄":[{"t":"의무가입자: 최대 적재량 5톤 이상이거나 총 중량 10톤 이상인 화물자동차 중 국토교통부령 차량을 소유한 운송사업자 / 이사화물을 취급하는 운송주선사업자 / 운송가맹사업자.","src":"화물자동차 운수사업법 제35조, 시행규칙 제41조의13"},{"t":"가입 대상 차량: 일반형·밴형·특수용도형 화물자동차와 견인형 특수자동차. 제외 - 경제적 가치 없는 화물(건축폐기물·쓰레기) 운송 차량 / 배출가스저감장치로 총중량 10톤 이상이 된 최대적재량 5톤 미만 차량 / 특수용도형 중 피견인자동차.","src":"화물자동차 운수사업법 시행규칙 제41조의13제1항"},{"t":"가입 금액: 사고 건당 2천만원 이상(이사화물운송만 주선하는 운송주선사업자는 500만원 이상). 운송사업자는 각 화물자동차별, 운송주선사업자는 각 사업자별, 운송가맹사업자는 직접 소유 차량이 있으면 각 차량별 및 각 사업자별.","src":"화물자동차 운수사업법 시행령 제9조의7"},{"t":"보험회사등은 의무가입자의 계약 체결을 거부할 수 없다(대통령령 사유 제외). 계약 해제·해지 불가가 원칙이며 예외: 감차 허가사항 변경 / 휴업·폐업 / 허가취소 또는 감차 조치명령 / 이중 가입 해지 / 보험회사 파산 등.","src":"화물자동차 운수사업법 제36조, 제37조"},{"t":"계약 종료 통지: 보험회사등이 계약 종료일 30일 전과 10일 전에 각각 통지. 미가입 시 500만원 이하 과태료라는 안내 포함. 계약 종료 후 새 계약을 체결하지 않으면 지체 없이 국토교통부장관(관할관청)에 알림.","src":"화물자동차 운수사업법 제38조, 시행규칙 제41조의15"},{"t":"미가입 제재: 500만원 이하 과태료(형벌 아님). 계약 체결 거부·해제·해지 위반 보험회사등도 과태료.","src":"화물자동차 운수사업법 제70조제2항제15~18호"}]},{"머리":"경영의 위탁·위수탁계약(제40~40조의5)","줄":[{"t":"경영 위탁: 운송사업자는 차량과 그 경영의 '일부'를 다른 사람(운송사업자를 제외한 개인)에게 위탁하거나 차량을 현물출자한 사람에게 경영의 일부를 위탁할 수 있다. 전부 위탁 불가, 다른 운송사업자에게 위탁 불가. 국토교통부장관이 허가 조건으로 위탁을 제한할 수 있다.","src":"화물자동차 운수사업법 제40조제1·2항"},{"t":"위·수탁계약: 대등한 입장의 합의, 차량 소유자·계약기간 등 명시한 계약서를 서명날인해 서로 교부(미교부 시 500만원 이하 과태료). 양도·양수 사항·운수종사자 교육 사항 명시. 표준 위·수탁계약서는 국토교통부장관이 고시하고 우선 사용 '권고'(강제 아님). 계약기간 2년 이상.","src":"화물자동차 운수사업법 제40조제3~5항, 제11조, 기출 2023-18, 2025-25"},{"t":"분쟁 지원: 시·도지사가 화물운송사업분쟁조정협의회 설치·운영. 5명 이상 10명 이내 위원, 매월 1회 개최. 심의 결과 조정안을 작성해 분쟁당사자에게 '권고'할 수 있다(따를 의무 없음). 심의 사항: 금전지급·차량 소유권·대폐차·양도양수 분쟁 등.","src":"화물자동차 운수사업법 제40조제6항, 시행령 제9조의9"},{"t":"불공정 계약 무효: 계약내용이 일방에게 현저히 불공정한 경우 그 '부분'에 한정해 무효 - 예상하기 어려운 내용 책임 전가 / 일방 의사로 계약내용 결정 / 손해배상책임을 과도하게 경감하거나 가중 / 상대방 권리를 상당한 이유 없이 배제·제한 / 그 밖의 대통령령 사항. 계약 전부 무효가 아님.","src":"화물자동차 운수사업법 제40조제7항"},{"t":"갱신 요구: 계약기간 만료 전 150일부터 60일까지 사이에 위·수탁차주가 요구하면 거절 불가(예외 있음). 거절은 요구를 받은 날부터 15일 이내 사유를 적어 서면 통지.","src":"화물자동차 운수사업법 제40조의2제1·2항"},{"t":"갱신 거절 사유: 전체 계약기간 6년 이하 - 거짓·부정 계약 체결 / 중대 사유(준수사항 위반으로 처벌·과태료, 종사자격 처분, 신고 자료 제출 요청·지도감독 불응 등). 6년 초과 - 위 사유 + 월지급액 6회 이상 미지급 / 표준계약서 조건 불준수 / 운송사업자의 사업 폐업 등. 화물운송 종사자격 효력정지 처분을 받은 경우 갱신 거절 가능.","src":"화물자동차 운수사업법 제40조의2, 시행령 제9조의10, 기출 2023-18"},{"t":"묵시적 갱신: 거절 통지 또는 계약 조건 변경·불갱신 통지를 기간 내(150일~60일 사이)에 서면으로 하지 않으면 같은 조건으로 다시 체결한 것으로 본다. 단 위·수탁차주가 계약 만료일 30일 전까지 이의를 제기하거나 천재지변 등 부득이한 사유가 있으면 예외.","src":"화물자동차 운수사업법 제40조의2제3항"},{"t":"해지: 2개월 이상의 유예기간을 두고 계약 위반 사실을 구체적으로 밝혀 시정하지 않으면 해지한다는 사실을 서면으로 2회 이상 통지. 절차를 거치지 않은 해지는 효력이 없다. 예외(중대 사유) - 종사자격 미보유 / 준수사항 위반 처벌·과태료 / 종사자격 처분 / 일신상 사유로 경영 불가.","src":"화물자동차 운수사업법 제40조의3, 시행령 제9조의11"},{"t":"계약상 지위 양도: 운송사업자의 동의 필요. 통지일부터 1개월 이내 거절하지 않으면 동의한 것으로 본다. 운송사업자는 사업을 양도·양수하는 경우 그 비용을 위·수탁차주에게 부담시킬 수 없다.","src":"화물자동차 운수사업법 제40조의4, 제11조제14항"},{"t":"실태조사: 국토교통부장관 또는 시·도지사가 정기적으로 위·수탁계약서 작성 여부를 조사할 수 있다(횟수 법정 없음).","src":"화물자동차 운수사업법 제40조의5"}]},{"머리":"재정지원·공영차고지(제43~45조)","줄":[{"t":"국가의 보조·융자 사업: 공동차고지 및 공영차고지 건설 / 운수사업 정보화 / 낡은 차량 대체 / 연료비 절감·환경친화적 화물자동차 전환 시설·장비 / 화물자동차 휴게소 건설 / 서비스 향상 시설·장비 확충·개선 / 경영합리화 사항. 운수사업자의 사고 손해배상 책임 보장, 운수사업 홍보는 대상이 아니다.","src":"화물자동차 운수사업법 제43조제1항, 기출 2023-23, 2024-17"},{"t":"공영차고지: 설치자가 직접 운영하거나 사업자단체·운송사업자·운송가맹사업자·운송사업자 협동조합에 임대(운영 위탁 포함). 운송주선사업자는 임대 대상이 아니다. 설치·운영계획은 시·도지사 제외 설치자가 수립하면 시·도지사 인가.","src":"화물자동차 운수사업법 제45조"}]},{"머리":"화물자동차 휴게소(제46조의2~6)","줄":[{"t":"휴게소 종합계획: 국토교통부장관이 5년 단위로 수립. 수립·변경 시 미리 시·도지사 의견 청취 + 관계 중앙행정기관 협의. 관보 고시.","src":"화물자동차 운수사업법 제46조의2"},{"t":"건설사업 시행자: 국가·지방자치단체 / 대통령령 공공기관 / 지방공사 / 이들이 지정한 법인. 공공기관: 한국철도공사·한국토지주택공사·한국도로공사·한국수자원공사·한국농어촌공사·항만공사·인천국제공항공사·한국공항공사·한국교통안전공단·국가철도공단.","src":"화물자동차 운수사업법 제46조의3제1항, 시행령 제9조의19"},{"t":"건설계획: 공고 후 관계 서류 사본을 20일 이상 열람. 이해관계인 의견서 제출 가능. 승인권자는 시·도지사(국가·공공기관 시행자 등은 국토교통부장관). 60일 이내 결정, 미결정 시 승인 간주. 거짓·부정 승인은 취소하여야 한다.","src":"화물자동차 운수사업법 제46조의3"},{"t":"건설 대상지역(시행규칙): 항만·산업단지 지역으로 일평균 왕복 교통량 1만5천대 이상 / 국가관리항 지역 / 면적 50만 제곱미터 이상 물류단지 / 고속국도·일반국도·지방도 인접 지역으로 일평균 편도 교통량 3천5백대 이상 / 졸음운전 사망사고 발생 지역 등.","src":"화물자동차 운수사업법 시행규칙 제43조의3"},{"t":"휴게소 운영 위탁: 협회·연합회 / 공공기관·지방공기업(국가·지방자치단체 위탁 시) / 화물운수 관련 법인.","src":"화물자동차 운수사업법 제46조의6, 시행령 제9조의20"}]},{"머리":"협회·연합회·공제(제48~52조)","줄":[{"t":"협회: 운송사업·운송주선사업·운송가맹사업의 종류별 또는 시·도별로 설립. 회원 자격자의 5분의 1 이상 발기, 3분의 1 이상 동의를 받아 창립총회에서 정관 작성 후 국토교통부장관에게 인가 신청. 법인, 설립등기로 성립. 정관 변경은 인가.","src":"화물자동차 운수사업법 제48조"},{"t":"협회 사업: 건전한 발전·공동이익 / 통계 작성·관리, 외국 자료 수집·조사·연구 / 경영자와 운수종사자 교육훈련 / 경영개선 지도 / 국가나 지방자치단체로부터 위탁받은 업무. 협회가 적재물배상 공제사업을 할 수 있으려면 국토교통부장관의 허가를 받은 연합회가 해야 한다(협회는 아님).","src":"화물자동차 운수사업법 제49조, 제51조"},{"t":"연합회: 운송사업자 협회·주선사업자 협회·가맹사업자 협회가 각각 설립. 연합회가 허가를 받아 자동차 사고 손해배상 책임 보장사업 및 적재물배상 공제사업 가능.","src":"화물자동차 운수사업법 제50·51조"},{"t":"공제조합 설립: 조합원 자격자의 10분의 1 이상 발기, 조합원 자격자 200인 이상의 동의를 받아 창립총회에서 정관 작성 후 국토교통부장관에게 인가 신청. 운영위원회를 두어 공제사업을 심의·의결하고 감독.","src":"화물자동차 운수사업법 제51조의3·4"},{"t":"운영위원회 위원 수: 25명 이내. 연합회가 공제사업을 하는 경우 시·도별 협회 대표 전원을 포함해 37명 이내.","src":"화물자동차 운수사업법 제51조의4제2항"},{"t":"공제조합은 결산기마다 사업 종류에 따라 책임준비금과 지급준비금을 계상하고 적립. 국토교통부장관은 업종별(연합회별)로 하나의 공제조합만 인가.","src":"화물자동차 운수사업법 제51조의6, 기출 2024-19"}]},{"머리":"자가용 화물자동차·교육(제55~56조의2, 제59조)","줄":[{"t":"자가용 화물자동차 사용신고: 시·도지사에게 신고(허가 아님). 대상: 특수자동차(부령) 또는 최대적재량 2.5톤 이상 화물자동차. 10일 이내 수리 여부 통지.","src":"화물자동차 운수사업법 제55조, 시행령 제12조"},{"t":"유상운송 금지: 자가용 화물자동차를 유상으로 화물운송용 제공·임대 금지. 예외로 부령 사유(천재지변 등 수송력 긴급 증가 필요)에 시·도지사의 허가를 받으면 가능. 위반 시 2년 이하 징역 또는 2천만원 이하 벌금.","src":"화물자동차 운수사업법 제56조, 제67조제7호"},{"t":"사용 제한·금지: 시·도지사가 6개월 이내 기간을 정해 제한·금지(자가용으로 운송사업을 경영한 경우 / 허가 없이 유상 운송·임대한 경우). 금지 시 자동차등록증·번호판을 반납한다.","src":"화물자동차 운수사업법 제56조의2"},{"t":"운수종사자 교육: 운전업무 종사자는 시·도지사가 실시하는 교육을 매년 1회 이상 받아야 한다. 관할관청이 시작 1개월 전까지 교육계획 통지. 교육시간 4시간. 8시간: 준수사항 위반으로 벌칙·과태료를 받은 사람 / 운전적성정밀검사 특별검사 대상자 / 물류정책기본법상 단말장치 장착 대상 위험물질 운송차량 운전자. 교육 방법·절차는 관할관청이 정함(한국교통안전공단 이사장 아님).","src":"화물자동차 운수사업법 제59조, 시행규칙 제53조"},{"t":"연수기관은 교육 현황을 매달 20일까지 시·도지사에게 제출하고, 시·도지사는 분기별로 취합해 다음 달 10일까지 국토교통부장관에게 제출.","src":"화물자동차 운수사업법 시행규칙 제53조제5항"},{"t":"교육 미이수 운수종사자: 500만원 이하 과태료(제70조제2항제23호의3). 운송사업자는 교육받는 데 필요한 조치를 하고 미이수자를 종사시키면 안 된다.","src":"화물자동차 운수사업법 제11조, 제70조제2항"}]},{"머리":"벌칙·과태료 요약","줄":[{"t":"2년 이하 징역/2천만원 이하 벌금: 무허가·부정 허가 운송사업·주선사업·가맹사업 경영 / 안전운임 관련 부정한 금품 수수 / 자동차관리사업자와 부정한 금품 수수 / 명의이용 금지 위반 / 허가 제한 사업 양도 / 자가용 유상운송.","src":"화물자동차 운수사업법 제67조"},{"t":"1천만원 이하 과태료: 안전운임보다 적은 운임 지급 등. 500만원 이하 과태료: 변경신고·운임신고·약관신고 불이행 / 종사자격 없는 운전 / 준수사항 위반 / 개선명령 불이행(번호판·대폐차 관련 제외) / 양도양수·합병·상속·휴폐업 신고 불이행 / 등록증·번호판 미반납 / 적재물배상보험등 미가입 / 자가용 사용신고 불이행 / 교육 미이수 등. 부과·징수: 국토교통부장관 또는 시·도지사.","src":"화물자동차 운수사업법 제70조"},{"t":"운수종사자의 일정 장소 장시간 정차 호객: 준수사항 위반(운송사업자의 이를 포함한 위반이 1년 3회 과태료 시 허가 취소·정지 가능).","src":"화물자동차 운수사업법 제12조, 제19조제1항제7호의4"}]}],"함정":[{"x":"화물자동차 운송사업자가 법인인 경우 대표자를 변경하려면 변경허가를 받아야 한다.","o":"대표자 변경(법인)은 경미 사항으로 신고 대상이다.","src":"화물자동차 운수사업법 시행령 제3조제2항제2호 / 기출 2021-17"},{"x":"운송약관을 신고할 때에는 신고서에 적재물배상보험계약서를 첨부하여야 한다.","o":"기출이 틀린 문장으로 처리(약관 신고의 첨부서류는 보험계약서가 아님).","src":"기출 2021-18"},{"x":"운송사업자는 운송약관의 신고를 협회로 하여금 대리하게 할 수 없다.","o":"협회로 하여금 대리하게 할 수 있다.","src":"기출 2021-18, 2025-19"},{"x":"시ㆍ도지사가 화물자동차 운수사업법령에서 정한 기간 내에 신고수리 여부를 신고인에게 통지하지 아니하면 그 기간이 끝난 날에 신고를 수리한 것으로 본다.","o":"그 기간이 끝난 날의 '다음 날' 수리한 것으로 본다(허가관청은 국토교통부장관).","src":"화물자동차 운수사업법 제6조제3항 / 기출 2021-18, 2022-18"},{"x":"공정거래위원회는 표준약관을 작성하여 운송사업자에게 그 사용을 권장할 수 있다.","o":"표준약관은 협회·연합회가 작성해 공정거래위원회 심사를 거친 것이고, 사용 권장은 국토교통부장관이 한다.","src":"화물자동차 운수사업법 제6조제4항 / 기출 2021-18, 2025-19"},{"x":"화물운송계약 중 화물자동차 안전운임에 미치지 못하는 금액을 운임으로 정한 경우 그 부분은 취소하고 새로 계약하여야 한다.","o":"미달 부분은 무효로 하고 안전운임과 동일한 운임을 지급하기로 한 것으로 본다.","src":"화물자동차 운수사업법 제5조의12제3항 / 기출 2021-19, 2022-22"},{"x":"최대적재량 1.5톤을 초과하는 화물자동차를 밤샘주차하는 경우 차고지에서만 하여야 한다.","o":"차고지 외에 공영차고지·화물자동차 휴게소·화물터미널·조례로 정하는 장소도 가능. 1.5톤 이하만 주차장·차고지·조례 장소.","src":"화물자동차 운수사업법 시행규칙 제21조제3·4호 / 기출 2021-21, 2024-25"},{"x":"특수용도형 화물자동차 중「자동차관리법」에 따른 피견인자동차를 소유하고 있는 운송사업자는 적재물배상보험등의 의무가입 대상이다.","o":"피견인자동차는 가입 대상에서 제외된다.","src":"화물자동차 운수사업법 시행규칙 제41조의13제1항제3호 / 기출 2021-25"},{"x":"적재물배상보험등에 가입하려는 자가 운송사업자인 경우 각 사업자별로 가입하여야 한다.","o":"운송사업자는 각 화물자동차별로 가입한다(운송주선사업자가 각 사업자별).","src":"화물자동차 운수사업법 시행령 제9조의7 / 기출 2021-25"},{"x":"중대한 교통사고로 감차 조치 명령을 받은 경우에도 책임보험계약등을 해제하거나 해지하여서는 아니 된다.","o":"허가취소·감차 조치명령을 받은 경우는 해제·해지가 허용된다.","src":"화물자동차 운수사업법 제37조제3호 / 기출 2021-25, 2022-21"},{"x":"적재물배상보험등에 가입하려는 자가 운송주선사업자인 경우 각 화물자동차별로 가입하여야 한다.","o":"운송주선사업자는 각 사업자별로 가입한다.","src":"화물자동차 운수사업법 시행령 제9조의7제2호 / 기출 2021-25, 2022-21"},{"x":"운송사업자는 필요한 경우 다른 사람에게 차량과 그 경영의 전부를 위탁할 수 있다.","o":"경영의 '일부'만 위탁할 수 있고, 위탁 상대는 운송사업자를 제외한 개인.","src":"화물자동차 운수사업법 제40조제1항 / 기출 2021-26, 2023-18, 2025-25"},{"x":"위ㆍ수탁계약의 내용이 계약불이행에 따른 당사자의 손해배상책임을 과도하게 가중하여 정함으로써 상대방의 정당한 이익을 침해한 경우에는 위ㆍ수탁계약 전부를 무효로 한다.","o":"그 부분에 한정하여 무효로 한다.","src":"화물자동차 운수사업법 제40조제7항 / 기출 2021-26"},{"x":"화물운송사업분쟁조정협의회가 위ㆍ수탁계약의 분쟁을 심의한 결과 조정안을 작성하여 분쟁당사자에게 제시하면 분쟁당사자는 이에 따라야 한다.","o":"조정안은 분쟁당사자에게 권고할 수 있을 뿐이다.","src":"화물자동차 운수사업법 시행령 제9조의9제5항 / 기출 2021-26"},{"x":"운송사업자가 위ㆍ수탁계약의 갱신 요구를 거절하는 경우에는 그 요구를 받은 날부터 30일 이내에 위ㆍ수탁차주에게 거절 사유를 적어 서면으로 통지하여야 한다.","o":"15일 이내에 통지한다.","src":"화물자동차 운수사업법 제40조의2제2항 / 기출 2021-26"},{"x":"운송사업자가 사망한 경우 상속인이 그 운송사업을 계속하려면 피상속인이 사망한 후 6개월 이내에 국토교통부장관에게 신고하여야 한다.","o":"90일 이내에 신고한다.","src":"화물자동차 운수사업법 제17조제1항 / 기출 2022-18"},{"x":"국토교통부장관은 신고를 받은 날부터 14일 이내에 신고수리 여부를 신고인에게 통지하여야 한다.","o":"상속 신고는 5일 이내 통지(14일은 운임·요금 신고).","src":"화물자동차 운수사업법 제17조제2항 / 기출 2022-18"},{"x":"상속인이 피상속인의 화물자동차 운송사업을 다른 사람에게 양도하려면 국토교통부장관의 승인을 받아야 한다.","o":"상속인이 사망일부터 3개월 이내 양도하면 그 기간 허가를 상속인에 대한 허가로 본다(승인 규정 없음).","src":"화물자동차 운수사업법 제17조제6항 / 기출 2022-18"},{"x":"운송주선사업자는 주사무소 외의 장소에서 상주하여 영업하려면 국토교통부장관에게 신고하여야 한다.","o":"허가를 받아 영업소를 설치한다.","src":"화물자동차 운수사업법 제24조제8항 / 기출 2022-19, 2025-21"},{"x":"운송주선사업자는 화주로부터 중개를 의뢰받은 화물에 대하여 다른 운송주선사업자에게 수수료를 받고 중개를 의뢰할 수 있다.","o":"수수료·대가를 받고 중개·대리를 의뢰하는 것은 금지된다.","src":"화물자동차 운수사업법 제26조제2항 / 기출 2022-19, 2023-24"},{"x":"운송주선사업자가 운송사업자에게 화물운송을 위탁하는 경우에는 운송가맹사업자의 화물정보망을 이용할 수 없다.","o":"이용할 수 있다.","src":"화물자동차 운수사업법 제34조의4제2항 / 기출 2022-19"},{"x":"부정한 방법으로 화물자동차 운송주선사업의 허가를 받고 화물자동차 운송주선사업을 경영한 자는 과태료 부과 대상이다.","o":"형벌(2년 이하 징역 또는 2천만원 이하 벌금) 대상이다.","src":"화물자동차 운수사업법 제67조제4호 / 기출 2022-19"},{"x":"보험등 의무가입자인 화물자동차 운송주선사업자는 각 화물자동차별로 적재물배상보험등에 가입하여야 한다.","o":"각 사업자별로 가입한다.","src":"화물자동차 운수사업법 시행령 제9조의7 / 기출 2022-21"},{"x":"이사화물운송만을 주선하는 화물자동차 운송주선사업자는 사고 건당 2천만원 이상의 금액을 지급할 책임을 지는 적재물배상보험등에 가입하여야 한다.","o":"이사화물운송만 주선하면 500만원 이상.","src":"화물자동차 운수사업법 시행령 제9조의7 / 기출 2022-21"},{"x":"보험등 의무가입자 및 보험회사등은 화물자동차 운송사업의 허가가 취소된 경우 책임보험계약등을 해제하거나 해지할 수 없다.","o":"허가취소는 해제·해지 허용 사유다.","src":"화물자동차 운수사업법 제37조제3호 / 기출 2022-21"},{"x":"적재물배상보험등에 가입하지 아니한 보험등 의무가입자는 형벌 부과 대상이다.","o":"500만원 이하 과태료 대상이다.","src":"화물자동차 운수사업법 제70조제2항제15호 / 기출 2022-21"},{"x":"운송사업자는 운임과 요금을 정하여 미리 신고하여야 하며, 신고를 받은 국토교통부장관은 30일 이내에 신고수리 여부를 신고인에게 통지하여야 한다.","o":"14일 이내에 통지한다.","src":"화물자동차 운수사업법 제5조제3항 / 기출 2022-22"},{"x":"화물자동차 안전운임위원회 위원의 임기는 2년으로 하되, 연임할 수 있다.","o":"임기는 1년, 연임 가능.","src":"화물자동차 운수사업법 시행령 제4조의10제3항 / 기출 2022-22"},{"x":"화물자동차 안전운임위원회에는 기획재정부, 고용노동부의 3급 또는 4급 공무원으로 구성된 특별위원을 둘 수 있다.","o":"관계 행정기관의 공무원으로 구성된 3명 이내의 특별위원을 둘 수 있다(기출이 틀린 문장으로 처리).","src":"화물자동차 운수사업법 제5조의9제3항 / 기출 2022-22"},{"x":"국토교통부장관은 휴게소 종합계획을 10년 단위로 수립하여야 한다.","o":"5년 단위로 수립한다.","src":"화물자동차 운수사업법 제46조의2제1항 / 기출 2022-23"},{"x":"「한국공항공사법」에 따른 한국공항공사는 화물자동차 휴게소 건설사업을 할 수 있는 공공기관에 해당하지 않는다.","o":"한국공항공사는 해당한다(시행령 제9조의19제1항제8호).","src":"화물자동차 운수사업법 시행령 제9조의19 / 기출 2022-23"},{"x":"휴게소 건설사업 시행자는 그 건설계획을 수립하면 이를 공고하고, 관계 서류의 사본을 10일 이상 일반인이 열람할 수 있도록 하여야 한다.","o":"20일 이상 열람하게 한다.","src":"화물자동차 운수사업법 제46조의3제4항 / 기출 2022-23"},{"x":"「항만법」에 따른 항만이 위치한 지역으로서 화물자동차의 일일 평균 왕복 교통량이 1만5천대인 지역은 화물자동차 휴게소의 건설 대상지역에 해당하지 않는다.","o":"1만5천대 이상이면 건설 대상지역에 해당한다.","src":"화물자동차 운수사업법 시행규칙 제43조의3제1항제1호 / 기출 2022-23"},{"x":"자가용 화물자동차로서 대통령령으로 정하는 화물자동차로 사용하려는 자는 국토교통부령으로 정하는 기준에 따라 시ㆍ도지사의 허가를 받아야 한다.","o":"시·도지사에게 신고한다.","src":"화물자동차 운수사업법 제55조제1항 / 기출 2022-24"},{"x":"화물자동차 운송사업의 폐업 신고 의무는 신고에 대한 수리 여부가 신고인에게 통지된 때에 이행된 것으로 본다(오답 선지).","o":"신고서가 접수기관에 도달된 때 이행된 것으로 본다.","src":"화물자동차 운수사업법 제18조제2항 / 기출 2022-25"},{"x":"허가받은 날부터 3년마다 허가기준에 관한 사항을 신고하여야 한다(운송사업).","o":"5년마다 신고한다.","src":"화물자동차 운수사업법 시행령 제3조제3항 / 기출 2022-20, 2023-26"},{"x":"화물자동차 운송사업의 허가에는 기한을 붙일 수 없다.","o":"조건 또는 기한을 붙일 수 있다.","src":"화물자동차 운수사업법 제3조제14항 / 기출 2022-20, 2025-18"},{"x":"화물자동차 운송사업자가 감차 조치 명령을 받은 후 6개월이 지났다면 증차를 수반하는 허가사항을 변경할 수 있다.","o":"감차 조치명령 후 1년이 지나지 않으면 증차 변경 불가.","src":"화물자동차 운수사업법 제3조제8항 / 기출 2022-20"},{"x":"국토교통부장관은 운송사업자가 사업정지처분을 받은 경우에도 주사무소를 이전하는 변경허가를 할 수 있다.","o":"사업정지처분을 받은 경우 주사무소 이전 변경허가를 하여서는 아니 된다.","src":"화물자동차 운수사업법 제3조제15항 / 기출 2022-20, 2023-26, 2025-18"},{"x":"운송사업자는 관할 관청의 행정구역 내에서 주사무소를 이전하려면 국토교통부장관의 변경허가를 받아야 한다.","o":"관할 관청 행정구역 내 주사무소 이전은 신고 사항이다.","src":"화물자동차 운수사업법 시행령 제3조제2항제5호 / 기출 2023-26"},{"x":"운송주선사업자가 허가사항을 변경하려면 국토교통부장관의 변경허가를 받아야 한다.","o":"변경신고를 한다.","src":"화물자동차 운수사업법 제24조제2항 / 기출 2023-26"},{"x":"운송가맹사업자가 화물취급소를 설치하거나 폐지하려면 국토교통부장관의 변경허가를 받아야 한다.","o":"변경신고 사항이다.","src":"화물자동차 운수사업법 시행령 제9조의2제2호 / 기출 2023-26"},{"x":"국토교통부장관은 운송가맹사업자가 거짓이나 그 밖의 부정한 방법으로 화물자동차 운송가맹사업 허가를 받은 경우 6개월 이내의 기간을 정하여 그 사업의 전부 또는 일부의 정지를 명할 수 있다.","o":"거짓·부정 허가는 허가를 취소하여야 한다.","src":"화물자동차 운수사업법 제32조제1항 / 기출 2024-20"},{"x":"시장ㆍ군수ㆍ구청장은 안전운행의 확보, 운송질서의 확립 및 화주의 편의를 도모하기 위하여 필요하다고 인정하면 운송가맹사업자에게 화물자동차의 구조변경 및 운송시설의 개선을 명할 수 있다.","o":"운송가맹사업자 개선명령은 국토교통부장관이 한다.","src":"화물자동차 운수사업법 제31조 / 기출 2021-24"},{"x":"운송사업자는 필요한 경우 다른 운송사업자에게 차량과 그 경영의 일부를 위탁할 수 있다.","o":"운송사업자를 제외한 개인에게 위탁한다.","src":"화물자동차 운수사업법 제40조제1항 / 기출 2023-18"},{"x":"손해배상 책임에 관하여 「상법」을 준용할 때 화물이 인도기한이 지난 후 1개월 이내에 인도되지 아니하면 그 화물은 멸실된 것으로 본다.","o":"3개월 이내.","src":"화물자동차 운수사업법 제7조제2항 / 기출 2023-25"},{"x":"협회는 국토교통부장관의 허가를 받아 적재물배상 공제사업 등을 할 수 있다.","o":"허가를 받아 공제사업을 하는 주체는 협회의 연합회(또는 인가받은 공제조합).","src":"화물자동차 운수사업법 제51조 / 기출 2023-22"},{"x":"운송주선사업자는 자기 명의로 다른 사람에게 화물자동차 운송주선사업을 경영하게 할 수 있다.","o":"명의이용을 금지한다.","src":"화물자동차 운수사업법 제25조 / 기출 2023-24"},{"x":"국토교통부장관은 운수종사자의 집단적 화물운송 거부로 국가경제에 매우 심각한 위기를 초래할 우려가 있다고 인정할 만한 상당한 이유가 있으면 운송주선사업자에게 업무개시를 명할 수 있다.","o":"업무개시명령 대상은 운송사업자·운수종사자.","src":"화물자동차 운수사업법 제14조 / 기출 2023-24"},{"x":"운송주선사업자는 공영차고지를 임대받아 운영할 수 있다.","o":"공영차고지 임대 대상은 사업자단체·운송사업자·운송가맹사업자·운송사업자 협동조합.","src":"화물자동차 운수사업법 제45조제1항 / 기출 2023-24"},{"x":"국토교통부장관은 화물자동차 운송주선사업의 허가사항 변경신고를 받은 경우 그 신고를 받은 날부터 7일 이내에 신고수리 여부를 신고인에게 통지하여야 한다.","o":"5일 이내 통지한다.","src":"화물자동차 운수사업법 제24조제3항 / 기출 2024-18"},{"x":"연합회가 공제사업을 하는 경우의 운영위원회 위원은 시ㆍ도별 협회의 대표 전원을 포함하여 25명 이내로 한다.","o":"37명 이내로 한다(공제조합은 25명 이내).","src":"화물자동차 운수사업법 제51조의4제2항 / 기출 2024-19"},{"x":"운수종사자 교육을 실시할 때에 교육방법 및 절차 등 교육 실시에 필요한 사항은 한국교통안전공단 이사장이 정한다.","o":"관할관청이 정한다.","src":"화물자동차 운수사업법 시행규칙 제53조제4항 / 기출 2024-23"},{"x":"밤샘주차하는 경우에는 화물자동차 휴게소에 주차할 수 없다.","o":"화물자동차 휴게소는 밤샘주차가 허용되는 장소다.","src":"화물자동차 운수사업법 시행규칙 제21조제3호라목 / 기출 2024-25"},{"x":"화주 1명당 화물의 중량이 10킬로그램 이상일 것(화주 동승 화물 기준).","o":"20킬로그램 이상.","src":"화물자동차 운수사업법 시행규칙 제3조의2 / 기출 2025-17"},{"x":"운송사업자가 화물자동차의 대폐차에 관한 사항을 변경하려면 국토교통부장관의 변경허가를 받아야 한다.","o":"대폐차는 변경신고 사항이다.","src":"화물자동차 운수사업법 시행령 제3조제2항제4호 / 기출 2025-18"},{"x":"개인 운송사업자는 주사무소 외의 장소에서 상주하여 영업하려면 국토교통부장관의 허가를 받아 영업소를 설치하여야 한다.","o":"개인 운송사업자는 영업소 설치 허가 규정의 적용 예외다.","src":"화물자동차 운수사업법 제3조제11항 / 기출 2025-18"},{"x":"화물자동차 운송사업의 증차를 수반하는 변경허가에는 조건 또는 기한을 붙일 수 없다.","o":"증차를 수반하는 변경허가에도 조건 또는 기한을 붙일 수 있다.","src":"화물자동차 운수사업법 제3조제14항 / 기출 2025-18"},{"x":"화물자동차 운송가맹사업의 허가를 받은 자는 화물자동차 운송주선사업의 허가를 받아야 화물자동차 운송주선사업을 경영할 수 있다.","o":"가맹사업 허가를 받은 자는 운송주선사업 허가를 받지 않아도 된다.","src":"화물자동차 운수사업법 제24조제1항 단서 / 기출 2025-21"},{"x":"운송주선사업자는 화주로부터 중개를 의뢰받은 화물에 대하여 운송가맹사업자에게 수수료를 받고 화물의 운송을 주선하는 행위를 할 수 없다.","o":"운송가맹사업자에게 화물 운송을 주선하는 행위는 재계약·중개·대리로 보지 않아 금지되지 않는다.","src":"화물자동차 운수사업법 제26조제6항 / 기출 2025-21"},{"x":"운송사업자는 각 사업자별로 사고 건당 2천만원 이상의 금액을 지급할 책임을 지는 적재물배상보험등에 가입하여야 한다.","o":"운송사업자는 각 화물자동차별로 가입한다.","src":"화물자동차 운수사업법 시행령 제9조의7제1호 / 기출 2025-24"},{"x":"운송사업자는 화물자동차 운송사업의 효율적인 수행을 위하여 필요하면 다른 사람에게 경영의 전부를 위탁할 수 있다.","o":"경영의 일부만 위탁할 수 있다.","src":"화물자동차 운수사업법 제40조제1항 / 기출 2025-25"},{"x":"화물자동차 운송사업의 허가권자는 경영의 위탁을 제한할 수 없다.","o":"허가에 조건을 붙이는 방식으로 위탁을 제한할 수 있다.","src":"화물자동차 운수사업법 제40조제2항 / 기출 2025-25"},{"x":"위ㆍ수탁계약의 기간은 3년 이상으로 하여야 한다.","o":"2년 이상으로 하여야 한다.","src":"화물자동차 운수사업법 제40조제5항 / 기출 2025-25"},{"x":"시장ㆍ군수ㆍ구청장은 위ㆍ수탁계약서의 작성 여부에 대한 실태조사를 매년 2회 이상 실시한다.","o":"국토교통부장관 또는 시·도지사가 정기적으로 실태조사를 할 수 있다(횟수 법정 없음).","src":"화물자동차 운수사업법 제40조의5 / 기출 2025-25"}]},"유통산업발전법":{"묶음":[{"머리":"정의(제2조)","줄":[{"t":"대규모점포: 하나 또는 연접한 둘 이상 건물 안에 설치되는 상시 운영 매장으로 매장면적 합계가 3천제곱미터 이상인 점포 집단(별표 규정). 연접 건물은 건물 간 거리 50미터 이내 + 지하도·지상통로로 하나의 점포로 기능.","src":"유통산업발전법 제2조제3호, 시행령 제3조"},{"t":"준대규모점포: 대규모점포를 경영하는 회사·계열회사 직영 점포 / 상호출자제한기업집단 계열회사 직영 점포 / 이들이 직영점형·프랜차이즈형 체인사업으로 운영하는 점포 중 한국표준산업분류상 슈퍼마켓·기타 음식료품 위주 종합소매업 점포.","src":"유통산업발전법 제2조제4호, 시행령 제3조의2"},{"t":"임시시장: 다수의 수요자와 공급자가 일정한 기간 동안 상품을 매매하거나 용역을 제공하는 일정한 장소.","src":"유통산업발전법 제2조제5호"},{"t":"체인사업 4유형: 직영점형(체인본부가 주로 직영, 일부 가맹점) / 프랜차이즈형(독자적 상품·판매·경영기법의 체인본부가 상호·판매방법·매장운영·광고방법 결정) / 임의가맹점형(경영지도 + 가맹점 취급품목·영업방식 표준화, 공동구매·공동판매·공동시설활용 등 협업) / 조합형(같은 업종 소매점들이 협동조합 등을 설립해 공동사업).","src":"유통산업발전법 제2조제6호"},{"t":"상점가: 일정 범위의 가로 또는 지하도에 도매·소매·용역점포가 밀집한 지구(2천제곱미터 이내에 30개 이상 등). 전문상가단지: 같은 업종을 경영하는 여러 도매업자 또는 소매업자가 일정 지역에 점포·부대시설을 집단으로 설치한 상가단지.","src":"유통산업발전법 제2조제7·8호, 시행령 제5조"},{"t":"무점포판매: 상시 운영 매장을 가진 점포 없이 상품을 판매하는 것으로 산업통상부령(종전 산업통상자원부령)이 정하는 것. 물류설비: 화물의 수송·포장·하역·운반과 이를 관리하는 물류정보처리활동에 사용되는 물품·기계·장치 등의 설비.","src":"유통산업발전법 제2조제9·13호"},{"t":"집배송시설: 상품의 주문처리·재고관리·수송·보관·하역·포장·가공 등 집하·배송 활동과 이를 조정·지원하는 정보처리활동에 쓰는 기계·장치 등 일련의 시설. 공동집배송센터: 여러 유통사업자 또는 제조업자가 공동으로 사용할 수 있도록 집배송시설과 부대업무시설이 설치된 지역 및 시설물.","src":"유통산업발전법 제2조제15·16호"}]},{"머리":"적용 배제(제4조)","줄":[{"t":"이 법을 적용하지 않는 곳: 농수산물도매시장·농수산물공판장·민영농수산물도매시장·농수산물종합유통센터(농수산물 유통 및 가격안정에 관한 법률) / 가축시장(축산법). 4종 모두 해당.","src":"유통산업발전법 제4조"}]},{"머리":"기본계획·시행계획(제5·6조)","줄":[{"t":"유통산업발전기본계획: 산업통상부장관이 5년마다 관계 중앙행정기관의 장과 협의해 수립·시행. 시·도지사에게 알린다.","src":"유통산업발전법 제5조제1·4항"},{"t":"기본계획 포함사항: 발전의 기본방향 / 국내외 여건 변화 전망 / 현황 및 평가 / 지역별·종류별 발전 방안 / 유통기능의 효율화·고도화 방안 / 유통전문인력·부지 및 시설 등의 수급 전망 / 중소유통기업 구조개선·경쟁력 강화 / 대규모점포와 중소유통기업·중소제조업체 사이의 건전한 상거래질서 유지 / 규제완화·제도개선 등.","src":"유통산업발전법 제5조제2항"},{"t":"시행계획: 기본계획에 따라 매년 수립. 기출(2021)에서 지역별 시행계획은 유통전문인력·부지 및 시설 등의 수급방안을 포함하여야 한다는 문장이 맞는 문장으로 출제됨.","src":"유통산업발전법 제6조제1항, 기출 2021-28"}]},{"머리":"유통업상생발전협의회(제7조의5)","줄":[{"t":"설치: 대규모점포 및 준대규모점포와 지역중소유통기업의 균형발전을 협의하기 위해 특별자치시장·시장·군수·구청장 소속으로 둔다.","src":"유통산업발전법 제7조의5"},{"t":"구성: 회장 1명 포함 11명 이내. 회장은 부시장(특별자치시는 행정부시장)·부군수·부구청장. 위원은 대형유통기업 대표 3명 / 중소유통기업 대표 3명 / 소비자·주민단체 대표, 학식 경험자, 이해관계자 / 유통업무 담당 과장급 공무원. 임기 2년.","src":"유통산업발전법 시행규칙 제4조의2"},{"t":"운영: 재적위원 3분의 2 이상 출석으로 개의, 출석위원 3분의 2 이상 찬성으로 의결. 회의 개최일 5일 전까지 날짜·시간·장소·안건 통지(긴급 시 예외). 간사 1명(유통업무 담당 공무원). 분기별로 1회 이상 개최가 원칙(회장이 주기를 달리할 수 있음).","src":"유통산업발전법 시행규칙 제4조의3"},{"t":"협의회 의견 제시 사항: 상생협력 지역 시책 / 상권영향평가서·지역협력계획서 검토 / 영업시간 제한 등 / 전통상업보존구역 지정 / 그 밖의 대·중소유통 협력 사항. 해당 지역 주민단체 대표도 위원이 될 수 있다.","src":"유통산업발전법 시행규칙 제4조의3제5항, 기출 2024-30, 2025-27"}]},{"머리":"대규모점포등 개설등록(제8~11조)","줄":[{"t":"등록: 대규모점포를 개설하거나 전통상업보존구역에 준대규모점포를 개설하려는 자는 영업 시작 전에 상권영향평가서와 지역협력계획서를 첨부해 특별자치시장·시장·군수·구청장에게 등록(시·도지사 아님).","src":"유통산업발전법 제8조제1항"},{"t":"상권영향평가서 포함사항: 요약문 / 사업의 개요 / 상권영향분석의 범위 / 상권의 특성 / 기존 사업자 현황 분석 / 상권영향기술서. 재무구조는 사업계획서 포함사항이다.","src":"유통산업발전법 시행규칙 제5조제1항"},{"t":"변경등록 사항: 법인 명칭·대표자 성명·주소 / 개설등록 당시 매장면적의 10분의 1 이상 변경 / 업태 변경(대규모점포) / 점포 소재지·상호. 소재지 변경, 매장면적 10분의 1 이상 증가, 업태 변경은 상권영향평가서·지역협력계획서 재첨부.","src":"유통산업발전법 시행규칙 제5조제4·5항"},{"t":"개설계획 예고: 대규모점포는 영업 개시 60일 전까지, 준대규모점포는 영업 시작 30일 전까지. 신청받은 지자체는 5일 이내 인터넷 홈페이지에 게재.","src":"유통산업발전법 제8조의3, 시행규칙 제5조의2"},{"t":"인접 지자체 통보: 점포 경계로부터 대규모점포 반경 3킬로미터, 매장 330제곱미터 이상 준대규모 반경 500미터, 330제곱미터 미만 반경 300미터 이내 범위가 인접 지자체에 속하면 통보. 통보받은 날부터 20일 이내 의견 제시.","src":"유통산업발전법 제8조제5·6항, 시행규칙 제5조제8항"},{"t":"허가 등 의제 대상: 비디오물·게임·음반 등 제작·배급업 / 담배 소매인 지정 / 식품 제조·가공·판매·접객업 / 집단급식소 / 테마파크업 / 평생교육시설 / 체육시설업 / 통신판매업 / 공연장 / 옥외광고물 / 외국환업무 / 주류 판매업면허 승계 / 축산물판매업 / 물환경보전법 배출시설 / 사업장폐기물배출자 / 약국 / 안경업소. 대기환경보전법 배출시설은 목록에 없다.","src":"유통산업발전법 제9조, 기출 2024-31"},{"t":"등록 결격사유: 피성년후견인·미성년자 / 파산선고 후 미복권자 / 이 법 위반 징역 실형 집행종료·면제 후 1년 미경과 / 이 법 위반 징역 집행유예 기간 중 / 등록 취소 후 1년 미경과 / 대표자가 위 해당하는 법인.","src":"유통산업발전법 제10조"},{"t":"등록 취소(특별자치시장·시장·군수·구청장, 반드시 취소): 정당한 사유 없이 1년 이내 영업 미개시 / 정당한 사유 없이 1년 이상 계속 휴업 / 결격사유 해당 / 전통상업보존구역 조건 불이행. 법인 대표자 결격·상속인 결격은 6개월 유예.","src":"유통산업발전법 제11조"},{"t":"개설자 지위 승계: 상속인, 양수인, 합병 후 존속·설립 법인. 승계자에게 제10조 결격 준용. 휴업·폐업은 신고(허가 아님).","src":"유통산업발전법 제13조, 제13조의2"},{"t":"전통상업보존구역: 전통시장·전통상점가 경계로부터 1킬로미터 이내 범위에서 지방자치단체 조례로 정하는 지역을 특별자치시장·시장·군수·구청장이 지정. 구역 안 등록은 제한하거나 조건을 붙일 수 있음.","src":"유통산업발전법 제13조의3, 제8조제3항"}]},{"머리":"대규모점포등관리자·영업시간·회계·관리규정(제12~12조의6)","줄":[{"t":"개설자 업무: 상거래질서 확립 / 소비자 안전유지와 소비자 및 인근 지역주민의 피해·불만의 신속한 처리 / 그 밖의 유지·관리 업무.","src":"유통산업발전법 제12조제1항"},{"t":"매장 분양 점포의 업무 수행자(관리자): 매장면적 2분의 1 이상 직영하는 자 → 없으면 입점상인 3분의 2 이상 동의로 설립한 법인·협동조합·사업조합, 또는 자치관리단체(6개월 내 법인 등 자격 구비), 또는 입점상인 2분의 1 이상 동의로 지정한 자(6개월 내 법인 등 설립). 관리자는 특별자치시장·시장·군수·구청장에게 신고(업무 수행일부터 20일 이내).","src":"유통산업발전법 제12조제2·3항, 시행규칙 제6조"},{"t":"영업시간 제한: 특별자치시장·시장·군수·구청장이 대형마트·준대규모점포에 대해 오전 0시부터 오전 10시까지 범위에서 영업시간을 제한하고, 매월 이틀을 의무휴업일로 지정(공휴일 중에서). 농수산물 매출 비중 55퍼센트 이상 등 조례 대상은 제외. 위반 시 1억원 이하 과태료.","src":"유통산업발전법 제12조의2, 제52조"},{"t":"회계감사: 대규모점포등관리자는 감사인의 회계감사를 매년 1회 이상. 입점상인 3분의 2 이상이 서면으로 동의한 연도는 생략 가능. 매 회계연도 종료 후 9개월 이내 재무제표 감사. 감사결과를 받은 날부터 1개월 이내 인터넷 홈페이지에 공개. 장부·증빙서류는 회계연도 종료일부터 5년 보관.","src":"유통산업발전법 제12조의4·5, 시행령 제7조의6"},{"t":"관리규정: 입점상인 3분의 2 이상의 동의를 얻어 제정, 개정도 3분의 2 이상 동의. 관리자 신고일부터 3개월 이내 표준관리규정을 참조해 제정. 표준관리규정은 시·도지사가 마련해 보급. 입점상인의 열람·복사 요구에 응하여야 한다.","src":"유통산업발전법 제12조의6, 시행령 제7조의7"}]},{"머리":"체인사업·중소유통공동도매물류센터·상점가진흥조합·전문상가단지(제16~20조)","줄":[{"t":"체인사업자의 경영개선사항: 시설 현대화 / 원재료·상품·용역 원활한 공급 / 점포관리·품질관리·판매촉진 지도 / 종사자 교육·훈련 / 유통정보시스템 구축 / 집배송시설 설치·공동물류 / 공동브랜드·자기부착상표 개발 / 유통관리사 고용 촉진 / 그 밖의 사항. 지원: 산업통상부장관·중소벤처기업부장관·지방자치단체의 장.","src":"유통산업발전법 제16조"},{"t":"중소유통공동도매물류센터 지원: 중소기업자 중 소매업자 50인 또는 도매업자 10인 이상의 중소유통기업자단체가 건립·운영하면 산업통상부장관·중소벤처기업부장관·지방자치단체의 장이 행정적·재정적 지원. 지방자치단체의 장이 건립해 중소유통기업자단체 등에 운영 위탁 가능(산업통상부장관 위탁 아님). 이용료는 매출액의 1천분의 5 이내. 건립·운영 사항은 중소벤처기업부장관이 고시.","src":"유통산업발전법 제17조의2"},{"t":"상점가진흥조합: 상점가에서 도매·소매·용역업 등을 하는 자가 결성. 조합원은 그중 중소기업자. 조합원 자격자의 3분의 2 이상 동의로 결성(같은 업종이 2분의 1 이상이면 그 같은 업종 영위자의 5분의 3 이상 동의로 가능). 협동조합 또는 사업조합으로 설립. 구역은 다른 상점가진흥조합 구역과 중복 불가.","src":"유통산업발전법 제18조"},{"t":"상점가진흥조합 지원(지방자치단체의 장): 점포시설 표준화·현대화 / 공동시설 설치 / 주차장·휴게소 등 공공시설 설치 / 판매촉진 공동사업 / 가격표시 등 상거래질서 확립 / 연수·정보제공 / 그 밖에 상점가 진흥사업.","src":"유통산업발전법 제19조"},{"t":"전문상가단지 건립 지원 요건(시행규칙): 5천제곱미터 이상 부지 확보, 입주 조합원 50인 이상 등.","src":"유통산업발전법 시행규칙 제8조"}]},{"머리":"유통정보화·유통관리사·유통연수기관(제21~24조)","줄":[{"t":"유통표준전자문서 위작·변작: 10년 이하 징역 또는 1억원 이하 벌금(미수범 처벌). 유통정보 공개: 1천만원 이하 벌금. 유통표준전자문서 보관기간 3년, 미보관 시 1년 이하 징역 또는 1천만원 이하 벌금.","src":"유통산업발전법 제22조·제49조·제50조, 시행령 제9조"},{"t":"유통관리사: 산업통상부장관 실시 자격시험 합격. 직무는 유통경영·관리 기법 향상, 계획·조사·연구, 진단·평가, 상담·자문 등. 고용 사업자 우선 자금 지원. 거짓·부정 취득은 자격 취소(취소하여야 하며, 취소일부터 3년간 응시 불가). 명의 사용·자격증 대여 시 6개월 이내 자격정지.","src":"유통산업발전법 제24조"},{"t":"지정유통연수기관 지정기준: 시설 - 강의실 100제곱미터 이상 / 사무실 16제곱미터 이상 / 휴게실 10제곱미터 이상 (산업통상부장관이 완화 가능). 강사 - 전임강사 1명 이상, 시간강사 3명 이상. 연수실적 - 지정신청일 기준 1년 이내에 2회(1회당 20시간 이상) 이상 유통연수강좌 실시.","src":"유통산업발전법 시행령 별표 2의2"}]},{"머리":"공동집배송센터·촉진지구(제29~35조)","줄":[{"t":"지정 주체: 산업통상부장관이 물류공동화 촉진을 위해 시·도지사의 추천을 받아 지정(시·도지사가 지정하는 것이 아님). 지정·변경지정 전 관계 중앙행정기관의 장과 협의. 지정 시 고시.","src":"유통산업발전법 제29조"},{"t":"지정 요건: 부지면적 3만제곱미터 이상(상업지역 또는 공업지역은 2만제곱미터 이상) + 집배송시설면적 1만제곱미터 이상 + 도시 내 유통시설로의 접근성이 우수한 지역·시설물.","src":"유통산업발전법 시행규칙 제19조"},{"t":"절차: 지정받으려는 자가 사업계획 첨부해 시·도지사에게 추천 신청(부지매입 관련 서류 포함) → 시·도지사가 타당성 검토 후 추천 사유서 제출. 지정 중요사항 변경은 산업통상부장관의 변경지정(시·도지사 아님). 변경지정을 받지 않으면 500만원 이하 과태료.","src":"유통산업발전법 제29조제2~4항, 제52조제3항"},{"t":"신탁개발: 공동집배송센터사업자가 신탁업자와 신탁계약을 체결해 신탁개발 가능. 신탁업자는 사업자의 지위를 승계하고, 계약체결일부터 14일 이내 신탁계약서 사본을 산업통상부장관에게 제출.","src":"유통산업발전법 제32조"},{"t":"시정명령 및 지정취소: 요건·시설·운영 기준 미달 시 시정명령. 거짓·부정 지정은 취소하여야 한다. 취소할 수 있는 사유 - 지정받은 날부터 정당한 사유 없이 3년 이내 시공하지 않음 / 시정명령 불이행 / 정상 추진 곤란(파산 / 법인·조합 해산 / 시공 후 정당한 사유 없이 공사가 6개월 이상 중단 / 지정일부터 5년 이내 미준공).","src":"유통산업발전법 제33조, 시행령 제15조"},{"t":"개발촉진지구: 시·도지사가 지정을 산업통상부장관에게 요청(관계 중앙행정기관의 장이 요청하는 것이 아님). 산업통상부장관이 요건에 적합하면 관계 중앙행정기관 협의 후 지정·고시. 요건: 부지 10만제곱미터 이상 + 외국인투자지역·자유무역지역·경제자유구역·물류단지·산업단지·공항 및 배후지·항만 및 배후지 중 하나 + 집배송시설 또는 공동집배송센터 2 이상.","src":"유통산업발전법 제34조, 시행규칙 제24조"},{"t":"촉진지구 지원: 산업통상부장관 또는 시·도지사가 자금 등 지원. 촉진지구의 집배송시설은 산업통상부장관이 시·도지사의 추천이 없어도 공동집배송센터로 지정할 수 있다.","src":"유통산업발전법 제35조"},{"t":"공동집배송센터 인·허가 의제 협의: 관계 행정기관은 협의 요청을 받은 날부터 30일 이내 의견 제출.","src":"유통산업발전법 제30조제2항"}]},{"머리":"유통분쟁조정(제36~41조)","줄":[{"t":"위원회: 시·도 및 시·군·구에 각각 둘 수 있다. 위원장 포함 11명 이상 15명 이하. 위원장은 호선. 공무원이 아닌 위원 임기 2년.","src":"유통산업발전법 제36조제1~5항"},{"t":"조정 대상: 대규모점포등과 인근 지역 도매업자·소매업자 간 영업활동 분쟁 / 대규모점포등과 중소제조업체 간 영업활동 분쟁 / 대규모점포등과 인근 지역 주민 간 생활환경 분쟁 / 개설자 업무(상거래질서 확립, 소비자 안전유지, 주민 피해·불만 처리) 수행 관련 분쟁. 각각 독점규제 및 공정거래법을 적용받는 사항은 제외.","src":"유통산업발전법 제36조제1항"},{"t":"절차: 특별자치시·시·군·구 위원회에 신청 → 신청일부터 60일 이내 심사해 조정안 작성(부득이하면 의결로 연장). 신청일부터 3일 이내 신청인 외 관련 당사자에게 통보. 시·군·구 위원회 조정안에 불복하면 제시받은 날부터 15일 이내 시·도 위원회에 조정 신청, 시·도 위원회는 30일 이내 조정안 작성.","src":"유통산업발전법 제37조, 시행령 제16조"},{"t":"조정안 제시 후 당사자는 제시받은 날부터 15일 이내 수락 여부를 통보. 수락하고 조정서에 기명날인·서명하면 조정서와 동일한 합의 성립. 조정이 적합하지 않거나 부정한 목적이면 조정 거부 가능. 한쪽이 소를 제기하면 조정 처리 중지. 동일한 시기·동일한 사안의 다수 신청은 통합 조정 가능.","src":"유통산업발전법 제39조·제40조, 시행령 제16조의3"}]},{"머리":"벌칙·과태료","줄":[{"t":"1년 이하 징역 또는 3천만원 이하 벌금: 등록 없이 대규모점포등 개설 / 거짓·부정으로 개설등록 / 신고 없이 개설자 업무 수행 / 거짓·부정 업무수행신고.","src":"유통산업발전법 제49조제2항"},{"t":"1억원 이하 과태료: 영업제한시간 영업·의무휴업 명령 위반. 1천만원 이하: 회계감사를 받지 않거나 부정한 방법으로 받은 경우 / 회계감사 방해. 500만원 이하: 변경등록 불이행 / 개설자 업무 미수행 / 관리비 등 공개 위반 / 장부 미작성·미보관 / 열람 불응 / 임시시장 무단 개설 / 변경지정 미이행 / 시정명령 불이행 등.","src":"유통산업발전법 제52조"},{"t":"형사벌 대상이 아닌 것: 부정한 방법으로 회계감사를 받은 대규모점포등관리자(과태료 대상).","src":"유통산업발전법 제52조제2항, 기출 2022-28"}]}],"함정":[{"x":"산업통상자원부장관은 10년마다 유통산업발전기본계획을 수립하여야 한다.","o":"5년마다 수립한다.","src":"유통산업발전법 제5조제1항 / 기출 2021-28"},{"x":"유통산업발전기본계획에는 유통산업의 지역별·종류별 발전방안이 포함되지 않아도 된다.","o":"지역별·종류별 발전 방안이 포함되어야 한다.","src":"유통산업발전법 제5조제2항제4호 / 기출 2021-28"},{"x":"시·도지사는 유통산업발전기본계획에 따라 2년마다 유통산업발전시행계획을 수립하여야 한다.","o":"시행계획은 기본계획에 따라 매년 수립한다(현행 조문은 산업통상부장관이 수립).","src":"유통산업발전법 제6조제1항 / 기출 2021-28"},{"x":"시·도지사는 유통산업발전시행계획의 집행실적을 다음 연도 1월 말일까지 산업통상자원부장관에게 제출하여야 한다.","o":"기출이 틀린 문장으로 처리(현행 조문에는 집행실적 제출 규정이 확인되지 않음).","src":"기출 2021-28"},{"x":"관리규정을 제정하기 위해서는 입점상인의 4분의 3 이상의 동의를 얻어야 한다.","o":"3분의 2 이상의 동의를 얻는다.","src":"유통산업발전법 제12조의6제1항 / 기출 2021-29"},{"x":"대규모점포등관리자는 대규모점포등관리자신고를 한 날부터 1개월 이내에 관리규정을 제정하여야 한다.","o":"신고를 한 날부터 3개월 이내.","src":"유통산업발전법 시행령 제7조의7제1항 / 기출 2021-29"},{"x":"상점가진흥조합의 구역은 다른 상점가진흥조합의 구역과 중복될 수 있다.","o":"중복되어서는 아니 된다.","src":"유통산업발전법 제18조제5항 / 기출 2021-30, 2023-33, 2025-31"},{"x":"중소유통공동도매물류센터의 건립, 운영 및 관리 등에 관하여 필요한 사항은 산업통상자원부장관이 정하여 고시한다.","o":"중소벤처기업부장관이 정하여 고시한다.","src":"유통산업발전법 제17조의2제4항 / 기출 2021-30"},{"x":"상업지역 내에서 부지면적이 1만제곱미터이고, 집배송시설면적이 5천제곱미터인 지역 및 시설물은 공동집배송센터로 지정할 수 있다.","o":"상업·공업지역은 부지 2만제곱미터 이상 + 집배송시설 1만제곱미터 이상이어야 한다.","src":"유통산업발전법 시행규칙 제19조 / 기출 2021-31"},{"x":"공동집배송센터를 신탁개발하는 경우 신탁계약을 체결한 신탁업자는 공동집배송센터사업자의 지위를 승계하지 않는다.","o":"신탁업자가 사업자의 지위를 승계한다.","src":"유통산업발전법 제32조제2항 / 기출 2021-31"},{"x":"관계 중앙행정기관의 장은 집배송시설의 효율적 배치를 위하여 공동집배송센터 개발촉진지구의 지정을 산업통상자원부장관에게 요청할 수 있다.","o":"지정을 요청하는 주체는 시·도지사다.","src":"유통산업발전법 제34조제1항 / 기출 2021-31"},{"x":"공동집배송센터 개발촉진지구의 집배송시설에 대하여는 시·도지사가 공동집배송센터로 지정할 수 있다.","o":"산업통상부장관이 시·도지사의 추천 없이도 공동집배송센터로 지정할 수 있다.","src":"유통산업발전법 제35조제2항 / 기출 2021-31"},{"x":"시·도지사는 물류공동화를 촉진하기 위하여 필요한 경우에는 시장·군수·구청장의 추천을 받아 산업통상자원부령으로 정하는 요건에 해당하는 지역 및 시설물을 공동집배송센터로 지정할 수 있다.","o":"산업통상부장관이 시·도지사의 추천을 받아 지정한다.","src":"유통산업발전법 제29조제1항 / 기출 2022-27"},{"x":"공동집배송센터사업자는 지정받은 사항 중 산업통상자원부령으로 정하는 중요 사항을 변경하려면 시·도지사의 변경지정을 받아야 한다.","o":"산업통상부장관의 변경지정을 받는다.","src":"유통산업발전법 제29조제4항 / 기출 2022-27"},{"x":"공동집배송센터의 지정을 받은 날부터 정당한 사유 없이 2년 이내에 시공을 하지 아니하는 경우에는 공동집배송센터의 지정이 취소될 수 있다.","o":"3년 이내.","src":"유통산업발전법 제33조제2항제2호 / 기출 2022-27"},{"x":"거짓으로 공동집배송센터의 지정을 받은 경우는 공동집배송센터의 지정을 취소할 수 있는 사유에 해당한다.","o":"거짓·부정 지정은 취소하여야 하는 사유다.","src":"유통산업발전법 제33조제2항제1호 / 기출 2022-27"},{"x":"산업통상자원부장관은 「중소기업기본법」 제2조에 따른 중소기업자 중 대통령령으로 정하는 소매업자 30인이 공동으로 중소유통공동도매물류센터를 건립하는 경우 필요한 행정적·재정적 지원을 할 수 있다.","o":"소매업자 50인 또는 도매업자 10인 이상.","src":"유통산업발전법 제17조의2제1항 / 기출 2022-30"},{"x":"산업통상자원부장관은 중소유통공동도매물류센터를 건립하여 중소유통기업자단체에 그 운영을 위탁할 수 있다.","o":"건립 후 운영 위탁은 지방자치단체의 장이 한다.","src":"유통산업발전법 제17조의2제2항 / 기출 2022-30, 2023-33"},{"x":"상점가진흥조합은 조합원의 자격이 있는 자의 과반수의 동의를 받아 결성한다.","o":"3분의 2 이상의 동의(같은 업종 2분의 1 이상이면 그 업종의 5분의 3 이상).","src":"유통산업발전법 제18조제3항 / 기출 2022-30"},{"x":"상점가진흥조합의 조합원은 상점가에서 도매업·소매업·용역업이나 그 밖의 영업을 하는 모든 자로 한다.","o":"그중 중소기업자에 해당하는 자.","src":"유통산업발전법 제18조제2항 / 기출 2022-30, 2025-31"},{"x":"「중소기업기본법」에 따른 중소기업자는 조합원이 될 수 없다.","o":"중소기업자가 조합원이 된다.","src":"유통산업발전법 제18조제2항 / 기출 2025-31"},{"x":"상점가진흥조합은 협동조합으로 설립하여야 하고 사업조합의 형식으로는 설립할 수 없다.","o":"협동조합 또는 사업조합으로 설립한다.","src":"유통산업발전법 제18조제4항 / 기출 2023-33, 2025-31"},{"x":"“상점가”란 같은 업종을 경영하는 여러 도매업자 또는 소매업자가 일정 지역에 점포 및 부대시설 등을 집단으로 설치하여 만든 상가단지를 말한다.","o":"이것은 전문상가단지의 정의. 상점가는 가로·지하도에 점포가 밀집한 지구.","src":"유통산업발전법 제2조제7·8호 / 기출 2023-30"},{"x":"대규모점포를 개설하려는 자는 영업을 개시하기 30일 전까지 개설 지역 및 시기 등을 포함한 개설계획을 예고하여야 한다.","o":"대규모점포는 60일 전, 준대규모점포는 30일 전.","src":"유통산업발전법 제8조의3 / 기출 2023-32"},{"x":"유통산업발전법을 위반하여 징역의 실형을 선고받고 그 집행이 면제된 날부터 6월이 지난 사람은 대규모점포등의 등록을 할 수 있다.","o":"1년이 지나야 등록할 수 있다.","src":"유통산업발전법 제10조제3호 / 기출 2023-32"},{"x":"대형마트의 영업시간을 제한하는 경우 조례로 달리 정하지 않는 한 오전 0시부터 오전 11시까지의 범위에서 영업시간을 제한할 수 있다.","o":"오전 0시부터 오전 10시까지.","src":"유통산업발전법 제12조의2제2항 / 기출 2023-32"},{"x":"대규모점포등개설자가 대규모점포등을 폐업하려는 경우에는 특별자치시장·시장·군수·구청장의 허가를 받아야 한다.","o":"신고하여야 한다.","src":"유통산업발전법 제13조의2 / 기출 2023-32"},{"x":"지방자치단체의 장은 자신이 건립한 중소유통공동도매물류센터의 운영을 중소유통기업자단체에 위탁할 수 없다.","o":"위탁할 수 있다.","src":"유통산업발전법 제17조의2제2항 / 기출 2023-33"},{"x":"지방자치단체의 장은 상점가진흥조합이 조합원의 판매촉진을 위한 공동사업을 하는 경우에는 필요한 자금을 지원할 수 없다.","o":"지원할 수 있다.","src":"유통산업발전법 제19조제4호 / 기출 2023-33"},{"x":"상점가진흥조합의 구역은 다른 상점가진흥조합 구역의 5분의 1 이하의 범위에서 그 다른 상점가진흥조합의 구역과 중복되어 지정할 수 있다.","o":"중복 불가.","src":"유통산업발전법 제18조제5항 / 기출 2023-33"},{"x":"공업지역 내에서 부지면적이 2만제곱미터이고, 집배송시설면적이 1만제곱미터인 지역 및 시설물은 공동집배송센터로 지정할 수 없다.","o":"공업지역 요건(2만제곱미터 이상 + 1만제곱미터 이상)을 충족하므로 지정할 수 있다.","src":"유통산업발전법 시행규칙 제19조 / 기출 2023-34"},{"x":"협의회의 회의는 재적위원 과반수의 출석으로 개의하고, 출석위원 3분의 2 이상의 찬성으로 의결한다.","o":"재적위원 3분의 2 이상 출석 + 출석위원 3분의 2 이상 찬성.","src":"유통산업발전법 시행규칙 제4조의3제1항 / 기출 2024-30"},{"x":"위원회는 유통분쟁조정신청을 받은 경우 신청일부터 10일 이내에 신청인외의 관련 당사자에게 분쟁의 조정신청에 관한 사실과 그 내용을 통보하여야 한다.","o":"3일 이내 통보.","src":"유통산업발전법 시행령 제16조제1항 / 기출 2024-33"},{"x":"협의회 위원의 임기는 1년으로 한다.","o":"2년.","src":"유통산업발전법 시행규칙 제4조의2제3항 / 기출 2025-27"},{"x":"성별 및 분야별 대표성 등을 고려하여 회장 1명을 포함한 10명 이내의 위원으로 구성한다.","o":"11명 이내.","src":"유통산업발전법 시행규칙 제4조의2제1항 / 기출 2025-27"},{"x":"협의회의 회장은 해당 지역의 시장·군수·구청장이 된다.","o":"부시장(특별자치시는 행정부시장)·부군수·부구청장.","src":"유통산업발전법 시행규칙 제4조의2제2항 / 기출 2025-27"},{"x":"협의회는 매월 1회 이상 개최하는 것을 원칙으로 하되, 회장은 필요에 따라 그 개최 주기를 달리할 수 있다.","o":"분기별 1회 이상이 원칙.","src":"유통산업발전법 시행규칙 제4조의3제4항 / 기출 2025-27"},{"x":"상점가진흥조합의 주차장·휴게소 등 공공시설 설치사업은 지방자치단체의 장이 필요한 자금을 지원할 수 있는 사업에 해당하지 않는다.","o":"지원 가능 사업에 해당한다.","src":"유통산업발전법 제19조제3호 / 기출 2025-31, 2022-30"},{"x":"전통상업보존구역에 대규모점포를 개설하려는 자는 상권영향평가서 및 지역협력계획서를 첨부하여 시·도지사에게 등록하여야 한다(기출 2022-29 ㄱ).","o":"특별자치시장·시장·군수·구청장에게 등록한다.","src":"유통산업발전법 제8조제1항 / 기출 2022-29"},{"x":"대규모점포의 매장면적이 개설등록 당시의 매장면적보다 20분의 1이 증가한 경우 변경등록을 하여야 한다(기출 2022-29 ㄴ).","o":"10분의 1 이상 변경이어야 변경등록 대상.","src":"유통산업발전법 시행규칙 제5조제4항 / 기출 2022-29"}]},"항만운송사업법":{"묶음":[{"머리":"항만운송의 정의(제2조제1항)","줄":[{"t":"항만운송: 타인의 수요에 응하여 하는 행위로서 제2조제1항 각 호(16개)의 어느 하나. 타인의 수요에 응하지 않는 자가용 행위는 아니다.","src":"항만운송사업법 제2조제1항"},{"t":"화물 인수·인도: 선박으로 운송된 화물을 화물주·선박운항업자 위탁받아 선박으로부터 인수하거나 화물주에게 인도 / 선박으로 운송될 화물을 화물주로부터 인수하거나 선박에 인도.","src":"항만운송사업법 제2조제1항제1·2호"},{"t":"하역·운송: 화물을 선박에 싣거나 내리는 일 / 항만에서 선박·부선으로 화물을 운송하는 행위(해운법상 해상화물운송사업자 운송, 여객선 여객운송에 수반되는 화물 운송은 제외) / 선박·부선으로 운송된 화물을 창고·하역장[수면 목재저장소 제외]에 들여놓는 행위 / 운송될 화물을 하역장에서 내가는 행위 / 하역장에서 싣거나 내리거나 보관하는 행위 / 부선에 싣거나 내리는 행위.","src":"항만운송사업법 제2조제1항제4~9호"},{"t":"목재: 항만·지정구간에서 목재를 뗏목으로 편성하여 운송하는 행위 / 뗏목·선박·부선으로 운송된 목재를 수면 목재저장소에 들여놓는 행위 / 저장소에서 내가는 행위 / 저장소에서 싣거나 내리거나 보관하는 행위.","src":"항만운송사업법 제2조제1항제10~13호"},{"t":"검수: 선적화물을 싣거나 내릴 때 화물의 개수를 계산하거나 인도·인수를 증명하는 일. 감정: 선적화물 및 선박(부선 포함)에 관련된 증명·조사·감정. 검량: 화물의 용적 또는 중량을 계산하거나 증명하는 일.","src":"항만운송사업법 제2조제1항제14~16호"},{"t":"항만운송에서 제외되는 운송(시행규칙): 선박에서 사용하는 물품을 공급하기 위한 운송 / 선박에서 발생하는 분뇨·폐기물의 운송 / 탱커선·어획물운반선에 의한 운송. 해운법상 해상화물운송사업자의 운송도 제외.","src":"항만운송사업법 제2조제1항제5호, 시행규칙 제2조"},{"t":"항만운송관련사업: 항만에서 선박에 물품이나 역무를 제공하는 항만용역업·선용품공급업·선박연료공급업·선박수리업·컨테이너수리업. 선적화물 검수업은 항만운송사업(검수사업)이지 관련사업이 아니다.","src":"항만운송사업법 제2조제4항, 기출 2025-32"},{"t":"항만용역업 내용: 통선으로 본선과 육지 사이에서 사람이나 문서 등 운송 / 본선 경비, 이안·접안 줄잡이 역무 / 선박 청소(유창 청소 제외)·오물 제거·소독·폐기물 수집·운반·화물 고정·칠 / 선박용 맑은 물 공급. 선용품(음료·식품·소모품·밧줄·예비부분품·집기 등) 공급은 선용품공급업이지 항만용역업이 아니다.","src":"항만운송사업법 시행령 제2조, 기출 2021-32, 2023-27"},{"t":"관리청: 국가관리무역항·국가관리연안항은 해양수산부장관, 지방관리무역항·지방관리연안항은 시·도지사.","src":"항만운송사업법 제2조제7항"},{"t":"부두운영회사: 항만하역사업 및 그 부대사업을 수행하기 위해 관리청등과 부두운영계약을 체결하고 항만시설 및 장비·부대시설 등을 일괄 임차 사용하는 자. 제외: 항만공사와 임대차계약을 맺고 해양수산부장관이 컨테이너 부두로 고시한 항만시설을 임차한 자 / 특정 화물 전용으로 고시된 항만시설 임차자.","src":"항만운송사업법 제2조제6항"}]},{"머리":"항만운송사업의 종류·등록(제3~6조)","줄":[{"t":"사업의 종류 4가지: 항만하역사업 / 검수사업 / 감정사업 / 검량사업.","src":"항만운송사업법 제3조"},{"t":"등록: 사업의 종류별로 관리청에 등록. 항만하역사업과 검수사업은 항만별로 등록(감정·검량은 항만별 등록 아님). 항만하역사업은 이용자별·취급화물별·항만시설별 한정하역사업과 그 외 일반하역사업으로 구분.","src":"항만운송사업법 제4조"},{"t":"등록신청: 사업계획을 첨부한 등록신청서를 관리청에 제출. 신청인이 법인이면 정관, 개인이면 재산 상태를 적은 서류 첨부. 요건을 모두 갖추면 등록증 발급.","src":"항만운송사업법 제5조, 시행규칙 제4조"},{"t":"항만하역사업 사업계획 포함: 사업 개요 / 사업소 수·명칭·위치 / 개시 예정일 / 종사자 수 / 하역장비 대수·선박·부선·예인선·통선 / 상옥·창고 / 하역장 / 수면 목재저장소의 수·위치·면적 / 종사자 대기소 / 사업 내용 / 연간 취급화물량 추정치.","src":"항만운송사업법 시행규칙 제5조"},{"t":"등록기준: 시설·자본금·노동력 등은 대통령령. 한정하역사업은 이용자·취급화물·항만시설 특성을 고려해 관리청이 등록기준을 완화할 수 있다.","src":"항만운송사업법 제6조"}]},{"머리":"검수사등 자격(제7~9조)","줄":[{"t":"검수사·감정사·검량사: 해양수산부장관 시행 자격시험 합격 후 해양수산부장관에게 등록. 시험 시행일 기준 결격사유 해당자는 응시 불가.","src":"항만운송사업법 제7조"},{"t":"결격: 미성년자 / 피성년후견인·피한정후견인 / 이 법 또는 관세법 위반 금고 이상 실형 집행종료·면제 후 3년 미경과 / 같은 죄 금고 이상 집행유예 기간 중 / 검수사등 자격 취소 후 2년 미경과.","src":"항만운송사업법 제8조"},{"t":"자격증 양도·대여·양수·알선 금지. 자격 취소(해양수산부장관, 반드시): 거짓·부정 취득 / 성명 사용 업무 허용·자격증 양도·대여. 취소 시 공고. 등록 말소: 업무를 폐지하거나 사망한 경우.","src":"항만운송사업법 제8조의2, 제8조의3, 제9조"}]},{"머리":"운임·요금(제10조)","줄":[{"t":"항만하역사업: 운임과 요금을 정하여 관리청의 인가(변경도 인가). 다만 해양수산부령이 정한 항만시설(특정 화주 전용, 비관리청 설치)에서 하역하는 화물 또는 컨테이너 전용 부두에서 취급하는 컨테이너 화물은 신고(인가 아님).","src":"항만운송사업법 제10조제1·2항, 시행규칙 제15조의2"},{"t":"검수·감정·검량사업: 요금을 정하여 관리청에 미리 신고(변경도 신고).","src":"항만운송사업법 제10조제3항"},{"t":"신고수리 통지 기한: 제2항(하역 운임 신고) 30일 이내 / 제3항(검수사업등 요금) 14일 이내. 기한 내 미통지 시 끝난 날의 다음 날 수리 간주. 관리청은 신고된 운임·요금에 대해 변경·조정 조치를 명할 수 있다.","src":"항만운송사업법 제10조제4·5·7항"},{"t":"검수사업등 요금 신고서 기재사항: 상호 / 성명 및 주소 / 사업의 종류 / 취급화물의 종류 / 항만명(검수사업만 해당) / 변경 전후 요금 비교·사유·예정일(변경 시) / 요금 적용방법. 감정사업은 항만명이 해당되지 않는다.","src":"항만운송사업법 시행규칙 제15조제3항, 기출 2021-34"}]},{"머리":"승계·취소·과징금(제23·26·27조의6)","줄":[{"t":"승계: 상속인 / 양수인 / 합병 후 존속·설립 법인. 시설·장비 전부 인수 절차(민사집행법 경매, 채무자회생법상 환가, 압류재산 매각 등)로 인수한 자도 종전 사업자의 권리·의무를 승계.","src":"항만운송사업법 제23조"},{"t":"사업정지·등록취소(관리청): 6개월 이내 정지 또는 취소. 반드시 취소 - 부정한 방법의 등록 / 사업정지명령 위반 정지기간 중 사업 계속. 임의 - 정당한 사유 없이 인가·신고 운임·요금과 다르게 받음 / 등록기준 미달 / 관세법 제269~271조 죄로 공소 제기 또는 통고처분 / 사업 수행 실적 1년 이상 없음.","src":"항만운송사업법 제26조"},{"t":"과징금: 사업정지처분을 하여야 하는 경우로서 이용자에게 심한 불편 또는 공익 침해 우려가 있을 때 정지에 갈음해 500만원 이하.","src":"항만운송사업법 제27조의6"}]},{"머리":"항만종합서비스업·항만운송관련사업(제26조의2~5)","줄":[{"t":"항만종합서비스업: 항만용역업(줄잡이 역무와 화물 고정 행위 포함)과 검수·감정·검량사업 중 1개 이상을 포함하는 사업. 대통령령 기준을 갖추어 관리청에 등록. 등록하면 각 사업을 등록한 것으로 본다.","src":"항만운송사업법 제2조제8항, 제26조의2"},{"t":"항만운송관련사업: 항만별·업종별로 관리청에 등록. 선용품공급업은 해양수산부장관에게 신고(등록 아님). 선박수리업·선용품공급업 영업구역은 항만시설. 신고수리 통지: 선용품공급업 신고는 6일 이내, 선박연료공급업 사업계획 변경신고는 5일 이내.","src":"항만운송사업법 제26조의3"},{"t":"선박연료공급업: 등록 후 사용 장비를 추가하거나 사업계획 중 부령 사항을 변경하려면 관리청에 사업계획 변경신고를 하여야 한다. 신고 없이 장비를 추가하면 등록취소·정지 사유 + 500만원 이하 벌금.","src":"항만운송사업법 제26조의3제3항, 제26조의5, 제31조"},{"t":"관련사업자 등록취소·정지: 6개월 이내 정지 또는 취소. 반드시 취소 - 부정한 등록·신고 / 사업정지명령 위반. 임의 - 변경신고 없이 장비 추가 / 기준 미달 / 실적 1년 이상 없음 / 관세법 죄 공소 제기.","src":"항만운송사업법 제26조의5"},{"t":"미등록 항만 일시 영업: 부득이한 사유가 있으면 관리청에 미리 신고. 3일 이내 수리 여부 통지, 미통지 시 다음 날 수리 간주. 신고 없이 영업하면 500만원 이하 벌금.","src":"항만운송사업법 제27조의2, 제31조"}]},{"머리":"부두운영회사(제26조의6~10)","줄":[{"t":"부두운영계약 체결: 관리청등(관리청 또는 항만공사)이 항만 운영 효율성·생산성 향상을 위해 필요한 경우 부령 기준에 적합한 자를 선정해 체결할 수 있다. 선정 기준: 임대료 등 지급 능력 / 화물 유치 능력과 투자 능력 / 재무구조 건전성.","src":"항만운송사업법 제26조의6제1항, 시행규칙 제27조"},{"t":"계약 포함사항: 임차·사용 항만시설등의 범위 / 화물유치·투자 계획과 미이행 시 위약금 / 임대료 / 계약기간 / 항만시설등 안전관리 / 분할 운영 금지 등 금지행위 위반 시 책임 / 해양수산부장관과 협의한 사항. 금지행위 위반 시 책임에 관한 사항은 포함되어야 한다.","src":"항만운송사업법 제26조의6제2항, 시행규칙 제29조"},{"t":"갱신: 계약기간 만료 6개월 전까지 항만시설운영자등에게 갱신 신청. 운영자등은 선정기준 적합성, 임대료 연체, 화물유치·투자 이행, 금지행위 위반 등을 검토하고, 갱신하려면 갱신 계약기간 시작 7일 전까지 갱신계약 체결. 공고 없이 계약 체결 가능한 경우(효율적 사용·운영 필요) 있음.","src":"항만운송사업법 시행규칙 제29조의2, 제29조의3"},{"t":"위약금: 화물유치 또는 투자 계획을 이행하지 못한 부두운영회사에 부과할 수 있으나, 귀책사유가 없으면 부과하지 않는다. 연도별로 산정하여 합산. 정부 항만개발 계획 미이행·연기, 불가항력 사유 시 감면.","src":"항만운송사업법 제26조의7, 시행규칙 제29조의4"},{"t":"운영성과 평가: 해양수산부장관이 매년 평가할 수 있다. 관리청등은 평가 결과에 따라 항만시설등의 임대료를 감면하거나 필요한 조치를 할 수 있다.","src":"항만운송사업법 제26조의8"},{"t":"계약 해지 사유(관리청등, 서면 통지): 항만재개발 등 공공 목적으로 계속 임대 곤란 / 임대료 3개월 이상 연체 / 항만시설 멸실 등(귀책 사유의 투자 미이행, 분할 운영 금지 등 금지행위, 협의 사항 불이행).","src":"항만운송사업법 제26조의9, 시행규칙 제29조의5"},{"t":"법에 정하지 않은 부두운영회사의 항만시설 사용은 항만법 또는 항만공사법에 따른다(국유재산법·지방재정법 아님).","src":"항만운송사업법 제26조의10"}]},{"머리":"교육훈련·표준계약서(제27조의3~5)","줄":[{"t":"교육훈련: 안전사고 우려가 높은 작업(부령) 종사자는 해양수산부장관이 실시하는 교육훈련을 받아야 한다. 받지 않으면 해당 작업 종사를 제한(정당한 사유 제외).","src":"항만운송사업법 제27조의3"},{"t":"교육훈련기관: 항만운송사업자·관련사업자에게 고용되거나 역무를 제공하는 자의 교육훈련. 법인. 해양수산부장관의 설립인가를 받아 설립등기로 성립. 운영 경비는 항만운송사업자·항만운송관련사업자 및 교육을 받는 자가 부담(국가 부담 아님). 민법 중 사단법인 규정 준용.","src":"항만운송사업법 제27조의4"},{"t":"교육훈련기관의 사업계획 및 예산안은 다음 해 것을 매년 11월 30일까지, 세입·세출결산서는 다음 해 3월 31일까지 해양수산부장관에게 제출.","src":"기출 2024-29"},{"t":"표준계약서: 해양수산부장관이 작성·보급하고 사용을 권장할 수 있다.","src":"항만운송사업법 제27조의5"}]},{"머리":"항만인력 수급관리협의회·항만운송 분쟁협의회(제27조의7·8)","줄":[{"t":"구성 주체: 항만운송사업자 단체, 항만운송근로자 단체, 그 밖의 대통령령 자(담당 공무원 1명)가 항만별로 구성·운영할 수 있다(업종별 아님, 사업의 종류별 아님).","src":"항만운송사업법 제27조의7·8"},{"t":"구성: 위원장 포함 7명 - 항만운송사업자 단체 추천 3명 + 항만운송근로자 단체 추천 3명 + 공무원 1명. 위원장은 위원 중 호선.","src":"항만운송사업법 시행령 제26조의2, 제26조의5"},{"t":"운영: 위원장이 필요하다고 인정하거나 재적위원 과반수의 요청이 있을 때 소집. 재적위원 3분의 2 이상 출석으로 개의, 출석위원 3분의 2 이상 찬성으로 의결. 분쟁당사자는 회의에 출석해 의견 진술 가능.","src":"항만운송사업법 시행령 제26조의3, 제26조의6"},{"t":"수급관리협의회 협의사항: 적정 근로자 수 산정 / 채용기준 및 교육훈련 등 인사관리 / 위원장이 부치는 사항. 분쟁협의회 협의사항: 항만운송 관련 노사 간 분쟁의 해소 / 분쟁의 예방 등 위원장이 부치는 사항.","src":"항만운송사업법 시행령 제26조의4, 제26조의7"}]},{"머리":"벌칙·과태료","줄":[{"t":"1년 이하 징역/1천만원 이하 벌금: 무등록 항만운송사업 / 검수사등 자격증 양도·양수·대여·알선 / 무등록·무신고 항만운송관련사업(선용품공급업 무신고 포함).","src":"항만운송사업법 제30조"},{"t":"500만원 이하 벌금: 등록·신고한 사항을 위반해 사업 영위 / 변경신고 없이 장비를 추가해 선박연료공급업 영위 / 신고 없이 일시적 영업행위.","src":"항만운송사업법 제31조"},{"t":"300만원 이하 벌금: 검수사등 등록 없이 업무 종사 / 거짓·부정 시험 합격 / 운임·요금 인가·신고 위반 / 사업정지처분 위반.","src":"항만운송사업법 제32조"},{"t":"200만원 이하 과태료: 관리청의 보고·자료제출 요구에 불응하거나 거짓 보고·자료제출 / 관계 공무원의 출입·검사·질문 거부·방해·기피. 관리청이 부과·징수.","src":"항만운송사업법 제34조, 제28조의2"}]}],"함정":[{"x":"항만운송 분쟁협의회는 사업의 종류별로 구성한다.","o":"항만별로 구성한다.","src":"항만운송사업법 제27조의8제1항 / 기출 2022-32"},{"x":"항만운송 분쟁협의회의 회의는 분쟁협의회의 위원장이 필요하다고 인정하거나 재적위원 3분의 1 이상의 요청이 있는 경우에 소집한다.","o":"위원장이 필요하다고 인정하거나 재적위원 과반수의 요청이 있는 경우에 소집한다.","src":"항만운송사업법 시행령 제26조의6제2항 / 기출 2022-32"},{"x":"항만운송 분쟁협의회의 회의는 재적위원 과반수의 출석으로 개의하고, 출석위원 과반수의 찬성으로 의결한다.","o":"재적위원 3분의 2 이상 출석, 출석위원 3분의 2 이상 찬성.","src":"항만운송사업법 시행령 제26조의6제3항 / 기출 2022-32, 2024-27"},{"x":"항만운송과 관련된 노사 간 분쟁의 해소에 관한 사항은 항만운송 분쟁협의회의 심의·의결사항에 포함되지 않는다.","o":"노사 간 분쟁의 해소에 관한 사항이 심의·의결사항이다.","src":"항만운송사업법 시행령 제26조의7제1호 / 기출 2022-32"},{"x":"선박연료공급업을 등록한 자가 사용 장비를 추가하려는 경우에는 사업계획 변경 신고를 하지 않아도 된다.","o":"사업계획 변경신고를 하여야 한다.","src":"항만운송사업법 제26조의3제3항 / 기출 2021-33"},{"x":"항만운송사업의 등록신청인이 법인인 경우 그 법인의 정관은 등록신청시 제출하여야 하는 서류에 포함되지 않는다.","o":"법인이면 정관을 첨부한다.","src":"항만운송사업법 시행규칙 제4조제1항제1호 / 기출 2022-34, 2023-28"},{"x":"검수사등의 자격이 취소된 날부터 3년이 지난 사람은 검수사등의 자격을 취득할 수 없다.","o":"취소된 날부터 2년이 지나지 않은 사람이 취득할 수 없다(3년이 지났으면 취득 가능).","src":"항만운송사업법 제8조제5호 / 기출 2022-34, 2023-28"},{"x":"항만운송사업을 하려는 자는 항만별로 관리청에 등록하여야 한다.","o":"사업의 종류별로 등록하고, 항만별 등록은 항만하역사업과 검수사업에 한한다.","src":"항만운송사업법 제4조 / 기출 2022-34"},{"x":"항만운송사업자가 사업정지명령을 위반하여 그 정지기간에 사업을 계속한 경우는 항만운송사업의 정지사유에 해당한다.","o":"등록을 취소하여야 하는 사유다.","src":"항만운송사업법 제26조제1항제6호 / 기출 2022-34"},{"x":"항만하역사업의 등록을 한 자는 컨테이너 전용 부두에서 취급하는 컨테이너 화물에 대하여 그 운임과 요금을 정하여 관리청의 인가를 받아야 한다.","o":"컨테이너 전용 부두의 컨테이너 화물은 관리청에 신고한다.","src":"항만운송사업법 제10조제2항, 시행규칙 제15조의2 / 기출 2023-28"},{"x":"부두운영회사의 금지행위 위반시 책임에 관한 사항은 부두운영계약에 포함되지 않아도 된다.","o":"계약에 포함되어야 한다.","src":"항만운송사업법 시행규칙 제29조제2호 / 기출 2023-29"},{"x":"부두운영회사가 부두운영 계약기간을 연장하려는 경우에는 그 계약기간이 만료되기 3개월 전까지 부두운영계약의 갱신을 신청하여야 한다.","o":"6개월 전까지 신청한다.","src":"항만운송사업법 시행규칙 제29조의3제1항 / 기출 2023-29, 2025-33"},{"x":"화물유치 또는 투자 계획을 이행하지 못한 부두운영회사에 대하여 부과하는 위약금은 분기별로 산정하여 합산한다.","o":"연도별로 산정하여 합산한다.","src":"항만운송사업법 시행규칙 제29조의4제1항 / 기출 2023-29"},{"x":"항만운송사업법에서 정한 것 외에 부두운영회사의 항만시설 사용에 대해서는 「국유재산법」 또는 「지방재정법」에 따른다.","o":"항만법 또는 항만공사법에 따른다.","src":"항만운송사업법 제26조의10 / 기출 2023-29"},{"x":"교육훈련기관의 운영에 필요한 경비는 대통령령으로 정하는 바에 따라 국가가 부담한다.","o":"항만운송사업자·항만운송관련사업자 및 교육훈련을 받는 자가 부담한다.","src":"항만운송사업법 제27조의4제5항 / 기출 2024-29"},{"x":"항만시설운영자등은 부두운영회사의 운영성과 평가 결과에 따라 부두운영회사에 대하여 항만시설등의 임대료를 감면할 수는 없다.","o":"평가 결과에 따라 임대료를 감면하거나 필요한 조치를 할 수 있다.","src":"항만운송사업법 제26조의8제2항 / 기출 2025-33"},{"x":"항만시설등의 임대료를 2개월 이상 연체한 경우 항만시설운영자등은 부두운영계약을 해지하고, 위약금을 부과한다.","o":"임대료를 3개월 이상 연체한 경우 계약을 해지할 수 있다(위약금은 화물유치·투자 계획 미이행에 대한 것).","src":"항만운송사업법 제26조의9제1항제2호 / 기출 2025-33"},{"x":"항만시설운영자등은 화물유치 또는 투자 계획을 이행하지 못한 부두운영회사에 대하여 그 귀책사유를 불문하고 위약금을 부과할 수 있다.","o":"귀책사유가 없으면 위약금을 부과하지 않는다.","src":"항만운송사업법 제26조의7제1항 단서 / 기출 2025-33"}]},"철도사업법":{"묶음":[{"머리":"정의(제2조)","줄":[{"t":"사업용철도: 철도사업을 목적으로 설치하거나 운영하는 철도. 전용철도: 다른 사람의 수요에 따른 영업을 목적으로 하지 않고 자신의 수요에 따라 특수 목적을 수행하기 위해 설치·운영하는 철도.","src":"철도사업법 제2조제4·5호"},{"t":"철도사업: 다른 사람의 수요에 응하여 철도차량을 사용하여 유상으로 여객이나 화물을 운송하는 사업. 철도사업자: 한국철도공사 및 면허를 받은 자. 전용철도운영자: 전용철도 등록을 한 자.","src":"철도사업법 제2조제6·8·9호"},{"t":"철도운수종사자: 철도운송과 관련하여 승무(동력차 운전·열차 내 승무) 및 역무서비스를 제공하는 직원.","src":"철도사업법 제2조제7호"},{"t":"사업용철도노선 분류: 운행지역·운행거리에 따라 간선철도·지선철도, 운행속도에 따라 고속철도노선·준고속철도노선·일반철도노선. 국토교통부장관이 지정·고시.","src":"철도사업법 제4조"}]},{"머리":"면허(제5~8조)","줄":[{"t":"철도사업 경영: 지정·고시된 사업용철도노선을 정하여 국토교통부장관의 면허(허가·등록 아님). 철도의 공공성·안전 강화와 이용자 편의 증진을 위해 필요한 부담을 붙일 수 있다.","src":"철도사업법 제5조제1항"},{"t":"면허를 받을 수 있는 자는 법인. 사업계획서를 첨부한 면허신청서를 국토교통부장관에게 제출.","src":"철도사업법 제5조제2·3항"},{"t":"면허기준 4가지: 철도교통의 안전에 지장을 줄 염려가 없을 것 / 운행계획이 철도 수송 수요와 수송력 공급 및 이용자 편의에 적합할 것 / 신청자의 재정적 능력 / 철도차량의 대수·사용연한·규격이 부령 기준에 맞을 것. 사업계획서에는 사용할 철도차량의 대수·형식 및 확보계획이 포함.","src":"철도사업법 제6조, 기출 2023-35"},{"t":"면허 결격: 법인의 임원 중 피성년후견인·피한정후견인 / 파산선고 후 미복권자 / 이 법 또는 철도 관계 법령 위반 금고 이상 실형 집행종료·면제 후 2년 미경과 / 같은 법 위반 금고 이상 집행유예 기간 중인 자가 있는 법인. 면허 취소 후 2년 미경과 법인(임원 후견·파산 사유 취소 제외).","src":"철도사업법 제7조"},{"t":"철도 관계 법령(시행령): 철도산업발전 기본법 / 철도안전법 / 도시철도법 / 국가철도공단법 / 한국철도공사법.","src":"철도사업법 시행령 제2조"},{"t":"운송 시작의 의무: 국토교통부장관이 지정하는 날 또는 기간에 운송을 시작. 천재지변 등 불가피한 사유가 있으면 국토교통부장관의 승인을 받아 날짜 연기·기간 연장 가능.","src":"철도사업법 제8조"}]},{"머리":"운임·요금·부가운임(제9~10조)","줄":[{"t":"여객 운임·요금: 철도사업자가 국토교통부장관에게 신고(허가·인가 아님). 변경도 신고. 3일 이내 수리 여부 통지. 시행 1주일 이전에 인터넷 홈페이지·관계 역 등에 게시.","src":"철도사업법 제9조제1·4·5항"},{"t":"여객 운임·요금 결정 시 원가와 다른 교통수단 운임·요금과의 형평성 등 고려. 여객 운임은 국토교통부장관이 지정·고시한 상한을 초과 불가(상한 지정 전 재정경제부장관과 협의).","src":"철도사업법 제9조제2·3항"},{"t":"감면: 재해복구를 위한 긴급지원, 여객 유치를 위한 기념행사, 경영상 필요 시 일정 기간·대상을 정해 감면. 시행 3일 이전에 홈페이지 등에 게시(긴급 시 사전 게시 생략 가능).","src":"철도사업법 제9조의2"},{"t":"부가 운임: 정당한 운임·요금 없이 열차 이용 시 승차 구간 운임 외에 그의 30배의 범위에서 징수. 송하인이 운송장에 적은 내용에 따라 계산한 운임이 정상 운임보다 적으면 부족 운임 외에 그 5배의 범위에서 징수.","src":"철도사업법 제10조제1·2항"},{"t":"부가 운임 징수 절차: 사전에 부가 운임 산정기준(징수 대상 행위, 열차 종류, 운행 구간 등)을 정해 철도사업약관에 포함하여 국토교통부장관에게 신고. 3일 이내 수리 여부 통지.","src":"철도사업법 제10조제3·4항"},{"t":"승차권 부정판매 금지: 상습 또는 영업으로 구입가격을 초과한 금액으로 판매·알선하면 1천만원 이하 과태료.","src":"철도사업법 제10조의2, 제51조"}]},{"머리":"철도사업약관·사업계획 변경·공동운수협정(제11~13조)","줄":[{"t":"철도사업약관: 철도사업자가 정하여 국토교통부장관에게 신고(허가 아님). 변경도 신고. 신고일부터 3일 이내 수리 여부 통지. 미신고·미이행 시 1천만원 이하 과태료.","src":"철도사업법 제11조, 제51조제1항"},{"t":"사업계획 변경: 원칙 신고. 대통령령 중요 사항 변경은 인가. 신고 수리 통지 3일 이내. 변경하려는 날 1개월 전까지(인가사항은 2개월 전까지) 신고서·인가신청서 제출. 인가신청 결과는 신청일부터 1개월 이내 통보.","src":"철도사업법 제12조, 시행규칙 제8조"},{"t":"인가 대상 중요 사항(시행령): 공익서비스비용 보상 계약 체결 벽지 노선의 철도운송서비스 종류 변경·추가 / 여객열차 운행구간의 변경 / 사업용철도노선별 여객열차 정차역 신설·폐지 또는 10분의 2 이상 변경 / 사업용철도노선별 10분의 1 이상 여객열차 운행횟수 변경(공휴일·방학 등 3개월 이내 변경은 제외).","src":"철도사업법 시행령 제5조"},{"t":"사업계획 변경 제한 사유: 지정일에 운송 미시작 / 노선 운행중지·운행제한·감차 변경명령 후 1년 미경과 / 개선명령 불이행 / 철도사고 규모·빈도가 기준 이상(직전 연도 열차운행거리 100만km당 사망자 수 또는 사고 횟수가 최근 5년 평균보다 10분의 2 이상 증가).","src":"철도사업법 제12조제2항, 시행령 제6조"},{"t":"공동운수협정: 다른 철도사업자와의 공동경영 계약 등. 체결·변경은 국토교통부장관의 인가(미리 공정거래위원회와 협의). 경미한 변경(운행구간별 열차 운행횟수 10분의 1 이내 변경, 운임·요금 변경신고 반영 등)은 신고. 신고 통지 3일 이내. 인가 없이 체결·변경 시 1천만원 이하 벌금.","src":"철도사업법 제13조, 시행규칙 제9조, 제49조"}]},{"머리":"양도·양수·합병·휴업·폐업(제14~15조)","줄":[{"t":"사업의 양도·양수: 국토교통부장관의 인가. 다른 철도사업자 또는 철도 외 사업자와 합병도 인가. 양수인·존속법인은 철도사업자 지위 승계. 결격(제7조) 준용. 계약 체결일부터 1개월 이내 인가신청.","src":"철도사업법 제14조, 시행규칙 제10조"},{"t":"휴업·폐업: 전부 또는 일부를 하려면 국토교통부장관의 허가(예정일 3개월 전 신청, 2개월 이내 허가 여부 통지). 선로 또는 교량의 파괴, 철도시설의 개량, 그 밖의 정당한 사유로 휴업하는 경우는 신고(60일 이내 수리 여부 통지).","src":"철도사업법 제15조제1·4항, 시행규칙 제11조"},{"t":"휴업기간은 6개월을 넘을 수 없다. 다만 선로·교량 파괴, 철도시설 개량 등 정당한 사유로 신고하는 휴업은 예외(6개월 초과 가능). 휴업 사유가 소멸되면 신고하고 재개 가능. 허가 후 7일 이내(신고 휴업은 즉시) 휴업·폐업 내용 게시.","src":"철도사업법 제15조제2·3항, 시행령 제7조"}]},{"머리":"면허취소·사업정지·과징금(제16·17조)","줄":[{"t":"취소·정지(국토교통부장관): 면허취소, 6개월 이내 사업의 전부·일부 정지, 노선 운행중지·운행제한·감차 등 사업계획 변경명령. 반드시 취소(제4호·제7호) - 거짓·부정 면허 / 임원 중 결격사유 해당자가 생긴 경우(3개월 이내 교체 시 예외). 취소하려면 청문.","src":"철도사업법 제16조제1·3항"},{"t":"임의 사유: 면허 사항 미시행 / 사업 계속 부적합 / 고의·중과실 철도사고로 다수 사상자(1회 철도사고 사망자 5명 이상) / 면허 부담 위반 / 면허기준 미달(3개월 내 충족 시 예외) / 운송 미시작 / 휴업·폐업 허가·신고 없이 영업 중단 / 준수사항 1년 내 3회 이상 위반 / 개선명령 위반 / 명의 대여.","src":"철도사업법 제16조제1항, 시행령 제8조"},{"t":"과징금: 사업정지처분 갈음, 1억원 이하. 납부 통지를 받은 날부터 20일 이내 납부. 미납 시 국세 체납처분 예에 따라 징수. 분할 납부 규정은 없다. 하나의 위반행위에 정지처분과 과징금을 함께 부과하지 않는다.","src":"철도사업법 제17조, 시행령 제10조"},{"t":"과징금 사용처: 철도사업 종사자 양성·교육훈련·자질향상 시설 및 지도업무 시설의 건설·운영 / 철도사업 경영개선 등 발전 사업 / 이를 위한 보조·융자. 국토교통부장관이 징수금액의 운용계획을 수립·시행.","src":"철도사업법 제17조제4·5항"}]},{"머리":"개선명령·준수사항·책임(제18~24조)","줄":[{"t":"개선명령(국토교통부장관): 사업계획 변경 / 철도차량 및 운송 관련 장비·시설 개선 / 운임·요금 징수 방식 개선 / 철도사업약관 변경 / 공동운수협정 체결 / 철도차량·철도사고 손해배상 보험 가입 / 안전운송 확보·서비스 향상 조치 / 철도운수종사자 양성·자질향상 교육.","src":"철도사업법 제21조"},{"t":"철도사업자 준수사항: 철도안전법 요건 미충족자의 운전업무 종사 금지 / 사업계획 성실 이행, 부당한 운송조건·정당한 사유 없는 계약 거부 금지 / 운임표·요금표·감면 사항·약관 게시 및 비치. 철도차량에 사업자 명칭 등 표시.","src":"철도사업법 제18조, 제20조"},{"t":"명의 대여 금지: 타인에게 자기의 성명 또는 상호를 사용하여 철도사업을 경영하게 해서는 안 된다(2년 이하 징역 또는 2천만원 이하 벌금).","src":"철도사업법 제23조, 제49조"},{"t":"철도운수종사자 금지: 정당한 사유 없이 운송 거부·중도 하차 / 부당한 운임·요금 요구·수령 / 부령 준수사항 위반.","src":"철도사업법 제22조"},{"t":"화물 책임: 멸실·훼손·인도지연에 대한 손해배상책임에 상법 제135조 준용. 인도기한이 지난 후 3개월 이내에 인도되지 않으면 멸실된 것으로 본다.","src":"철도사업법 제24조"},{"t":"철도시설 공동 활용: 선로 및 공동 사용시설(철도역·역 시설, 차량 정비·검사·보관 시설, 사고 복구·구조·피난 설비, 열차 조성·분리 시설, 정보통신 설비)을 관리하는 자는 철도사업자의 요청 시 협정을 체결해 이용하게 하여야 한다. 정당한 사유 없이 거부하면 2년 이하 징역 또는 2천만원 이하 벌금.","src":"철도사업법 제31조, 제49조"}]},{"머리":"민자철도(제25조)","줄":[{"t":"국토교통부장관은 민자철도 유지·관리 및 운영 기준을 정해 고시하고, 매년 소관 민자철도에 대해 운영평가를 실시하여야 한다. 평가 결과에 따라 필요한 조치를 민자철도사업자에게 명할 수 있다.","src":"철도사업법 제25조"},{"t":"운영평가 기준 항목: 철도의 안전성 / 이용자의 편의성 / 민자철도 운영의 효율성. 운영평가계획은 매년 3월 31일까지 수립하고 평가 2주 전까지 민자철도사업자에게 통보. 필요 시 공무원·철도 전문가로 운영 평가단 구성·운영 가능.","src":"철도사업법 시행규칙 제17조"},{"t":"조치명령을 받은 민자철도사업자는 30일 이내에 조치계획을 마련해 제출하고, 명령 이행 후 결과를 보고.","src":"철도사업법 시행규칙 제17조제4항, 제25조제5항"}]},{"머리":"전용철도(제34~41조)","줄":[{"t":"전용철도 운영: 운영계획서를 첨부해 국토교통부장관에게 등록(면허 아님). 등록사항 변경도 등록. 경미한 변경은 예외. 지역적 특성·공익상 필요 시 등록 제한·부담 가능.","src":"철도사업법 제34조"},{"t":"경미한 변경(등록 불요): 운행시간 연장·단축 / 배차간격·운행횟수 단축·연장 / 철도차량 대수 10분의 1 범위 변경 / 주사무소·철도차량기지를 제외한 운송관련 부대시설 변경 / 법인 임원 변경 / 전용철도 건설기간 6월 범위 조정. 차량 대수 10분의 2 변경은 경미하지 않다.","src":"철도사업법 시행령 제12조제1항"},{"t":"결격사유: 제7조제1호 각 목 해당자(법인은 임원) / 이 법에 따른 전용철도 등록이 취소된 후 1년 미경과.","src":"철도사업법 제35조"},{"t":"양도·양수·합병: 신고(인가 아님). 30일 이내 수리 여부 통지. 신고가 수리되면 지위 승계. 결격(제35조) 준용.","src":"철도사업법 제36조"},{"t":"상속: 사망한 날부터 3개월 이내 신고(1개월 이내 아님). 10일 이내 수리 여부 통지. 수리 전까지 피상속인 등록은 상속인 등록으로 본다.","src":"철도사업법 제37조"},{"t":"휴업·폐업: 전부 또는 일부를 휴업·폐업한 경우 1개월 이내에 국토교통부장관에게 신고. 건설기간 연장은 등록(변경등록) 사항이나 경미한 범위는 제외.","src":"철도사업법 제38조, 기출 2021-38, 2022-37"},{"t":"등록 취소·정지(국토교통부장관): 1년 이내 운영 정지. 거짓·부정 등록은 취소하여야 한다. 등록기준 미달·부담 불이행, 휴업·폐업 신고 없이 3개월 이상 운영하지 않음은 임의 사유.","src":"철도사업법 제40조"},{"t":"무등록 전용철도 운영 또는 거짓·부정 등록: 1년 이하 징역 또는 1천만원 이하 벌금.","src":"철도사업법 제49조제2항"}]},{"머리":"점용허가(제42~46조의2)","줄":[{"t":"점용허가: 국토교통부장관이 국가 소유·관리 철도시설에 건물 등 시설물 설치를 허가. 철도사업자와 철도사업자가 출자·보조·출연한 사업을 경영하는 자에게만 허가하며, 시설물의 종류·사업이 철도사업에 지장을 주지 않아야 한다.","src":"철도사업법 제42조"},{"t":"점용허가 기간 상한: 철골조·철근콘크리트조·석조 등 견고한 건물 50년 / 그 외 건물 15년 / 건물 외 공작물 5년(시설물 설치 공사 기간은 산입하지 않음).","src":"철도사업법 시행령 제13조제2항"},{"t":"점용허가 취소(국토교통부장관, 임의): 목적 외 점용 / 철도사업에 지장을 주게 된 경우 / 허가를 받은 날부터 1년 이내 공사 미착수(정당한 사유 시 1년 범위 연장) / 점용료 미납 / 스스로 취소 신청.","src":"철도사업법 제42조의2"},{"t":"점용료: 철도시설의 가액과 사업 매출액 기준. 감면 사유 - 국가에 무상 양도·제공할 시설물 설치 / 그 공사 기간 중 허가 또는 임시 시설물 / 공공주택 건설 / 재해 등으로 점용 목적 달성 불가 / 국민경제에 중대한 영향을 미치는 공익사업. 매년 1월 말까지 해당연도분 선납(부득이한 경우 기한 별도). 미납 시 국세 체납처분 예에 따라 징수.","src":"철도사업법 제44조, 시행령 제14조"},{"t":"변상금: 점용허가 없이 철도시설을 점용한 자에게 점용료의 100분의 120에 해당하는 금액을 징수할 수 있다(과태료·과징금·이행강제금 아님).","src":"철도사업법 제44조의2"},{"t":"권리와 의무의 이전: 국토교통부장관의 인가(신고 아님). 이전하려는 날 3월 전까지 신청. 이전받은 자의 점용허가기간은 이전한 자의 잔여기간.","src":"철도사업법 제45조, 시행령 제15조"},{"t":"원상회복: 점용허가 기간 만료 또는 취소 시 원상으로 회복(만료·폐지일부터 3월 이내). 원상으로 회복할 수 없거나 부적당하면 면제 가능하며 무상 국가귀속을 조건으로 할 수 있다. 불이행 시 행정대집행.","src":"철도사업법 제46조, 시행령 제16조"},{"t":"국가귀속 시설물의 사용허가기간은 10년 이내이며, 10년을 초과하지 않는 범위에서 1회에 한해 갱신할 수 있다.","src":"철도사업법 제46조의2"}]},{"머리":"벌칙·과태료","줄":[{"t":"2년 이하 징역 또는 2천만원 이하 벌금: 무면허 철도사업 / 거짓·부정 면허 / 사업정지기간 중 영업 / 사업계획 변경명령 위반 / 명의 대여 / 시설 공동 활용 거부.","src":"철도사업법 제49조제1항"},{"t":"1천만원 이하 과태료: 여객 운임·요금 신고 불이행 / 약관 미신고·미이행 / 인가·신고 없이 사업계획 변경 / 승차권 부정판매. 500만원 이하: 철도차량 표시 미이행 / 회계 미구분 / 보고·검사 불응. 100만원 이하: 준수사항(제20조 제2~4항) 위반. 50만원 이하: 철도운수종사자 및 소속 철도사업자의 제22조 위반.","src":"철도사업법 제51조"}]}],"함정":[{"x":"철도사업자는 철도사업약관을 정하여 국토교통부장관의 허가를 받아야 한다.","o":"신고하여야 한다.","src":"철도사업법 제11조제1항 / 기출 2021-35"},{"x":"국토교통부장관은 철도사업약관의 변경신고를 받은 날부터 10일 이내에 신고수리 여부를 신고인에게 통지하여야 한다.","o":"3일 이내.","src":"철도사업법 제11조제3항 / 기출 2021-35"},{"x":"철도사업자는 사업용철도노선별로 여객열차의 정차역의 10분의 2를 변경하는 경우 국토교통부장관에게 신고하여야 한다.","o":"정차역 10분의 2 이상 변경은 인가 사항이다.","src":"철도사업법 시행령 제5조제3호 / 기출 2021-35"},{"x":"철도사업자가 사업계획 중 인가사항을 변경하려는 경우에는 사업계획을 변경하려는 날 1개월 전까지 사업계획변경인가신청서를 제출하여야 한다.","o":"인가사항은 2개월 전까지(신고사항은 1개월 전까지).","src":"철도사업법 시행규칙 제8조제1항 / 기출 2021-35"},{"x":"과징금은 철도사업자의 신청에 따라 분할하여 납부할 수 있다.","o":"분할 납부 규정은 없고, 통지를 받은 날부터 20일 이내 납부한다.","src":"철도사업법 시행령 제10조 / 기출 2021-36"},{"x":"철도사업자의 화물의 멸실·훼손에 대한 손해배상책임에 관하여는「상법」제135조(손해배상책임)를 준용하지 않는다.","o":"상법 제135조를 준용한다.","src":"철도사업법 제24조제1항 / 기출 2021-37"},{"x":"철도사업자는 여객에 대한 운임을 변경하려는 경우 국토교통부장관의 허가를 받아야 한다.","o":"신고하여야 한다.","src":"철도사업법 제9조제1항 / 기출 2022-35"},{"x":"철도시설의 개량을 사유로 하는 경우 휴업기간은 6개월을 넘을 수 없다.","o":"철도시설의 개량·선로 또는 교량의 파괴 등 정당한 사유의 휴업(신고)은 6개월 제한의 예외다.","src":"철도사업법 제15조제2항 단서 / 기출 2022-36"},{"x":"철골조 건물의 축조를 목적으로 하는 경우에는 점용허가기간은 20년을 초과하여서는 아니된다.","o":"철골조 등 견고한 건물은 50년 초과 불가.","src":"철도사업법 시행령 제13조제2항제1호 / 기출 2022-38"},{"x":"점용허가를 받은 자가 「공공주택 특별법」에 따른 공공주택을 건설하기 위하여 점용허가를 받은 경우에 해당할 때에는 점용료 감면대상이 될 수 없다.","o":"공공주택 건설을 위한 점용허가는 점용료 감면 대상이다.","src":"철도사업법 제44조제2항제3호 / 기출 2022-38"},{"x":"국토교통부장관은 점용허가를 받지 아니하고 철도시설을 점용한 자에 대하여 점용료의 100분의 150에 해당하는 금액을 변상금으로 징수할 수 있다.","o":"점용료의 100분의 120에 해당하는 금액(현행 조문).","src":"철도사업법 제44조의2 / 기출 2022-38"},{"x":"점용허가로 인하여 발생한 권리와 의무를 이전하려는 경우에는 국토교통부장관에게 신고하여야 한다.","o":"국토교통부장관의 인가를 받아야 한다.","src":"철도사업법 제45조 / 기출 2022-38"},{"x":"법인이 아닌 자도 철도사업의 면허를 받을 수 있다.","o":"법인만 면허를 받을 수 있다.","src":"철도사업법 제5조제3항 / 기출 2023-35"},{"x":"철도사업자는 열차를 이용하는 여객이 정당한 운임·요금을 지급하지 아니하고 열차를 이용한 경우에는 승차 구간에 해당하는 운임 외에 그의 50배의 범위에서 부가 운임을 징수할 수 있다.","o":"30배의 범위.","src":"철도사업법 제10조제1항 / 기출 2023-37, 2025-35"},{"x":"국유철도시설의 점용허가를 받은 자는 부득이한 사유가 없는 한 매년 1월 15일까지 당해연도의 점용료 해당분을 선납하여야 한다.","o":"매년 1월 말까지 선납한다.","src":"철도사업법 시행령 제14조제4항 / 기출 2023-38"},{"x":"국토교통부장관이 민자철도사업자에게 필요한 조치를 명한 경우 해당 민자철도 사업자는 15일 이내에 조치계획을 마련하여 국토교통부장관에게 제출해야 한다.","o":"30일 이내.","src":"철도사업법 시행규칙 제17조제4항 / 기출 2024-36"},{"x":"철도사업자가 인가받은 공동운수협정에 따른 운행구간별 열차 운행횟수를 10분의 1 이내에서 변경하려는 경우에는 국토교통부장관의 변경인가를 받아야 한다.","o":"10분의 1 이내 변경은 경미한 사항으로 신고 사항이다.","src":"철도사업법 시행규칙 제9조제3항제3호 / 기출 2025-36"},{"x":"전용철도를 운영하려는 자는 전용철도 건설기간을 1년 연장한 경우 국토교통부장관에게 신고를 하여야 한다(기출 2021-38 ㄱ).","o":"건설기간 6월 범위 조정만 경미한 변경이므로 1년 연장은 변경등록이 필요하다.","src":"철도사업법 시행령 제12조 / 기출 2021-38"},{"x":"전용철도운영자가 그 운영의 일부를 폐업한 경우에는 15일 이내에 국토교통부장관에게 등록하여야 한다(오답 선지).","o":"1개월 이내에 신고한다.","src":"철도사업법 제38조 / 기출 2021-38"},{"x":"사망한 전용철도운영자의 상속인이 그 전용철도의 운영을 계속하려는 경우에는 피상속인이 사망한 날부터 1개월 이내에 신고하여야 한다(오답 선지).","o":"3개월 이내.","src":"철도사업법 제37조제1항 / 기출 2022-37"},{"x":"전용철도 운영자의 철도차량 대수를 10분의 2의 범위 안에서 변경하는 경우는 경미한 변경이다.","o":"10분의 1 범위 안에서만 경미한 변경.","src":"철도사업법 시행령 제12조제1항제3호 / 기출 2023-36"},{"x":"9월의 범위 안에서 전용철도 건설기간을 조정한 경우는 등록을 하지 않아도 되는 경미한 변경이다.","o":"6월의 범위 안에서만 경미한 변경.","src":"철도사업법 시행령 제12조제1항제6호 / 기출 2024-37"},{"x":"점용허가를 받은 자가 점용허가를 받은 날부터 6개월 이내에 해당 점용허가의 목적이 된 공사에 착수하지 아니한 경우는 점용허가 취소 사유다.","o":"공사 미착수 기간은 1년.","src":"철도사업법 제42조의2제1항제3호 / 기출 2024-38"}]},"농수산물 유통 및 가격안정에 관한 법률":{"묶음":[{"머리":"정의(제2조)","줄":[{"t":"농수산물도매시장: 특별시·광역시·특별자치시·특별자치도 또는 시가 양곡류·청과류·화훼류·조수육류·어류·조개류·갑각류·해조류 및 임산물 등 대통령령 품목의 전부 또는 일부를 도매하게 하기 위해 관할구역에 개설하는 시장.","src":"농수산물 유통 및 가격안정에 관한 법률 제2조제2호"},{"t":"중앙도매시장: 특별시·광역시·특별자치시·특별자치도가 개설한 도매시장 중 해당 관할구역 및 인접지역에서 도매의 중심이 되는 시장으로 부령이 정하는 것(가락동, 노량진, 부산 엄궁동·국제수산, 대구 북부, 인천 남촌·삼산, 광주 각화동, 대전 오정·노은, 울산 등). 지방도매시장은 중앙도매시장 외의 도매시장.","src":"농수산물 유통 및 가격안정에 관한 법률 제2조제3·4호, 시행규칙 제3조"},{"t":"농수산물공판장: 농림수협등(지역농협·지역축협·품목별 협동조합·조합공동사업법인·품목조합연합회·산림조합·수협과 그 중앙회 등), 대통령령 생산자 관련 단체, 공익법인이 시·도지사의 승인을 받아 개설·운영하는 사업장.","src":"농수산물 유통 및 가격안정에 관한 법률 제2조제5호"},{"t":"민영농수산물도매시장: 국가·지방자치단체 및 공판장을 개설할 수 있는 자 외의 자(민간인등)가 시·도지사의 허가를 받아 특별시·광역시·특별자치시·특별자치도 또는 시 지역에 개설하는 시장.","src":"농수산물 유통 및 가격안정에 관한 법률 제2조제6호"},{"t":"도매시장법인: 개설자의 지정을 받아 농수산물을 위탁받아 상장하여 도매하거나 이를 매수하여 도매하는 법인(공공출자법인 포함). 시장도매인: 개설자의 지정을 받아 농수산물을 매수 또는 위탁받아 도매하거나 매매를 중개하는 영업을 하는 법인.","src":"농수산물 유통 및 가격안정에 관한 법률 제2조제7·8호"},{"t":"중도매인: 개설자의 허가 또는 지정을 받아 상장된 농수산물을 매수하여 도매하거나 매매를 중개, 또는 개설자의 허가를 받은 비상장 농수산물을 매수·위탁받아 도매·중개하는 자. 매매참가인: 개설자에게 신고하고 상장 농수산물을 직접 매수하는 중도매인이 아닌 가공업자·소매업자·수출업자·소비자단체 등 수요자.","src":"농수산물 유통 및 가격안정에 관한 법률 제2조제9·10호"},{"t":"산지유통인: 개설자에게 등록하고 농수산물을 수집하여 시장에 출하하는 영업을 하는 자. 경매사: 도매시장법인(또는 공판장·민영도매시장 개설자)의 임명을 받아 상장 농수산물의 가격 평가 및 경락자 결정 등을 수행하는 자. 농수산물종합유통센터: 국가·지방자치단체가 설치하거나 지원받아 설치된, 출하 경로 다원화·물류비용 절감을 위한 시설을 갖춘 사업장.","src":"농수산물 유통 및 가격안정에 관한 법률 제2조제11~13호"}]},{"머리":"도매시장의 개설(제17~19조)","줄":[{"t":"개설 주체: 중앙도매시장은 특별시·광역시·특별자치시·특별자치도가, 지방도매시장은 특별시·광역시·특별자치시·특별자치도 또는 시가 개설. 부류별로 또는 둘 이상의 부류를 종합하여 개설. 부류: 양곡·청과·축산·수산·화훼·약용작물부류.","src":"농수산물 유통 및 가격안정에 관한 법률 제17조제1항, 기출 2021-39"},{"t":"시가 지방도매시장을 개설하려면 도지사의 허가(신고 아님). 허가신청서에 업무규정과 운영관리계획서 첨부.","src":"농수산물 유통 및 가격안정에 관한 법률 제17조제1·3항"},{"t":"특별시·광역시·특별자치시·특별자치도가 개설하려면 미리 업무규정과 운영관리계획서 작성. 중앙도매시장의 업무규정은 농림축산식품부장관 또는 해양수산부장관의 승인. 업무규정 변경도 같다(지방도매시장은 시가 개설자인 경우 도지사 승인).","src":"농수산물 유통 및 가격안정에 관한 법률 제17조제4·5항"},{"t":"폐쇄: 시가 지방도매시장을 폐쇄하려면 3개월 전에 도지사의 허가. 특별시·광역시·특별자치시·특별자치도가 폐쇄하는 경우 3개월 전에 공고.","src":"농수산물 유통 및 가격안정에 관한 법률 제17조제6항"},{"t":"도매시장의 명칭에는 개설한 지방자치단체의 명칭이 포함되어야 한다(기출).","src":"기출 2021-39"},{"t":"개설구역: 개설되는 지방자치단체 관할구역. 농림축산식품부장관 또는 해양수산부장관은 인접 구역을 개설구역으로 편입하게 할 수 있다. 시가 개설하는 지방도매시장의 인접 구역으로 그 도의 일정 구역은 도지사가 편입하게 할 수 있다.","src":"농수산물 유통 및 가격안정에 관한 법률 제18조"},{"t":"도지사의 허가요건: 농수산물 거래의 중심지로서 적절한 위치 / 시설기준에 적합 / 운영관리계획서 내용이 충실하고 실현이 확실. 시설 미비 시 기간 내 갖출 것을 조건으로 허가 가능.","src":"농수산물 유통 및 가격안정에 관한 법률 제19조"},{"t":"개설자의 의무: 시설의 정비·개선과 합리적 관리 / 경쟁 촉진과 공정한 거래질서 확립 및 환경 개선 / 상품성 향상을 위한 규격화, 포장 개선 및 선도 유지의 촉진. 투자계획 등 대책을 수립·시행.","src":"농수산물 유통 및 가격안정에 관한 법률 제20조"},{"t":"관리: 개설자는 관리사무소를 두거나 관리공사·공공출자법인·한국농수산식품유통공사 중에서 시장관리자를 지정할 수 있다.","src":"농수산물 유통 및 가격안정에 관한 법률 제21조"},{"t":"운영: 시설규모·거래액 등을 고려해 적정 수의 도매시장법인·시장도매인·중도매인을 두어 운영하게 한다. 중앙도매시장의 개설자는 청과부류와 수산부류에 대해서는 도매시장법인을 두어야 한다(양곡부류 아님).","src":"농수산물 유통 및 가격안정에 관한 법률 제22조, 시행규칙 제18조의2"}]},{"머리":"도매시장법인(제23~24조)","줄":[{"t":"지정: 개설자가 부류별로 공모하여 지정. 중앙도매시장은 농림축산식품부장관 또는 해양수산부장관과 협의하여 지정. 지정 유효기간 5년 이상 10년 이하의 범위에서 설정 가능.","src":"농수산물 유통 및 가격안정에 관한 법률 제23조제1항"},{"t":"재지정: 유효기간 만료 90일 전까지 신청. 3년 이상 5년 이하의 범위에서 유효기간 설정(중앙도매시장은 장관과 협의). 지정·재지정 시 가격 안정·농어업인 권익보호·도매유통 발전을 위한 지정조건 부여 가능.","src":"농수산물 유통 및 가격안정에 관한 법률 제23조제6~8항"},{"t":"법인 요건: 해당 부류 도매 지식과 도매시장·공판장 업무 2년 이상 종사한 경험이 있는 업무집행 담당 임원 2명 이상 / 임원 중 이 법 위반 금고 이상 실형 집행종료·면제 후 2년 미경과자 없을 것 / 임원 중 파산선고 후 미복권자·피성년후견인·피한정후견인 없을 것 / 임원 중 지정취소 원인 관련자 없을 것 / 거래규모·순자산액 비율·거래보증금 등 업무규정 요건.","src":"농수산물 유통 및 가격안정에 관한 법률 제23조제3항"},{"t":"지정 후 임원 요건(제1호) 미충족 시 3개월 이내 충족. 임원이 제2~4호 요건을 잃으면 지체 없이 해임.","src":"농수산물 유통 및 가격안정에 관한 법률 제23조제4·5항"},{"t":"도매시장법인의 주주 및 임직원은 해당 법인 업무와 경합되는 도매업 또는 중도매업을 해서는 안 된다(다른 법인을 과반수 인수한 경우 겸임은 예외).","src":"농수산물 유통 및 가격안정에 관한 법률 제23조제2항"},{"t":"인수·합병: 해당 도매시장 개설자의 승인을 받아야 한다(신고 아님). 개설자는 요건 미충족 등 제외하고는 승인하여야 한다. 합병하는 법인이 소멸 법인의 지위 승계. 법인인 중도매인·시장도매인의 인수·합병에도 준용.","src":"농수산물 유통 및 가격안정에 관한 법률 제23조의2, 제25조의2, 제36조의2"},{"t":"공공출자법인: 개설자가 도매시장법인을 갈음해 업무를 수행하게 설립. 출자 대상: 지방자치단체·관리공사·농림수협등·상인과 상인단체·도매시장법인 등. 처음 세 부류의 출자액 합계가 총출자액의 100분의 50 초과. 상법상 주식회사 규정 적용. 설립등기일에 도매시장법인 지정을 받은 것으로 본다.","src":"농수산물 유통 및 가격안정에 관한 법률 제24조"},{"t":"영업제한: 도매시장 외의 장소에서 판매업무 불가. 전자거래·견본거래(개설자 사전승인)는 예외. 판매업무 외 사업 겸영 불가(선별·포장·가공·제빙·보관·후숙·저장·수출입 등은 부령에 따라 겸영 가능, 개설자가 1년 이내 제한 가능).","src":"농수산물 유통 및 가격안정에 관한 법률 제35조"},{"t":"수탁판매 원칙: 도매시장법인의 도매는 출하자로부터 위탁받아 한다. 부령이 정하는 특별한 사유가 있을 때만 매수하여 도매할 수 있다.","src":"농수산물 유통 및 가격안정에 관한 법률 제31조제1항"}]},{"머리":"시장도매인(제36조)","줄":[{"t":"지정: 개설자가 부류별로 지정. 유효기간 5년 이상 10년 이하의 범위에서 설정 가능.","src":"농수산물 유통 및 가격안정에 관한 법률 제36조제1항"},{"t":"법인 요건: 임원 중 이 법 위반 금고 이상 실형 집행종료·면제 후 2년 미경과자 없을 것 / 임원 중 해당 도매시장에서 경합되는 도매업·중도매업 종사자 없을 것 / 임원 중 파산·피성년후견인·피한정후견인 없을 것 / 지정취소 원인 관련자 없을 것 / 업무규정 요건. 임원이 요건을 잃으면 지체 없이 해임.","src":"농수산물 유통 및 가격안정에 관한 법률 제36조제2·3항"}]},{"머리":"중도매업·매매참가인·경매사·산지유통인(제25~30조)","줄":[{"t":"중도매업은 부류별로 해당 도매시장 개설자의 허가. 개설자는 결격·제한 위반 사유가 없으면 허가 및 갱신허가를 하여야 한다.","src":"농수산물 유통 및 가격안정에 관한 법률 제25조제1·2항"},{"t":"중도매업 허가를 받을 수 없는 자: 파산선고 후 미복권자·피성년후견인 / 이 법 위반 금고 이상 실형의 집행이 끝나지 않았거나 면제되지 않은 사람 / 허가취소 후 2년 미경과자 / 도매시장법인의 주주·임직원으로 경합되는 중도매업을 하려는 자 / 임원 중 위 해당자가 있는 법인 / 최저거래금액·보증금 등 업무규정 허가조건 미충족자.","src":"농수산물 유통 및 가격안정에 관한 법률 제25조제3항"},{"t":"법인인 중도매인은 임원이 결격에 해당하게 되면 지체 없이 해임. 중도매인 금지: 다른 중도매인·매매참가인 거래 참가 방해, 집단적 경매·입찰 불참 / 성명·상호 사용 허용, 허가증 대여.","src":"농수산물 유통 및 가격안정에 관한 법률 제25조제4·5항"},{"t":"중도매업 허가 유효기간: 5년 이상 10년 이하(법인이 아닌 중도매인은 3년 이상 10년 이하). 갱신허가는 만료 30일 전까지 신청, 갱신 시 구 허가증 회수 후 새 허가증 발급.","src":"농수산물 유통 및 가격안정에 관한 법률 제25조제6·7항, 시행규칙 제19조"},{"t":"중도매인 거래: 도매시장법인이 상장한 농수산물 외 거래 불가(부령 예외로 허가받은 비상장 품목은 가능). 다른 중도매인과의 거래는 연간 거래액 범위 내에서만.","src":"농수산물 유통 및 가격안정에 관한 법률 제31조제2·5항"},{"t":"매매참가인: 개설자에게 신고.","src":"농수산물 유통 및 가격안정에 관한 법률 제25조의3"},{"t":"경매사: 도매시장법인이 2명 이상(업무규정으로 정함)을 둔다. 경매사 자격시험 합격자로서 결격(피성년후견인·피한정후견인 / 이 법 또는 형법 제129~132조 죄 금고 이상 실형 집행 후 2년 미경과 / 집행유예·선고유예 중 / 해당 시장의 시장도매인·중도매인·산지유통인 또는 임직원 / 면직 후 2년 미경과 / 업무정지 중) 사유가 없는 자. 임면하면 30일 이내 개설자에게 신고(미신고 100만원 이하 과태료).","src":"농수산물 유통 및 가격안정에 관한 법률 제27조, 시행규칙 제20조"},{"t":"경매사 업무: 경매 우선순위 결정 / 가격평가 / 경락자 결정 / 정가매매·수의매매에 대한 협상 및 중재. 형법 제129~132조 적용에서는 공무원으로 본다.","src":"농수산물 유통 및 가격안정에 관한 법률 제28조"},{"t":"산지유통인: 농수산물을 수집해 도매시장에 출하하려면 부류별로 개설자에게 등록. 등록 예외 - 생산자단체가 구성원 생산물을 출하 / 도매시장법인이 예외적으로 매수한 농수산물 상장 / 중도매인의 비상장 거래 / 시장도매인의 매매 / 종합유통센터·수출업자 잔량 상장 등. 도매시장법인·중도매인과 그 주주·임직원은 해당 시장에서 산지유통인 업무 금지. 출하업무 외 판매·매수·중개 금지.","src":"농수산물 유통 및 가격안정에 관한 법률 제29조, 시행규칙 제25조"},{"t":"출하자 신고: 도매시장에 출하하려는 생산자·생산자단체 등은 개설자에게 신고. 신고한 출하자는 위탁수수료 인하·경매 우선 실시 등 우대 가능.","src":"농수산물 유통 및 가격안정에 관한 법률 제30조"}]},{"머리":"공판장(제43~46조)","줄":[{"t":"개설: 농림수협등, 생산자단체 또는 공익법인이 시·도지사의 승인(허가·신고 아님). 승인신청서에 업무규정과 운영관리계획서 등 첨부(시·군·구 의견서는 민영도매시장 허가 신청 서류).","src":"농수산물 유통 및 가격안정에 관한 법률 제43조, 시행규칙 제40조·제41조"},{"t":"승인 제한사유: 교통체증을 유발할 수 있는 위치 / 시설이 기준에 부적합 / 운영관리계획서 내용 실현 불가능 / 법령상 제한 위반. 이 외에는 승인하여야 한다.","src":"농수산물 유통 및 가격안정에 관한 법률 제43조제4항"},{"t":"공판장 거래 관계자: 중도매인, 매매참가인, 산지유통인 및 경매사를 둘 수 있다. 중도매인은 공판장 개설자가 지정, 경매사는 공판장 개설자가 임면, 산지유통인은 개설자에게 등록. 업무규정 변경은 시·도지사에게 보고.","src":"농수산물 유통 및 가격안정에 관한 법률 제44조, 기출 2024-40"},{"t":"도매시장공판장은 농림수협등의 유통자회사(상법상 회사)로 하여금 운영하게 할 수 있다.","src":"농수산물 유통 및 가격안정에 관한 법률 제46조제5항, 제70조"}]},{"머리":"민영도매시장(제47~48조)","줄":[{"t":"개설: 민간인등이 특별시·광역시·특별자치시·특별자치도 또는 시 지역에 개설하려면 시·도지사의 허가(농림축산식품부장관 아님). 신청서에 업무규정과 운영관리계획서 첨부, 소재지 관할 시장 또는 구청장의 의견서 첨부.","src":"농수산물 유통 및 가격안정에 관한 법률 제47조제1·2항, 시행규칙 제41조"},{"t":"허가 제한사유는 공판장과 같음(교통체증 유발 위치, 시설기준 부적합, 계획 실현 불가능, 법령 제한 위반). 허가 처리기간 30일 이내 허가 여부 또는 지연 사유 통보, 지연 시 10일 범위에서 한 번만 연장. 통보하지 않으면 처리기간 마지막 날의 다음 날 허가한 것으로 본다.","src":"농수산물 유통 및 가격안정에 관한 법률 제47조제4~6항"},{"t":"운영: 개설자가 중도매인·매매참가인·산지유통인·경매사를 두어 직접 운영하거나 시장도매인을 두어 운영하게 할 수 있다. 중도매인은 민영도매시장 개설자가 지정, 경매사는 개설자가 임면, 시장도매인은 개설자가 지정.","src":"농수산물 유통 및 가격안정에 관한 법률 제48조"}]},{"머리":"농산물가격안정기금(제54~61조)","줄":[{"t":"설치: 정부가 농산물(축산물·임산물 포함)의 원활한 수급과 가격안정, 유통구조 개선을 위해 설치. 농림축산식품부장관이 국가회계원칙에 따라 운용·관리하며, 업무 일부를 국립종자원장과 한국농수산식품유통공사 장에게 위임·위탁 가능.","src":"농수산물 유통 및 가격안정에 관한 법률 제54조, 제56조"},{"t":"재원: 정부의 출연금 / 기금 운용 수익금 / 몰수농산물등 처분금·수입이익금 등 다른 법률에 따라 납입되는 금액 / 다른 기금으로부터의 출연금. 한국은행 또는 다른 기금으로부터 차입 가능.","src":"농수산물 유통 및 가격안정에 관한 법률 제55조"},{"t":"융자·대출 사업: 농산물의 가격조절과 생산·출하 조절 / 농산물의 수출 촉진 / 보관·관리 및 가공 / 도매시장·공판장·민영도매시장·경매식 집하장의 출하촉진·거래대금정산·운영·시설설치 / 상품성 향상 / 그 밖에 필요하다고 인정하는 사업. 융자를 받을 수 있는 자: 농업협동조합중앙회·산림조합중앙회·한국농수산식품유통공사.","src":"농수산물 유통 및 가격안정에 관한 법률 제57조제1·3항"},{"t":"지출 사업: 농수산자조금 출연·지원 / 안정 생산·공급지원사업 / 농산물 수급관리센터 설치·운영 / 계약거래 지원 / 가격안정 사업 / 유통명령 이행자 지원 / 농산물가격안정제도 운영 / 기금 관리 유통시설 설치·운영 / 도매시장 시설현대화 지원 등.","src":"농수산물 유통 및 가격안정에 관한 법률 제57조제2항"},{"t":"여유자금 운용: 은행 예치 / 국채·공채, 그 밖에 자본시장법 제4조의 증권 매입. 융자기간은 1년 이내(시설자금 등은 예외). 농림축산식품부장관이 회계연도마다 기금운용계획 수립.","src":"농수산물 유통 및 가격안정에 관한 법률 제60조, 제60조의2"}]},{"머리":"허가취소·정지·과징금(제82·83조)","줄":[{"t":"도매시장법인등 업무정지·지정취소(농림축산식품부장관·해양수산부장관·시·도지사·개설자): 6개월 이내 업무정지 또는 지정 취소. 업무정지 처분을 받고 정지 기간 중 업무를 한 경우는 지정·승인을 취소하여야 한다.","src":"농수산물 유통 및 가격안정에 관한 법률 제82조제2항"},{"t":"중도매인·산지유통인(개설자): 6개월 이내 업무정지 또는 허가·등록 취소. 업무정지 중 업무를 한 경우는 취소하여야 한다.","src":"농수산물 유통 및 가격안정에 관한 법률 제82조제5항"},{"t":"경매사: 고의·중대한 과실로 경매 우선순위·가격평가·경락자·정가/수의매매를 잘못한 경우 6개월 이내 업무정지 또는 면직 명령.","src":"농수산물 유통 및 가격안정에 관한 법률 제82조제4항"},{"t":"과징금: 업무정지에 갈음해 도매시장법인등 1억원 이하, 중도매인 1천만원 이하.","src":"농수산물 유통 및 가격안정에 관한 법률 제83조"}]},{"머리":"벌칙·과태료","줄":[{"t":"2년 이하 징역/2천만원 이하 벌금: 수입 용도 외 사용 / 허가 없이 지방도매시장·민영도매시장 개설 / 지정·재지정 없이 도매시장법인 업무 / 허가 없이 중도매인 업무 / 등록 없이 산지유통인 업무 / 도매시장 외 판매·판매업무 외 겸영 / 지정 없이 시장도매인 업무 / 승인 없이 공판장 개설 / 업무정지 중 계속 영업.","src":"농수산물 유통 및 가격안정에 관한 법률 제86조"},{"t":"과태료: 1천만원 이하(유통명령 위반 등), 500만원 이하(포전매매 서면계약 위반 매수인, 단속 기피, 보고 불이행·허위), 100만원 이하(경매사 임면 신고 불이행 등).","src":"농수산물 유통 및 가격안정에 관한 법률 제90조"}]}],"함정":[{"x":"시가 지방도매시장을 개설하려면 도지사에게 신고하여야 한다.","o":"도지사의 허가를 받아야 한다.","src":"농수산물 유통 및 가격안정에 관한 법률 제17조제1항 / 기출 2021-39"},{"x":"공익법인이 운영하는 공판장의 개설승인 신청서에는 해당 공판장의 소재지를 관할하는 시장 또는 자치구의 구청장의 의견서를 첨부하여야 한다.","o":"공판장 개설승인 신청서에는 업무규정과 운영관리계획서를 첨부한다(의견서는 민영도매시장 허가 신청 서류).","src":"농수산물 유통 및 가격안정에 관한 법률 시행규칙 제40조·제41조 / 기출 2021-40"},{"x":"다른 기금으로부터의 출연금은 농산물가격안정기금의 재원으로 할 수 없다.","o":"다른 기금으로부터의 출연금도 재원이다.","src":"농수산물 유통 및 가격안정에 관한 법률 제55조제1항제4호 / 기출 2022-39"},{"x":"농산물의 수출 촉진사업을 위하여 농산물가격안정기금을 대출할 수 없다.","o":"농산물의 수출 촉진은 기금의 융자·대출 사업이다.","src":"농수산물 유통 및 가격안정에 관한 법률 제57조제1항제2호 / 기출 2022-39"},{"x":"농림축산식품부장관은 농산물가격안정기금의 여유자금의 운용에 관한 업무를 농업정책보험금융원의 장에게 위탁한다.","o":"기금 운용·관리 업무 일부는 국립종자원장과 한국농수산식품유통공사 장에게 위임·위탁할 수 있다.","src":"농수산물 유통 및 가격안정에 관한 법률 제56조제3항 / 기출 2022-39"},{"x":"농림축산식품부장관은 농산물가격안정기금의 수입과 지출을 명확히 하기 위하여 농협은행에 기금계정을 설치하여야 한다.","o":"기금의 수입·지출 사무는 소속 공무원 중 기금수입징수관 등을 임명해 수행하게 한다(농협은행 기금계정 설치 규정 없음).","src":"농수산물 유통 및 가격안정에 관한 법률 제58조 / 기출 2022-39"},{"x":"도매시장은 중앙도매시장의 경우에는 시·도가 개설하고, 지방도매시장의 경우에는 시·군·구가 개설한다.","o":"중앙도매시장은 특별시·광역시·특별자치시·특별자치도가, 지방도매시장은 특별시·광역시·특별자치시·특별자치도 또는 시가 개설한다(군·구는 개설 주체가 아님).","src":"농수산물 유통 및 가격안정에 관한 법률 제17조제1항 / 기출 2022-40"},{"x":"중앙도매시장의 개설자가 업무규정을 변경하는 때에는 농림축산식품부장관 또는 산업통상자원부장관의 승인을 받아야 한다.","o":"농림축산식품부장관 또는 해양수산부장관의 승인.","src":"농수산물 유통 및 가격안정에 관한 법률 제17조제5항 / 기출 2022-40"},{"x":"도매시장법인은 도매시장 개설자가 부류별로 지정하되, 3년 이상 10년 이하의 범위에서 지정 유효기간을 설정할 수 있다.","o":"5년 이상 10년 이하(재지정은 3년 이상 5년 이하).","src":"농수산물 유통 및 가격안정에 관한 법률 제23조제1항·제7항 / 기출 2022-40, 2023-40"},{"x":"도매시장법인이 다른 도매시장법인을 인수하거나 합병하는 경우에는 해당 도매시장 개설자에게 신고하여야 한다.","o":"해당 도매시장 개설자의 승인을 받아야 한다.","src":"농수산물 유통 및 가격안정에 관한 법률 제23조의2제1항 / 기출 2022-40, 2025-39"},{"x":"도매시장 개설자는 법인인 중도매인에게 중도매업의 허가를 하는 경우 3년 이상 10년 이하의 범위에서 허가 유효기간을 설정할 수 있다.","o":"법인인 중도매인은 5년 이상 10년 이하(3년 이상은 법인이 아닌 중도매인).","src":"농수산물 유통 및 가격안정에 관한 법률 제25조제6항 / 기출 2024-39"},{"x":"생산자단체가 구성원의 농수산물을 공판장에 출하하는 경우 공판장의 개설자에게 산지유통인으로 등록하여야 한다.","o":"생산자단체가 구성원의 생산물을 출하하는 경우는 산지유통인 등록 예외다.","src":"농수산물 유통 및 가격안정에 관한 법률 제29조제1항제1호(제44조제3항 준용) / 기출 2024-40"},{"x":"중앙도매시장의 개설자는 양곡부류와 수산부류에 대하여는 도매시장법인을 두어야 한다.","o":"청과부류와 수산부류에 대하여 도매시장법인을 두어야 한다.","src":"농수산물 유통 및 가격안정에 관한 법률 시행규칙 제18조의2 / 기출 2025-39, 2023-40"},{"x":"민간인등이 광역시 지역에 민영도매시장을 개설하려면 농림축산식품부장관의 허가를 받아야 한다.","o":"시·도지사의 허가를 받아야 한다.","src":"농수산물 유통 및 가격안정에 관한 법률 제47조제1항 / 기출 2023-39"},{"x":"시·도지사가 민영도매시장 개설 허가 처리기간에 허가 여부를 통보하지 아니하면 허가 처리기간의 마지막 날에 허가를 한 것으로 본다.","o":"마지막 날의 다음 날 허가한 것으로 본다.","src":"농수산물 유통 및 가격안정에 관한 법률 제47조제5항 / 기출 2023-39"},{"x":"민영도매시장의 개설자는 시장도매인을 두어 민영도매시장을 운영하게 할 수 없다.","o":"시장도매인을 두어 운영하게 할 수 있다.","src":"농수산물 유통 및 가격안정에 관한 법률 제48조제1항 / 기출 2023-39"},{"x":"민영도매시장의 중도매인은 해당 민영도매시장을 관할하는 시·도지사가 지정한다.","o":"민영도매시장 개설자가 지정한다.","src":"농수산물 유통 및 가격안정에 관한 법률 제48조제2항 / 기출 2023-39"},{"x":"농림수협등의 유통자회사(流通子會社)는 도매시장공판장을 운영할 수 없다.","o":"도매시장공판장을 운영하게 할 수 있다.","src":"농수산물 유통 및 가격안정에 관한 법률 제46조제5항, 제70조 / 기출 2025-40"}]}};
